// 《雅韻文齋》歷史經典成語典故語料庫（500 則依文獻與考查頻率降序）
window.CORPUS_IDIOMS = [{"rank": 500, "idiom": "管鮑之交", "pinyin": "guǎn bào zhī jiāo", "origin": "《列子·力命》/《史記·管晏列傳》", "story": "齊國管仲與鮑叔牙為至交。管仲貧困時與鮑叔牙經商，分財自取多，鮑叔不以為貪，知其貧也；管仲三戰三走，鮑叔不以為怯，知其有老母也。及齊桓公即位，鮑叔薦管仲為相，卒成霸業。管仲曰：『生我者父母，知我者鮑子也。』", "quote": "生我者父母，知我者鮑子也。", "desc": "比喻友誼無私深厚，彼此深知相諒。", "yin": "guǎn bào zhī jiāo"}, {"rank": 499, "idiom": "退避三舍", "pinyin": "tuì bì sān shè", "origin": "《左傳·僖公二十三年》", "story": "晉公子重耳流亡楚國，楚成王厚禮待之。王問：『公子若反晉國，何以報我？』重耳對曰：『若以君之靈得反晉國，晉楚治兵，遇於中原，其辟君三舍。』古者行軍三十里為一舍，退避三舍即九十里。後城濮之戰，晉軍果退三舍以示守諾，大敗楚軍。", "quote": "晉楚治兵，遇於中原，其辟君三舍。", "desc": "比喻退讓遷就，避免衝突以示守信有禮。", "yin": "tuì bì sān shè"}, {"rank": 498, "idiom": "完璧歸趙", "pinyin": "wán bì guī zhào", "origin": "《史記·廉頗藺相如列傳》", "story": "趙惠文王得楚和氏璧，秦昭王願以十五城易之。趙王患秦詐，相如毅然奉璧西使。見秦王無償城意，相如仗義斥秦，持璧倚柱曰：『大王必欲急臣，臣頭今與璧俱碎於柱矣！』終以大智大勇將寶璧完好送返趙國。", "quote": "城入趙而璧留秦；城不入，臣請完璧歸趙。", "desc": "比喻把原物完好無缺地歸還原主。", "yin": "wán bì guī zhào"}, {"rank": 497, "idiom": "負荊請罪", "pinyin": "fù jīng qǐng zuì", "origin": "《史記·廉頗藺相如列傳》", "story": "藺相如立澠池之功，位居廉頗之上。廉頗怒曰：『我為趙將，有攻城野戰之大功，相如徒以口舌為勞，而位居我上！我見相如，必辱之。』相如聞之，每出引車避匿，曰：『吾所以為此者，以先國家之急而後私讎也！』廉頗聞之大慚，肉袒負荊，至門謝罪。", "quote": "先國家之急而後私讎也。", "desc": "比喻向人認錯賠罪，坦誠悔過。", "yin": "fù jīng qǐng zuì"}, {"rank": 496, "idiom": "臥薪嚐膽", "pinyin": "wò xīn cháng dǎn", "origin": "《史記·越王句踐世家》", "story": "吳王夫差敗越於夫椒，越王句踐棲於會稽，入臣於吳為奴三年，深自怨抑。既歸國，身踐焦勞，苦身深思，置膽於坐，坐臥即仰膽，飲食亦嚐膽也。曰：『女忘會稽之厄邪？』親率士卒耕作，二十年休養生息，終滅吳稱霸。", "quote": "越王句踐反國，乃苦身焦思，置膽於坐，坐臥即仰膽，飲食亦嚐膽也。", "desc": "形容刻苦自勵，發憤雪恥。", "yin": "wò xīn cháng dǎn"}, {"rank": 495, "idiom": "破釜沉舟", "pinyin": "pò fǔ chén zhōu", "origin": "《史記·項羽本紀》", "story": "鉅鹿之戰，項羽領兵救鉅鹿。引兵渡漳水，令士卒：『皆沉船，破釜甑，燒廬舍，持三日糧，以示士卒必死，無一還心。』楚兵以一當十，呼聲動天，諸侯軍皆震恐壁上觀。九戰絕其甬道，大破秦軍章邯、王離，威震天下。", "quote": "項羽乃悉引兵渡河，皆沉船，破釜甑，燒廬舍，持三日糧，以示士卒必死，無一還心。", "desc": "比喻下定必死決心，誓不回顧。", "yin": "pò fǔ chén zhōu"}, {"rank": 494, "idiom": "圍魏救趙", "pinyin": "wéi wèi jiù zhào", "origin": "《史記·孫子吳起列傳》", "story": "魏龐涓攻趙，圍邯鄲。齊威王命田忌、孫臏救趙。孫臏曰：『夫解雜亂紛糾者不控捲，救鬭者不搏撠。今梁趙相攻，輕兵銳卒必竭於外，老弱罷於內。君不若引兵疾走大梁，據其街路，衝其方虛，彼必釋趙而自救。』田忌從之，龐涓果去邯鄲，齊軍迎擊於桂陵，大破魏軍。", "quote": "批亢擣虛，引兵疾走大梁，彼必釋趙而自救。", "desc": "指襲擊敵方要害以解他處之危的避實擊虛戰法。", "yin": "wéi wèi jiù zhào"}, {"rank": 493, "idiom": "毛遂自薦", "pinyin": "máo suí zì jiàn", "origin": "《史記·平原君虞卿列傳》", "story": "秦圍邯鄲，趙遣平原君求救於楚，約合從。平原君欲選門下文武備具者二十人俱，得十九人，餘無可取者。毛遂自薦曰：『遂聞君將合從於楚，願借遂得處囊中以脫穎而出。』平原君笑曰：『夫賢士之處世，譬如錐之處囊中，其末立見。先生處勝之門下三年於此矣，未有所聞。』遂曰：『臣乃今日請處囊中耳！使遂蚤得處囊中，乃穎脫而出，非特其末見而已。』後遂定楚從。", "quote": "使遂蚤得處囊中，乃穎脫而出，非特其末見而已。", "desc": "比喻自告奮勇，毛遂自薦擔任重任。", "yin": "máo suí zì jiàn"}, {"rank": 492, "idiom": "價值連城", "pinyin": "jià zhí lián chéng", "origin": "《史記·廉頗藺相如列傳》", "story": "趙惠文王時，得楚人和氏璧。秦昭王聞之，使人遺趙王書，願以十五城請易璧。趙王與大將軍廉頗諸大臣謀：欲予秦，秦城恐不可得，徒見欺；欲勿予，即患秦兵之來。藺相如奉璧往使，終保國珍不失。", "quote": "趙惠文王時，得楚人和氏璧。秦昭王聞之，使人遺趙王書，願以十五城請易璧。", "desc": "形容物品極其珍貴難得。", "yin": "jià zhí lián chéng"}, {"rank": 491, "idiom": "楚河漢界", "pinyin": "chǔ hé hàn jiè", "origin": "《史記·項羽本紀》", "story": "楚漢相持於滎陽、成皋間，羽與漢王劉邦約天下：中分天下，割鴻溝以西者為漢，鴻溝以東者為楚。項羽乃歸漢王父母妻子。軍皆呼萬歲。後象棋棋盤正中遂標『楚河漢界』，象徵涇渭分明、壁壘對峙。", "quote": "項王乃與漢約，中分天下，割鴻溝以西者為漢，鴻溝以東者為楚。", "desc": "比喻雙方界線極為分明，互相對立。", "yin": "chǔ hé hàn jiè"}, {"rank": 490, "idiom": "揭竿而起", "pinyin": "jiē gān ér qǐ", "origin": "漢·賈誼《過秦論》/《史記·陳涉世家》", "story": "秦二世元年，陳勝、吳廣等九百戍卒行至大澤鄉，遇大雨失期，法皆斬。陳勝召豪傑曰：『且壯士不死即已，死即舉大名耳，王侯將相寧有種乎！』乃斬木為兵，揭竿為旗，天下雲集響應，贏糧而景從，山東豪俊遂並起而亡秦族矣。", "quote": "斬木為兵，揭竿為旗，天下雲集響應，贏糧而景從。", "desc": "比喻人民因不堪壓迫起義反抗。", "yin": "jiē gān ér qǐ"}, {"rank": 489, "idiom": "運籌帷幄", "pinyin": "yùn chóu wéi wò", "origin": "《史記·高祖本紀》", "story": "漢高祖劉邦置酒洛陽南宮，問諸將所以得天下之由。高祖曰：『夫運籌帷幄之中，決勝千里之外，吾不如子房；鎮國家，撫百姓，給饋餉，不絕糧道，吾不如蕭何；連百萬之軍，戰必勝，攻必取，吾不如韓信。三者皆人傑也，吾能用之，此吾所以取天下也。』", "quote": "夫運籌帷幄之中，決勝千里之外，吾不如子房。", "desc": "比喻在後方策劃指揮，掌控全域。", "yin": "yùn chóu wéi wò"}, {"rank": 488, "idiom": "約法三章", "pinyin": "yuē fǎ sān zhāng", "origin": "《史記·高祖本紀》", "story": "沛公劉邦兵先諸侯入鹹陽，秦王子嬰降。沛公召諸縣父老豪傑曰：『父老苦秦苛法久矣！誹謗者族，偶語者棄市。吾與諸侯約，先入關者王之，吾當王關中。與父老約法三章耳：殺人者死，傷人及盜抵罪。餘悉除去秦法。』秦人大喜，爭持牛羊酒食獻饗。", "quote": "與父老約法三章耳：殺人者死，傷人及盜抵罪。餘悉除去秦法。", "desc": "指訂立簡明切實的法規以安民心。", "yin": "yuē fǎ sān zhāng"}, {"rank": 487, "idiom": "四面楚歌", "pinyin": "sì miàn chǔ gē", "origin": "《史記·項羽本紀》", "story": "項王軍壁垓下，兵少食盡，漢軍及諸侯兵圍之數重。夜聞漢軍四面皆楚歌，項王乃大驚曰：『漢皆已得楚乎？是何楚人之多也！』項王則夜起，飲帳中。有美人名虞，常幸從；駿馬名騅，常騎之。於是項王乃悲歌慷慨，泣下數行。", "quote": "夜聞漢軍四面皆楚歌，項王乃大驚曰：『漢皆已得楚乎？是何楚人之多也！』", "desc": "比喻陷入重重包圍，孤立無援的困境。", "yin": "sì miàn chǔ gē"}, {"rank": 486, "idiom": "霸王別姬", "pinyin": "bà wáng bié jī", "origin": "《史記·項羽本紀》", "story": "垓下被圍，項王知大勢已去，作歌慷慨曰：『力拔山兮氣蓋世，時不利兮騅不逝。騅不逝兮可奈何，虞兮虞兮奈若何！』歌數闋，美人和之。項王泣數行下，左右皆泣，莫能仰視。虞姬隨即拔劍自刎，殉楚霸王。", "quote": "力拔山兮氣蓋世，時不利兮騅不逝。騅不逝兮可奈何，虞兮虞兮奈若何！", "desc": "形容英雄窮途末路與摯愛訣別之悲壯。", "yin": "bà wáng bié jī"}, {"rank": 485, "idiom": "蕭規曹隨", "pinyin": "xiāo guī cáo suí", "origin": "《史記·曹相國世家》", "story": "蕭何薨，曹參繼任漢相國。參代何為相，舉事無所變更，一遵蕭何約束。惠帝怪參不理政事，參曰：『高帝與蕭何定天下，法令既明。今陛下垂拱，參等守職，遵而勿失，不亦可乎？』百姓歌之曰：『蕭何為法，若畫一；曹參代之，守而勿失。載其清淨，民以寧一。』", "quote": "蕭何為法，若畫一；曹參代之，守而勿失。", "desc": "比喻依照前人成規行事，不妄加變革。", "yin": "xiāo guī cáo suí"}, {"rank": 484, "idiom": "塞翁失馬", "pinyin": "sài wēng shī mǎ", "origin": "《淮南子·人間訓》", "story": "近塞上之人有善術者，馬無故亡而入胡。人皆賀之，其父曰：『此何遽不為福乎？』居數月，其馬將胡駿馬而歸。人皆賀之，父曰：『此何遽不能為禍乎？』家富良馬，其子好騎，墮而折其髀。丁壯者引弦而戰，近塞之人死者十九，此獨以跛之故，父子相保。", "quote": "禍兮福之所倚，福兮禍之所伏，聖人不能察也。", "desc": "比喻壞事可能轉為好事，好事亦可轉為禍端。", "yin": "sài wēng shī mǎ"}, {"rank": 483, "idiom": "唇亡齒寒", "pinyin": "chún wáng chǐ hán", "origin": "《左傳·僖公五年》", "story": "晉獻公欲伐虢，向虞國借道。宮之奇諫虞公曰：『虢，虞之表也；虢亡，虞必從之。晉不可啟，寇不可翫。一之謂甚，其可再乎？諺所謂輔車相依，唇亡齒寒者，其虞虢之謂也！』虞公不聽，許晉借道。晉滅虢後，還軍滅虞。", "quote": "諺所謂輔車相依，唇亡齒寒者，其虞虢之謂也。", "desc": "比喻雙方利害休慼相關，互為依賴。", "yin": "chún wáng chǐ hán"}, {"rank": 482, "idiom": "邯鄲學步", "pinyin": "hán dān xué bù", "origin": "《莊子·秋水》", "story": "壽陵餘子之學行於邯鄲，未得國能，又失其故行矣，直匍匐而歸耳。公孫龍自矜才博，魏牟引此寓言笑之，謂其徒欲窺大道而自失其所守，終成大笑於天下。", "quote": "且子獨不聞夫壽陵餘子之學行於邯鄲與？未得國能，又失其故行矣，直匍匐而歸耳。", "desc": "比喻模仿他人不成，反倒喪失固有本領。", "yin": "hán dān xué bù"}, {"rank": 481, "idiom": "掩耳盜鈴", "pinyin": "yǎn ěr dào líng", "origin": "《呂氏春秋·自知》", "story": "範氏之亡也，百姓有得鐘者，欲負而走，則鐘大不可負。以椎毀之，鐘況然有聲。恐人聞之而奪己也，遽掩其耳。惡人聞之，可也；惡己自聞之，悖矣！", "quote": "恐人聞之而奪己也，遽掩其耳。", "desc": "比喻自欺欺人，以為自己不知別人亦不知。", "yin": "yǎn ěr dào líng"}, {"rank": 480, "idiom": "買櫝還珠", "pinyin": "mǎi dú huán zhū", "origin": "《韓非子·外儲說左上》", "story": "楚人有賣其珠於鄭者，為木蘭之櫃，薰以桂椒，綴以珠玉，飾以玫瑰，輯以翡翠。鄭人買其櫝而還其珠。此可謂善賣櫝矣，未可謂善鬻珠也。", "quote": "鄭人買其櫝而還其珠。此可謂善賣櫝矣，未可謂善鬻珠也。", "desc": "比喻捨本逐末，取捨失當。", "yin": "mǎi dú huán zhū"}, {"rank": 479, "idiom": "杞人憂天", "pinyin": "qǐ rén yōu tiān", "origin": "《列子·天瑞》", "story": "杞國有人憂天地崩墜，身亡所寄，廢寢食者。又有憂彼之所憂者，往曉之曰：『天，積氣耳，亡處亡氣。若屈伸呼吸，終日在天中行止，奈何憂崩墜乎？』其人舍然大喜，曉之者亦舍然大喜。", "quote": "杞國有人憂天地崩墜，身亡所寄，廢寢食者。", "desc": "比喻缺乏事實依據之庸人自擾。", "yin": "qǐ rén yōu tiān"}, {"rank": 478, "idiom": "杯弓蛇影", "pinyin": "bēi gōng shé yǐng", "origin": "漢·應劭《風俗通義·怪神》", "story": "樂廣嘗有親客，久闊不復來，廣問其故，答曰：『前在坐，蒙賜酒，方欲飲，見杯中有蛇，意甚惡之，既飲而疾。』於時河南聽事堂上，壁懸赤弩，照於巵中，動如蛇形。廣乃告其所以，客豁然意解，沈痾頓愈。", "quote": "客豁然意解，沈痾頓愈。", "desc": "比喻疑神疑鬼，妄自驚擾。", "yin": "bēi gōng shé yǐng"}, {"rank": 477, "idiom": "刻舟求劍", "pinyin": "kè zhōu qiú jiàn", "origin": "《呂氏春秋·察今》", "story": "楚人有涉江者，其劍自舟中墜於水，遽契其舟曰：『是吾劍之所從墜。』舟止，從其所契者入水求之。舟已行矣，而劍不行，求劍若此，不亦惑乎？以故法為其國與此同，時已徙矣，而法不徙，以此為治，豈不難哉！", "quote": "舟已行矣，而劍不行，求劍若此，不亦惑乎？", "desc": "比喻拘泥成規，不知隨時間客觀條件變化而變通。", "yin": "kè zhōu qiú jiàn"}, {"rank": 476, "idiom": "鄭人買履", "pinyin": "zhèng rén mǎi lǚ", "origin": "《韓非子·外儲說左上》", "story": "鄭人有欲買履者，先自度其足，而置之其坐。至之市，而忘操之。已得履，乃曰：『吾忘持度。』反歸取之。及反，市罷，遂不得履。人曰：『何不試之以足？』曰：『寧信度，無自信也。』", "quote": "寧信度，無自信也。", "desc": "比喻死守教條規矩，不知因地制宜以求實用。", "yin": "zhèng rén mǎi lǚ"}, {"rank": 475, "idiom": "守株待兔", "pinyin": "shǒu zhū dài tù", "origin": "《韓非子·五蠹》", "story": "宋人有耕田者，田中有株，兔走觸株，折頸而死。因釋其耒而守株，冀復得兔。兔不可復得，而身為宋國笑。今欲以先王之政，治當世之民，皆守株之類也。", "quote": "因釋其耒而守株，冀復得兔。兔不可復得，而身為宋國笑。", "desc": "比喻不思努力而僥倖寄望於意外收穫。", "yin": "shǒu zhū dài tù"}, {"rank": 474, "idiom": "自相矛盾", "pinyin": "zì xiāng máo dùn", "origin": "《韓非子·難一》", "story": "楚人有鬻盾與矛者，譽之曰：『吾盾之堅，莫能陷也。』又譽其矛曰：『吾矛之利，於物無不陷也。』或曰：『以子之矛，陷子之盾，何如？』其人弗能應也。夫不可陷之盾與無不陷之矛，不可同世而立。", "quote": "以子之矛，陷子之盾，何如？其人弗能應也。", "desc": "比喻言行前後抵觸，無法自圓其說。", "yin": "zì xiāng máo dùn"}, {"rank": 473, "idiom": "畫蛇添足", "pinyin": "huà shé tiān zú", "origin": "《戰國策·齊策二》", "story": "楚有祠者，賜其舍人卮酒。舍人相謂曰：『數人飲之不足，一人飲之有餘。請畫地為蛇，先成者飲酒。』一人蛇先成，引酒且飲之，乃左手持卮，右手畫蛇曰：『吾能為之足。』未成，一人之蛇成，奪其卮曰：『蛇固無足，子安能為之足？』遂飲其酒。為蛇足者，終亡其酒。", "quote": "蛇固無足，子安能為之足？為蛇足者，終亡其酒。", "desc": "比喻多此一舉，反而弄巧成拙。", "yin": "huà shé tiān zú"}, {"rank": 472, "idiom": "鷸蚌相爭", "pinyin": "yù bàng xiāng zhēng", "origin": "《戰國策·燕策二》", "story": "趙且伐燕，蘇代為燕謂惠王曰：『今者臣來，過易水，蚌方出曝，而鷸啄其肉，蚌合而拑其喙。鷸曰：今日不雨，明日不雨，即有死蚌。蚌亦謂鷸曰：今日不出，明日不出，即有死鷸。兩者不肯相舍，漁者得而並禽之。今趙且伐燕，燕趙久相支，以弊大眾，臣恐強秦之為漁父也。』", "quote": "兩者不肯相舍，漁者得而並禽之。", "desc": "比喻雙方相持不下，兩敗俱傷，使第三者坐收漁利。", "yin": "yù bàng xiāng zhēng"}, {"rank": 471, "idiom": "狐假虎威", "pinyin": "hú jiǎ hǔ wēi", "origin": "《戰國策·楚策一》", "story": "荊宣王問群臣曰：『吾聞北方之畏昭奚恤也，果誠何如？』江乙對曰：『虎求百獸而食之，得狐。狐曰：子無敢食我也，天帝使我長百獸，今子食我，是逆天帝命也。子以我為不信，吾為子先行，子隨我後，觀百獸之見我而敢不走乎！虎以為然，故遂與之行。獸見之皆走。虎不知獸畏己而走也，以為畏狐也。』", "quote": "虎不知獸畏己而走也，以為畏狐也。", "desc": "比喻倚仗他人威勢來作威作福欺凌他人。", "yin": "hú jiǎ hǔ wēi"}, {"rank": 470, "idiom": "濫竽充數", "pinyin": "làn yú chōng shù", "origin": "《韓非子·內儲說上》", "story": "齊宣王使人吹竽，必三百人。南郭處士請為王吹竽，宣王說之，廩食以數百人。宣王死，湣王立，好一一聽之，處士逃。故韓子以為治國任能，當考實功，無令虛聲者混跡。", "quote": "宣王死，湣王立，好一一聽之，處士逃。", "desc": "比喻無真才實學之人混在行家裡充數冒充。", "yin": "làn yú chōng shù"}, {"rank": 469, "idiom": "庖丁解牛", "pinyin": "páo dīng jiě niú", "origin": "《莊子·養生主》", "story": "庖丁為文惠君解牛，手之所觸，肩之所倚，足之所履，膝之所踦，砉然嚮然，奏刀騞然，莫不中音。文惠君曰：『譆，善哉！技蓋至此乎？』庖丁釋刀對曰：『臣之所好者道也，進乎技矣。始臣之解牛之時，所見無非全牛者；三年之後，未嘗見全牛也。方今之時，臣以神遇而不以目視，官知止而神欲行。依乎天理，批大郤，導大窾，因其固然。』", "quote": "以神遇而不以目視，官知止而神欲行。依乎天理，批大郤，導大窾，因其固然。", "desc": "比喻經過反覆實踐掌握事物規律，技藝達到出神入化之境。", "yin": "páo dīng jiě niú"}, {"rank": 468, "idiom": "揠苗助長", "pinyin": "yà miáo zhù zhǎng", "origin": "《孟子·公孫醜上》", "story": "宋人有閔其苗之不長而揠之者，芒芒然歸，謂其人曰：『今日病矣！予助苗長矣！』其子趨而往視之，苗則槁矣。天下之不助苗長者寡矣。以為無益而舍之者，不耘苗者也；助之長者，揠苗者也，非徒無益，而又害之。", "quote": "助之長者，揠苗者也，非徒無益，而又害之。", "desc": "比喻違反客觀事物規律急於求成，反而壞事。", "yin": "yà miáo zhù zhǎng"}, {"rank": 467, "idiom": "井底之蛙", "pinyin": "jǐng dǐ zhī wā", "origin": "《莊子·秋水》", "story": "井蛙謂東海之鱉曰：『吾跳踉井幹之上，入休於甃閣，科蚪蟹友無能及我。子盍亦來觀乎！』鱉語海之廣深：『夫千里之遠，不足以舉其大；千仞之高，不足以極其深。禹時十年九潦，而水弗為加益；湯時八年七旱，而崖不為加損。此亦東海之大樂也！』蛙聞之，適適然驚，規規然自失也。", "quote": "井蛙不可以語於海者，拘於虛也；夏蟲不可以語於冰者，篤於時也。", "desc": "比喻見識狹隘之人，孤陋寡聞而妄自尊大。", "yin": "jǐng dǐ zhī wā"}, {"rank": 466, "idiom": "望洋興嘆", "pinyin": "wàng yáng xìng tàn", "origin": "《莊子·秋水》", "story": "秋水時至，百川灌河，涇流之大，兩涘渚崖之間，不辯牛馬。於是焉河伯欣然自喜，以天下之美為盡在己。順流而東行，至於北海，東面而視，不見水端。於是焉河伯始旋其面目，望洋向若而歎曰：『野語有之曰：聞道百，以為莫己若者，我之謂也。』", "quote": "於是焉河伯始旋其面目，望洋向若而歎曰：聞道百以為莫己若者，我之謂也。", "desc": "形容看到宏大境界或博大精神而自感渺小，亦指無可奈何。", "yin": "wàng yáng xìng tàn"}, {"rank": 465, "idiom": "螳臂當車", "pinyin": "táng bì dāng chē", "origin": "《莊子·人間世》/《莊子·山木》", "story": "汝不知夫螳螂乎？怒其臂以當車轍，不知其不勝任也，是其才之美者也。齊莊公出獵，見一蟲舉足將搏其輪，問其御者，御曰：『此螳螂也，其為蟲不知進退，輕敵而自用。』公曰：『使其為人，必為勇士。』乃回車避之。", "quote": "汝不知夫螳螂乎？怒其臂以當車轍，不知其不勝任也，是其才之美者也。", "desc": "比喻不自量力，企圖阻擋無法抵擋之強大力量。", "yin": "táng bì dāng chē"}, {"rank": 464, "idiom": "亡羊補牢", "pinyin": "wáng yáng bǔ láo", "origin": "《戰國策·楚策四》", "story": "莊辛諫楚襄王不聽，秦果拔郢，王亡走城陽。王謂莊辛曰：『寡人不能用先生之言，今事至於此，為之奈何？』莊辛對曰：『臣聞鄙語曰：見兔而顧犬，未為晚也；亡羊而補牢，未為遲也。昔者湯武以百里昌，桀紂以天下亡。今楚雖小，絕長續短，猶以數千里，豈特百里哉！』", "quote": "見兔而顧犬，未為晚也；亡羊而補牢，未為遲也。", "desc": "比喻出了差錯後設法及時補救，避免繼續受害。", "yin": "wáng yáng bǔ láo"}, {"rank": 463, "idiom": "緣木求魚", "pinyin": "yuán mù qiú yú", "origin": "《孟子·梁惠王上》", "story": "齊宣王欲闢土地，朝秦楚，蒞中國而撫四夷。孟子曰：『以若所為，求若所欲，猶緣木而求魚也。』王曰：『若是其甚與？』曰：『殆有甚焉。緣木求魚，雖不得魚，無後災；以若所為，求若所欲，盡心力而為之，後必有災。』孟子因闡明仁政王道。", "quote": "以若所為，求若所欲，猶緣木而求魚也。", "desc": "比喻方向或方法完全不對，根本不可能達到目的。", "yin": "yuán mù qiú yú"}, {"rank": 462, "idiom": "驚弓之鳥", "pinyin": "jīng gōng zhī niǎo", "origin": "《戰國策·楚策四》", "story": "更羸與魏王處京臺之下，仰見飛鳥。更羸謂王曰：『臣為王引弓虛發而下鳥。』魏王曰：『然則射可至此乎？』更羸曰：『可。』有間，鴈從東方來，更羸以虛發而下之。王曰：『嘻，射亦可至此乎？』更羸曰：『此孽也。其飛徐而鳴悲。飛徐者，故瘡痛也；鳴悲者，久要飛也。瘡痛未息，驚心未去，聞絃音引而高飛，故瘡裂而墮。』", "quote": "瘡痛未息，驚心未去，聞絃音引而高飛，故瘡裂而墮。", "desc": "比喻曾受過驚恐創傷，一遇動靜就恐懼不安之人。", "yin": "jīng gōng zhī niǎo"}, {"rank": 461, "idiom": "東施效顰", "pinyin": "dōng shī xiào pín", "origin": "《莊子·天運》", "story": "西施病心而矉其裡，其裡之醜人見而美之，歸亦捧心而矉其裡。其裡之富人見之，堅閉門而不出；貧人見之，挈妻子而去走。彼知矉美，而不知矉之所以美。", "quote": "彼知矉美，而不知矉之所以美。", "desc": "比喻盲目模仿他人，效果適得其反，醜態百出。", "yin": "dōng shī xiào pín"}, {"rank": 460, "idiom": "愚公移山", "pinyin": "yú gōng yí shān", "origin": "《列子·湯問》", "story": "太行、王屋二山，方七百里，高萬仞。北山愚公年且九十，面山而居，懲山北之塞，出入之迂也，聚室而謀曰：『吾與汝畢力平險，指通豫南，達於漢陰，可乎？』河曲智叟笑而止之。愚公長息曰：『雖我之死，有子存焉；子又生孫，孫又生子；子又有子，子又有孫；子子孫孫無窮匱也，而山不加增，何苦而不平？』操蛇之神聞之，帝感其誠，命誇娥氏二子負二山。", "quote": "子子孫孫無窮匱也，而山不加增，何苦而不平？", "desc": "比喻下定決心，堅持不懈，終能克服萬難達成目標。", "yin": "yú gōng yí shān"}, {"rank": 459, "idiom": "葉公好龍", "pinyin": "yè gōng hào lóng", "origin": "漢·劉向《新序·雜事五》", "story": "葉公子高好龍，鉤以寫龍，鑿以寫龍，屋室雕文以寫龍。於是天龍聞而下之，窺頭於牖，施尾於堂。葉公見之，棄而還走，失其魂魄，五色無主。是葉公非好龍也，好夫似龍而非龍者也。", "quote": "葉公非好龍也，好夫似龍而非龍者也。", "desc": "比喻口頭上愛好某種事物，實際上並非真愛乃至畏懼厭惡。", "yin": "yè gōng hào lóng"}, {"rank": 458, "idiom": "朝三暮四", "pinyin": "zhāo sān mù sì", "origin": "《莊子·齊物論》/《列子·黃帝》", "story": "宋有狙公者，愛狙，養之成群，能解狙之意。狙亦得公之心。損其家口，充狙之慾。俄而匱焉，將限其食。恐狙之不馴也，先誑之曰：『與若芐，朝三而暮四，足乎？』眾狙皆起而怒。俄而曰：『與若芐，朝四而暮三，足乎？』眾狙皆伏而喜。物與名俱無虧，而喜怒為用，亦因是也。", "quote": "狙公賦芐，曰朝三而暮四，眾狙皆怒；曰朝四而暮三，眾狙皆喜。名實未虧而喜怒為用。", "desc": "原指玩弄手法瞞哄欺騙，後多比喻常常變卦，反覆無常。", "yin": "zhāo sān mù sì"}, {"rank": 457, "idiom": "歧路亡羊", "pinyin": "qí lù wáng yáng", "origin": "《列子·說符》", "story": "楊子之鄰人亡羊，既率其黨，又請楊子之豎追之。楊子曰：『嘻，亡一羊，何追者之眾？』鄰人曰：『多歧路。』既反，問：『獲羊乎？』曰：『亡之矣。』曰：『奚亡之？』曰：『歧路之中又有歧焉，吾不知所之，所以反也。』楊子戚然變容，不言者移時。心學多端，求道亦然。", "quote": "大道以多歧亡羊，學者以多方喪生。", "desc": "比喻事情錯綜複雜，因缺乏明確方向而誤入歧途迷失真理。", "yin": "qí lù wáng yáng"}, {"rank": 456, "idiom": "高山流水", "pinyin": "gāo shān liú shuǐ", "origin": "《列子·湯問》/《呂氏春秋·本味》", "story": "伯牙善鼓琴，鍾子期善聽。伯牙鼓琴，志在登高山，鍾子期曰：『善哉，峨峨兮若泰山！』志在流水，鍾子期曰：『善哉，洋洋兮若江河！』伯牙所念，鍾子期必得之。子期死，伯牙破琴絕絃，終身不復鼓琴，以為世無足復為鼓琴者。", "quote": "志在登高山，曰善哉峨峨兮若泰山；志在流水，曰善哉洋洋兮若江河。", "desc": "比喻知音難遇，亦形容樂曲高妙絕倫。", "yin": "gāo shān liú shuǐ"}, {"rank": 455, "idiom": "南轅北轍", "pinyin": "nán yuán běi zhé", "origin": "《戰國策·魏策四》", "story": "季梁聞魏王欲伐邯鄲，中道而反，見王曰：『今者臣來，見人於太行，方北面而馳其駕，告臣曰吾欲之楚。臣曰君之楚，何為而北？曰吾馬良。臣曰馬雖良，此非楚之路也。曰吾用多。臣曰用雖多，此非楚之路也。曰吾御者善。此數者愈善，而離楚愈遠耳。』", "quote": "此數者愈善，而離楚愈遠耳。", "desc": "比喻行動和目標完全相反，越用力越背離宗旨。", "yin": "nán yuán běi zhé"}, {"rank": 454, "idiom": "抱薪救火", "pinyin": "bào xīn jiù huǒ", "origin": "《史記·魏世家》", "story": "秦攻魏，魏欲割地以求和。蘇代謂魏安僖王曰：『夫抱薪而救火，薪不盡，火不滅。今王以地事秦，秦之慾無厭，地有盡而秦求無窮，是抱薪救火也。』魏王不聽，卒為秦滅。", "quote": "且夫以地事秦，譬猶抱薪救火，薪不盡，火不滅。", "desc": "比喻用錯誤有害的方法去消弭禍患，結果禍患反而愈演愈烈。", "yin": "bào xīn jiù huǒ"}, {"rank": 453, "idiom": "盲人摸象", "pinyin": "máng rén mō xiàng", "origin": "《大般涅槃經·卷三十》", "story": "有王命牽象以示群盲。各摩其身：撫牙者言象如蘆菔根，摩耳者言象如箕，撫腳者言象如臼，撫背者言象如床，摩腹者言象如甕，摩尾者言象如絪繩。群盲競諍，各執己見。佛以此喻世人執著片面而不知全體大道。", "quote": "盲人各以所觸一分謂為象體，執己所見，各不相伏。", "desc": "比喻只憑片面瞭解即妄下全盤結論，認識主觀狹隘。", "yin": "máng rén mō xiàng"}, {"rank": 452, "idiom": "飲鴆止渴", "pinyin": "yǐn zhèn zhǐ kě", "origin": "《後漢書·霍諝傳》", "story": "霍諝舅宋娥為大將軍梁冀所陷，諝年十五，上書訟之曰：『飛鳥衝林，不擇枝而棲；人窮反本，不計險而走。譬猶飢者甘糟糠，渴者飲鴆毒，豈不苟安須臾，而自及滅亡之禍哉！』帝覽章感悟，省釋宋娥。", "quote": "譬猶飢者甘糟糠，渴者飲鴆毒，豈不苟安須臾，而自及滅亡之禍哉！", "desc": "比喻只圖解決眼前的燃眉之急，而不顧後果帶來毀滅性大患。", "yin": "yǐn zhèn zhǐ kě"}, {"rank": 451, "idiom": "黔驢技窮", "pinyin": "qián lǘ jì qióng", "origin": "唐·柳宗元《三戒·黔之驢》", "story": "黔無驢，有好事者船載以入。放之山下，虎見之，龐然大物也，以為神。蔽林間窺之，稍出近之，憖憖然莫相知。他日，驢一鳴，虎大駭，遠遁。然往來視之，覺無異能者；益習其聲，又近出前後，蕩倚衝冒。驢不勝怒，蹄之。虎因喜，計之曰：『技止此耳！』因跳踉大㘚，斷其喉，盡其肉，乃去。", "quote": "虎因喜，計之曰：技止此耳！因跳踉大㘚，斷其喉，盡其肉，乃去。", "desc": "比喻有限的一點拙劣技能已經用盡，再也無計可施。", "yin": "qián lǘ jì qióng"}, {"rank": 450, "idiom": "溫故知新", "pinyin": "wēn gù zhī xīn", "origin": "《論語·為政》", "story": "子曰：『溫故而知新，可以為師矣。』孔子教導弟子研習古典，並非死記舊章，而是在溫習歷代舊學典冊中，體悟出切合當下之全新義理，如此方能承先啟後，為人師表。", "quote": "溫故而知新，可以為師矣。", "desc": "指複習舊有學問而從中獲得新的理解與領悟。", "yin": "wēn gù zhī xīn"}, {"rank": 449, "idiom": "見賢思齊", "pinyin": "jiàn xián sī qí", "origin": "《論語·里仁》", "story": "子曰：『見賢思齊焉，見不賢而內自省也。』孔子勉勵門人隨時隨地修養德行，見到德才兼備之人便一心向其看齊，見到德行欠缺之人則反觀自身有無相同過失，以此砥礪道德操守。", "quote": "見賢思齊焉，見不賢而內自省也。", "desc": "指看到德才優秀之人便想向其看齊努力修持。", "yin": "jiàn xián sī qí"}, {"rank": 448, "idiom": "任重道遠", "pinyin": "rèn zhòng dào yuǎn", "origin": "《論語·泰伯》", "story": "曾子曰：『士不可以不弘毅，任重而道遠。仁以為己任，不亦重乎？死而後已，不亦遠乎？』曾子指出讀書人必須志向遠大、剛毅果決，因為實踐仁德王道乃天下至重之重責，終生不懈方能達成。", "quote": "士不可以不弘毅，任重而道遠。仁以為己任，不亦重乎？死而後已，不亦遠乎？", "desc": "比喻擔負的責任極其重大，艱難的長路極為遙遠。", "yin": "rèn zhòng dào yuǎn"}, {"rank": 447, "idiom": "三思而行", "pinyin": "sān sī ér xíng", "origin": "《論語·公冶長》", "story": "季文子三思而後行。子聞之，曰：『再，斯可矣。』魯國大夫季文子每遇事必反覆思索三次始付諸行動。孔子知其生性多疑過慮，因而提示只要思慮兩次明辨是非利害即當決斷，過度猶豫反致貽誤時機。", "quote": "季文子三思而後行。子聞之，曰：再，斯可矣。", "desc": "指經過反覆周密的思考後才採取行動，力求穩妥。", "yin": "sān sī ér xíng"}, {"rank": 446, "idiom": "不恥下問", "pinyin": "bù chǐ xià wèn", "origin": "《論語·公冶長》", "story": "子貢問曰：『孔文子何以謂之文也？』子曰：『敏而好學，不恥下問，是以謂之文也。』衛國大夫孔圉聰慧好學，雖身居顯爵，若有不通之處，仍虛懷若谷向地位不如自己之人請教，毫不覺羞恥，故得諡號為文。", "quote": "敏而好學，不恥下問，是以謂之文也。", "desc": "形容謙虛向地位或學識不如自己的人請教，不自矜自滿。", "yin": "bù chǐ xià wèn"}, {"rank": 445, "idiom": "敏而好學", "pinyin": "mǐn ér hǎo xué", "origin": "《論語·公冶長》", "story": "孔子盛讚孔文子之所以能獲得最高諡號，正在於其天資穎異敏銳，卻從不恃才傲物，始終孜孜不倦酷愛學問，終生勤勉研求典籍義理。", "quote": "敏而好學，不恥下問，是以謂之文也。", "desc": "指資質敏銳聰穎且酷愛讀書求知。", "yin": "mǐn ér hǎo xué"}, {"rank": 444, "idiom": "巧言令色", "pinyin": "qiǎo yán lìng sè", "origin": "《論語·學而》", "story": "子曰：『巧言令色，鮮矣仁！』孔子告誡弟子，以花言巧語討好他人、偽裝溫和麵容以取悅世俗者，內心多失真誠，極少具有仁義實質德行。修身首在忠信質樸，切忌矯飾虛偽。", "quote": "巧言令色，鮮矣仁！", "desc": "指用花言巧語和諂媚臉色討好奉承他人。", "yin": "qiǎo yán lìng sè"}, {"rank": 443, "idiom": "過猶不及", "pinyin": "guò yóu bù jí", "origin": "《論語·先進》", "story": "子貢問：『師與商也孰賢？』子曰：『師也過，商也不及。』曰：『然則師愈與？』子曰：『過猶不及。』顓孫師行事常過度激切，卜商行事則過於拘謹。孔子點明作事過分與做不到位同樣不合中庸之道。", "quote": "子曰：師也過，商也不及。曰：然則師愈與？子曰：過猶不及。", "desc": "指事情做得過頭與做得不夠同樣不妥，凡事當閤中庸之度。", "yin": "guò yóu bù jí"}, {"rank": 442, "idiom": "逝者如斯", "pinyin": "shì zhě rú sī", "origin": "《論語·子罕》", "story": "子在川上曰：『逝者如斯夫！不捨晝夜。』孔子立於川流之濱，俯瞰滔滔江水奔流向前，日夜不息，深感時光飛逝與萬物遷流無常，藉此勉勵學者抓緊光陰刻苦立志，精進自強。", "quote": "子在川上曰：逝者如斯夫！不捨晝夜。", "desc": "形容光陰流水一去不復返，感嘆時光無情飛逝。", "yin": "shì zhě rú sī"}, {"rank": 441, "idiom": "己所不欲", "pinyin": "jǐ suǒ bù yù", "origin": "《論語·衛靈公》", "story": "子貢問曰：『有一言而可以終身行之者乎？』子曰：『其恕乎！己所不欲，勿施於人。』孔子將恕道提煉為人際相處之最高準則，凡自己所不願承受之屈辱苦痛，絕不可加諸他人身上。", "quote": "己所不欲，勿施於人。", "desc": "指推己及人，凡自己不喜歡的事物絕不強加於他人。", "yin": "jǐ suǒ bù yù"}, {"rank": 440, "idiom": "孟母三遷", "pinyin": "mèng mǔ sān qiān", "origin": "漢·劉向《列女傳·母儀傳·鄒孟軻母》", "story": "孟子幼時，其舍近墓，孟子遂嬉戲為墓間之事，踴躍築埋。孟母曰：『此非吾所以居處子也。』乃去舍市傍。其嬉戲為賈人衒賣之事。孟母又曰：『此非吾所以居處子也。』復徙舍學宮之傍。其嬉戲乃設俎豆揖讓進退，孟母曰：『真可以居吾子矣。』遂居之。", "quote": "孟子生有淑質，幼被慈母三遷之教。", "desc": "比喻家長為子女成長選擇優良良好的教育與生活環境。", "yin": "mèng mǔ sān qiān"}, {"rank": 439, "idiom": "出爾反爾", "pinyin": "chū ěr fǎn ěr", "origin": "《孟子·梁惠王下》", "story": "鄒與魯鬨。穆公問孟子，孟子曰：『曾子曰：戒之戒之！出乎爾者，反乎爾者也。夫民今而後得反之也。君無尤焉！』昔日長官遇饑荒坐視民餓死，今日戰事士卒遂坐視長官陣亡。自作自受，因果相循。", "quote": "戒之戒之！出乎爾者，反乎爾者也。", "desc": "原指怎樣對待別人就會得到怎樣的反饋，後多形容言行反覆無常、自相違背。", "yin": "chū ěr fǎn ěr"}, {"rank": 438, "idiom": "始作俑者", "pinyin": "shǐ zuò yǒng zhě", "origin": "《孟子·梁惠王上》", "story": "仲尼曰：『始作俑者，其無後乎！』為其象人而用之也。古者以殉葬傷天害理，後世雖改用泥木俑偶隨葬，孔子仍嚴厲痛斥首開惡例者，因其開啟不仁之禍端，遺毒無窮。", "quote": "仲尼曰：始作俑者，其無後乎！為其象人而用之也。", "desc": "比喻惡劣風氣或不良先例的開創者。", "yin": "shǐ zuò yǒng zhě"}, {"rank": 437, "idiom": "生於憂患", "pinyin": "shēng yú yōu huàn", "origin": "《孟子·告子下》", "story": "舜發於畎畝之中，傅說舉於版築之間，膠鬲舉於魚鹽之中，管夷吾舉於士，孫叔敖舉於海，百里奚舉於市。故天將降大任於是人也，必先苦其心志，勞其筋骨，餓其體膚，空乏其身，行拂亂其所為，所以動心忍性，曾益其所不能。然後知生於憂患而死於安樂也。", "quote": "入則無法家拂士，出則無敵國外患者，國恆亡。然後知生於憂患而死於安樂也。", "desc": "指憂難艱困能磨礪意志促使人生存奮起，安逸沉溺反致衰亡。", "yin": "shēng yú yōu huàn"}, {"rank": 436, "idiom": "專心致志", "pinyin": "zhuān xīn zhì zhì", "origin": "《孟子·告子上》", "story": "弈秋，通國之善弈者也。使弈秋誨二人弈，其一人專心致志，惟弈秋之為聽；一人雖聽之，一心以為有鴻鵠將至，思援弓繳而射之。雖與之俱學，弗若之矣。為是其智弗若與？曰：非然也。", "quote": "今夫弈之為數，小數也；不專心致志，則不得也。", "desc": "指一心一意，集中全部精力投入其中。", "yin": "zhuān xīn zhì zhì"}, {"rank": 435, "idiom": "摩頂放踵", "pinyin": "mó dǐng fàng zhǒng", "origin": "《孟子·盡心上》", "story": "楊子取為我，拔一毛而利天下，不為也。墨子兼愛，摩頂放踵利天下，為之。子莫執中，執中為近之，執中無權，猶執一也。墨家主張兼愛天下，縱使從頭頂磨禿到腳後跟，只要有利於世人百姓，亦甘之如飴。", "quote": "墨子兼愛，摩頂放踵利天下，為之。", "desc": "比喻捨己救人，不辭勞苦為天下蒼生利益奔走。", "yin": "mó dǐng fàng zhǒng"}, {"rank": 434, "idiom": "遊刃有餘", "pinyin": "yóu rèn yǒu yú", "origin": "《莊子·養生主》", "story": "庖丁釋刀對曰：『彼節者有間，而刀刃者無厚；以無厚入有間，恢恢乎其於遊刃必有餘地矣，是以十九年而刀刃若新發於硎。』藉牛骨骨節縫隙與薄利刀刃之理，說明因順規律者臨事從容不迫。", "quote": "以無厚入有間，恢恢乎其於遊刃必有餘地矣。", "desc": "形容經驗豐富熟練，處理複雜難題輕鬆從容、遊刃有餘。", "yin": "yóu rèn yǒu yú"}, {"rank": 433, "idiom": "莊周夢蝶", "pinyin": "zhuāng zhōu mèng dié", "origin": "《莊子·齊物論》", "story": "昔者莊周夢為胡蝶，栩栩然胡蝶也，自喻適志與！不知周也。俄然覺，則蘧蘧然周也。不知周之夢為胡蝶與，胡蝶之夢為周與？周與胡蝶，則必有分矣。此之謂物化。", "quote": "昔者莊周夢為胡蝶，栩栩然胡蝶也，不知周也。俄然覺，則蘧蘧然周也。", "desc": "指物我交融的大化境界，亦比喻人生如夢幻無常。", "yin": "zhuāng zhōu mèng dié"}, {"rank": 432, "idiom": "涸轍之鮒", "pinyin": "hé zhé zhī fù", "origin": "《莊子·外物》", "story": "莊周家貧，往貸粟於監河侯。監河侯曰：『諾。我將得邑金，貸子三百金，可乎？』莊周忿然作色曰：『周昨來，有呼者，視車轍中有鮒魚焉。問曰：鮒魚來，子何為者邪？對曰：吾得斗升之水然活耳。君豈有斗升之水而活我哉？周曰：吾南遊吳越之王，激西江之水而迎子，可乎？鮒魚曰：吾失我常與，我無所處。吾得斗升之水然活耳，君乃言此，曾不如早索我於枯魚之肆！』", "quote": "吾得斗升之水然活耳，君乃言此，曾不如早索我於枯魚之肆！", "desc": "比喻陷入極度困厄、急待援救之人。", "yin": "hé zhé zhī fù"}, {"rank": 431, "idiom": "白駒過隙", "pinyin": "bái jū guò xì", "origin": "《莊子·知北遊》", "story": "人生天地之間，若白駒之過郤，忽然而已。注然勃然，莫不出焉；油然漻然，莫不入焉。莊子借駿馬飛馳飛越牆縫之瞬息，體現生命之短促短暫，勸人淡泊名利，順應自然。", "quote": "人生天地之間，若白駒之過郤，忽然而已。", "desc": "形容光陰如駿馬掠過縫隙般極度短暫飛速。", "yin": "bái jū guò xì"}, {"rank": 430, "idiom": "貽笑大方", "pinyin": "yí xiào dà fāng", "origin": "《莊子·秋水》", "story": "河伯見海神若而嘆曰：『吾長見笑於大方之家。』大方之家指深明大道、博學高深之學者。河伯自省其原本驕矜自負，直至得見浩瀚汪洋，始知自己極其淺陋，免不了為識見廣大者所恥笑。", "quote": "吾長見笑於大方之家。", "desc": "指自己的淺陋見識被大方行家或學識淵博者所取笑。", "yin": "yí xiào dà fāng"}, {"rank": 429, "idiom": "青出於藍", "pinyin": "qīng chū yú lán", "origin": "《荀子·勸學》", "story": "君子曰：學不可以已。青，取之於藍，而青於藍；冰，水為之，而寒於水。木直中繩，輮以為輪，其曲中規。荀子以藍草提煉出的靛青比原料更青翠為喻，說明學術後進只要不懈修持，定能超越前代師長。", "quote": "青，取之於藍，而青於藍；冰，水為之，而寒於水。", "desc": "比喻後輩學生經過學習鑽研，成就超越了師輩。", "yin": "qīng chū yú lán"}, {"rank": 428, "idiom": "鍥而不捨", "pinyin": "qiè ér bù shě", "origin": "《荀子·勸學》", "story": "積土成山，風雨興焉；積水成淵，蛟龍生焉。騏驥一躍，不能十步；駑馬十駕，功在不捨。鍥而舍之，朽木不折；鍥而不捨，金石可鏤。荀子勉勵學者雕刻物體若堅持雕刻不放手，連堅硬如金石亦可雕琢成形。", "quote": "鍥而舍之，朽木不折；鍥而不捨，金石可鏤。", "desc": "比喻做事持之以恆，堅持到底絕不放棄。", "yin": "qiè ér bù shě"}, {"rank": 427, "idiom": "蓬生麻中", "pinyin": "péng shēng má zhōng", "origin": "《荀子·勸學》", "story": "蓬生麻中，不扶而直；白沙在涅，與之俱黑。蘭槐之根是為芷，其漸之滫，君子不近，庶人不服。其質非不美也，所漸者然也。荀子以蓬草長於麻叢自能挺立為喻，強調周圍客觀環境對人格修養具有莫大潛移默化之功。", "quote": "蓬生麻中，不扶而直；白沙在涅，與之俱黑。", "desc": "比喻處在良好環境薰陶之中，自然受到正面陶冶。", "yin": "péng shēng má zhōng"}, {"rank": 426, "idiom": "一鼓作氣", "pinyin": "yī gǔ zuò qì", "origin": "《左傳·莊公十年》", "story": "長勺之戰，魯莊公與齊師戰。公將鼓之，曹劌曰：『未可。』齊人三鼓。劌曰：『可矣。』齊師敗績。公問其故。對曰：『夫戰，勇氣也。一鼓作氣，再而衰，三而竭。彼竭我盈，故克之。』", "quote": "夫戰，勇氣也。一鼓作氣，再而衰，三而竭。彼竭我盈，故克之。", "desc": "比喻趁著士氣旺盛、幹勁最足時一口氣完成工作。", "yin": "yī gǔ zuò qì"}, {"rank": 425, "idiom": "居安思危", "pinyin": "jū ān sī wēi", "origin": "《左傳·襄公十一年》", "story": "晉侯以樂書賜魏絳。魏絳辭曰：『《書》曰：居安思危。思則有備，有備無患。敢以此規。』晉悼公八年間九合諸侯，天下和睦，魏絳力勸國君身處昇平安寧之時，尤當戒備隱患，預先周備以防不測。", "quote": "居安思危，思則有備，有備無患，敢以此規。", "desc": "指身處安定的境遇中，仍時刻防備可能發生的危難困厄。", "yin": "jū ān sī wēi"}, {"rank": 424, "idiom": "多行不義", "pinyin": "duō xíng bù yì", "origin": "《左傳·隱公元年》", "story": "鄭莊公弟共叔段恃寵生驕，招兵買馬收聚兩鄙，擴充私邑欲襲鄭都。祭仲諫莊公早除之，莊公曰：『多行不義必自斃，子姑待之。』後共叔段果然發動叛亂，眾叛親離，敗逃共國。", "quote": "多行不義必自斃，子姑待之。", "desc": "指壞事做多了終究自取滅亡。", "yin": "duō xíng bù yì"}, {"rank": 423, "idiom": "鞭長莫及", "pinyin": "biān zhǎng mò jí", "origin": "《左傳·僖公四年》", "story": "齊桓公率諸侯伐楚，楚使屈完來問罪。齊人管仲責楚包茅不入、昭王不復。屈完對曰：『君處北海，寡人處南海，唯是風馬牛不相及也。不虞君之涉吾地也，何故？』楚君臣亦謂晉楚殊途，古諺雲『雖鞭之長，不及馬腹』，勢力範圍無法跨越遠地。", "quote": "古人有言曰：雖鞭之長，不及馬腹。", "desc": "比喻力量達不到，無法予以顧及或控制。", "yin": "biān zhǎng mò jí"}, {"rank": 422, "idiom": "食言而肥", "pinyin": "shí yán ér féi", "origin": "《左傳·哀公二十五年》", "story": "魯哀公自越歸，季康子、孟武伯逆於五梧。郭重僕，見二子，曰：『惡言多矣，君請討之。』公宴於五梧，武伯為祝，惡郭重曰：『何肥也！』季孫曰：『請飲彘也。』公曰：『是食言多矣，能無肥乎？』諷刺孟武伯屢屢違背誓約承諾。", "quote": "是食言多矣，能無肥乎？", "desc": "比喻說話不算數，失信於人。", "yin": "shí yán ér féi"}, {"rank": 421, "idiom": "結草銜環", "pinyin": "jié cǎo xián huán", "origin": "《左傳·宣公十五年》/南朝梁·吳均《續齊諧記》", "story": "晉魏顆戰秦杜回，見一老人結草以亢杜回，杜回蹎而獲之。夜夢老人曰：『餘，爾所嫁婦人之父也。爾用先人之治命，嫁吾女，吾是以報。』後楊寶九歲時救黃雀，雀銜四白玉環報之，子孫世列三公。二典合稱結草銜環。", "quote": "魏顆結草以報恩，楊寶銜環以顯貴。", "desc": "比喻生死不忘大恩，誓死報答他人恩惠。", "yin": "jié cǎo xián huán"}, {"rank": 420, "idiom": "染指於鼎", "pinyin": "rǎn zhǐ yú dǐng", "origin": "《左傳·宣公四年》", "story": "楚人獻黿於鄭靈公。公子宋與子家將見。子公之食指動，以示子家，曰：『他日我如此，必嘗異味。』及入，宰夫將解黿，相視而笑。公問之，子家以告。及食大夫黿，召子公而弗與也。子公怒，染指於鼎，嘗之而出。", "quote": "子公怒，染指於鼎，嘗之而出。", "desc": "比喻插手分取不應得的利益，或涉足某項事務。", "yin": "rǎn zhǐ yú dǐng"}, {"rank": 419, "idiom": "問鼎中原", "pinyin": "wèn dǐng zhōng yuán", "origin": "《左傳·宣公三年》", "story": "楚莊王伐陸渾之戎，遂至洛，觀兵於周郊。周定王使王孫滿勞楚子。楚子問鼎之大小輕重焉。王孫滿對曰：『在德不在鼎。成王定鼎於郟鄏，卜世三十，卜年七百，天所命也。周德雖衰，天命未改。鼎之輕重，未可問也。』", "quote": "周德雖衰，天命未改。鼎之輕重，未可問也。", "desc": "比喻企圖奪取最高統治權，亦指爭奪大賽冠軍之位。", "yin": "wèn dǐng zhōng yuán"}, {"rank": 418, "idiom": "量力而行", "pinyin": "liàng lì ér xíng", "origin": "《左傳·昭公十五年》", "story": "晉荀躒如周，葬穆後。籍談為介。司徒問禮，籍談不能對。賓孟適至，曰：『君子能為可為，不能為不可為。量力而動，其過鮮矣。』告誡人當審察評估自身才識力量，不可盲目逞強。", "quote": "君子能為可為，不能為不可為。量力而動，其過鮮矣。", "desc": "指衡量自己的實力或能力而採取相應行動。", "yin": "liàng lì ér xíng"}, {"rank": 417, "idiom": "表裡山河", "pinyin": "biǎo lǐ shān hé", "origin": "《左傳·僖公二十八年》", "story": "城濮之戰，晉侯登有莘之虛以觀師，曰：『少長有禮，其可用也。』楚子玉恃強挑戰。子犯曰：『戰也！戰而捷，必得諸侯。若其不捷，表裡山河，必無害也。』指出晉國外有大河之阻，內倚高山之險，縱使失利亦有固守天塹。", "quote": "戰而捷，必得諸侯。若其不捷，表裡山河，必無害也。", "desc": "形容山河形勢內外環衛，險要易守難攻。", "yin": "biǎo lǐ shān hé"}, {"rank": 416, "idiom": "痛心疾首", "pinyin": "tòng xīn jí shǒu", "origin": "《左傳·成公十三年》", "story": "秦桓公背盟伐晉。晉厲公率諸侯伐秦，呂相移檄告絕秦國曰：『諸侯備聞此言，斯是用痛心疾首，暱就寡人。』痛陳秦國背德背信，天下諸侯聞之皆痛恨憤激入骨。", "quote": "諸侯備聞此言，斯是用痛心疾首，暱就寡人。", "desc": "形容痛恨到了極點，或為嚴重錯誤悔恨到了極點。", "yin": "tòng xīn jí shǒu"}, {"rank": 415, "idiom": "假道伐虢", "pinyin": "jiǎ dào fá guó", "origin": "《左傳·僖公二年》", "story": "晉荀息請以屈產之乘與垂棘之璧，假道於虞以伐虢。公曰：『是吾寶也。』荀息曰：『若得道於虞，猶外府也。』虞公貪璧馬，許晉伐虢。宮之奇諫不聽。晉軍滅虢，反拔虞，荀息牽璧馬以復晉獻公曰：『璧則猶是也，而馬齒亦微長矣。』", "quote": "荀息請以屈產之乘與垂棘之璧，假道於虞以伐虢。", "desc": "指藉口向對方借道，實則伺機將兩方一舉消滅之謀略。", "yin": "jiǎ dào fá guó"}, {"rank": 414, "idiom": "爾虞我詐", "pinyin": "ěr yú wǒ zhà", "origin": "《左傳·宣公十五年》", "story": "楚子圍宋，宋城中急，華元夜入楚師，登子反之床。子反驚問之。華元曰：『敝邑易子而食，析骸以爨。雖然，城下之盟，有以國斃，不能從也。去我三十里，唯命是聽。』楚軍遂退三十里，盟曰：『我無爾詐，爾無我虞。』", "quote": "宋及楚平。盟曰：我無爾詐，爾無我虞。", "desc": "形容人與人或勢力之間互相欺騙防範，勾心鬥角。", "yin": "ěr yú wǒ zhà"}, {"rank": 413, "idiom": "厲兵秣馬", "pinyin": "lì bīng mò mǎ", "origin": "《左傳·僖公三十三年》", "story": "秦穆公發兵襲鄭。鄭商人弦高販牛西入周，塗遇秦師，矯鄭伯之命，以十二牛犒秦師，且遣人馳報鄭國。鄭穆公使視客館，則束載、厲兵、秣馬矣。鄭國乃加強防備，秦師知鄭有備遂回。", "quote": "使視客館，則束載、厲兵、秣馬矣。", "desc": "形容磨快兵器、餵飽戰馬，積極做好戰鬥準備。", "yin": "lì bīng mò mǎ"}, {"rank": 412, "idiom": "眾志成城", "pinyin": "zhòng zhì chéng chéng", "origin": "《國語·周語下》", "story": "周景王將鑄大錢，單穆公諫之。後景王又鑄無射鐘，伶州鳩諫曰：『夫民情之所欲，神必從之。晉文公能合諸侯之志，故霸。諺曰：眾心成城，眾口鑠金。三川震，民心搖，國危矣。』警醒統治者萬民一心方如鋼鐵長城般堅固。", "quote": "諺曰：眾心成城，眾口鑠金。", "desc": "比喻萬眾一心，團結一致，力量便無比堅固強大。", "yin": "zhòng zhì chéng chéng"}, {"rank": 411, "idiom": "防民之口", "pinyin": "fáng mín zhī kǒu", "origin": "《國語·周語上》", "story": "周厲王虐，國人謗王。召穆公諫曰：『民不堪命矣！』王怒，得衛巫，使監謗者。以告，則殺之。國人莫敢言，道路以目。王喜，告召公曰：『吾能弭謗矣，乃不敢言。』召公曰：『是障之也。防民之口，甚於防川。川壅而潰，傷人必多，民亦如之。』厲王不聽，三年，流王於彘。", "quote": "防民之口，甚於防川。川壅而潰，傷人必多，民亦如之。", "desc": "指阻止人民發表批評言論，引發的後患比堵塞河川決堤更危險。", "yin": "fáng mín zhī kǒu"}, {"rank": 410, "idiom": "狡兔三窟", "pinyin": "jiǎo tù sān kū", "origin": "《戰國策·齊策四》", "story": "馮諼客孟嘗君。馮諼市義於薛，焚券還民。後齊王廢孟嘗君，孟嘗君就國於薛，未至百里，民扶老攜幼迎之。馮諼曰：『狡兔有三窟，僅得免其死耳。今君有一窟，未得高枕而臥也。請為君復鑿二窟。』乃遊魏引魏聘孟嘗君，齊王大驚，復請為相，建宗廟於薛。孟嘗君為相數十年無纖介之禍。", "quote": "狡兔有三窟，僅得免其死耳。今君有一窟，未得高枕而臥也。", "desc": "比喻有多處避難場所或藏身退路，防範意外禍患。", "yin": "jiǎo tù sān kū"}, {"rank": 409, "idiom": "前事不忘", "pinyin": "qián shì bù wàng", "origin": "《戰國策·趙策一》", "story": "張孟談既固趙宗，辭賞退隱。趙襄子欲留之，孟談曰：『昔者知伯之驕，在於自矜。前事之不忘，後事之師也。臣功高位隆，若不引退，難保終吉。』襄子乃從之。孟談全名保身。", "quote": "前事之不忘，後事之師也。", "desc": "指記取以往的經驗教訓，可作為日後行事的借鑑法式。", "yin": "qián shì bù wàng"}, {"rank": 408, "idiom": "懸梁刺股", "pinyin": "xuán liáng cì gǔ", "origin": "《戰國策·秦策一》/《太平御覽》", "story": "蘇秦始將連橫說秦惠王，書十上而說不行，黑貂之裘弊，黃金百斤盡，歸家妻不下紝，嫂不為炊。蘇秦乃發憤閉門讀書，讀書欲睡，引錐自刺其股，血流至足。東漢孫敬好學，晨夕不休，以繩系頭，懸屋樑以防瞌睡。二人刻苦自勵，卒成大器。", "quote": "蘇秦讀書欲睡，引錐自刺其股，血流至足；孫敬以繩繫髮懸梁。", "desc": "形容刻苦攻讀，勤奮不輟之頑強求學精神。", "yin": "xuán liáng cì gǔ"}, {"rank": 407, "idiom": "羽毛未豐", "pinyin": "yǔ máo wèi fēng", "origin": "《戰國策·秦策一》", "story": "蘇秦說秦王書十上而說不行。秦惠王曰：『寡人聞之：毛羽不豐滿者，不可以高飛；文章不成者，不可以誅罰；道德不厚者，不可以使民；政教不順者，不可以煩大臣。今先生儼然不遠千里而庭教之，願以異日。』拒納其策。", "quote": "毛羽不豐滿者，不可以高飛；文章不成者，不可以誅罰。", "desc": "比喻實力勢力尚淺薄稚嫩，條件尚未成熟。", "yin": "yǔ máo wèi fēng"}, {"rank": 406, "idiom": "千金買骨", "pinyin": "qiān jīn mǎi gǔ", "origin": "《戰國策·燕策一》", "story": "燕昭王即位，卑身厚幣以招賢。郭隗曰：『古之君王有以千金使涓人求千里馬者，得死馬骨以五百金返。君大怒，涓人曰：死馬且買五百金，況生馬乎？天下必以王為能致馬。不出年，千里馬至者三。今王欲致士，先從隗始。隗且見事，況賢於隗者乎？』昭王築黃金臺師郭隗，樂毅、鄒衍皆至。", "quote": "死馬且市之五百金，況生馬乎？天下必以王為能致馬矣。", "desc": "比喻統治者誠心重金求賢，以激勵海內英才紛至沓來。", "yin": "qiān jīn mǎi gǔ"}, {"rank": 405, "idiom": "安步當車", "pinyin": "ān bù dàng chē", "origin": "《戰國策·齊策四》", "story": "齊宣王見顏斶，曰：『斶前！』斶亦曰：『王前！』宣王不悅。斶曰：『斶前為慕勢，王前為趨賢。』乃極論士貴王不貴。宣王慚服，請為弟子，受以高爵厚祿。斶辭曰：『夫玉生於山，制則破焉；士生於鄙野，推選則祿焉。斶願得歸，晚食以當肉，安步以當車，無罪以當貴，清靜貞正以自虞。』", "quote": "晚食以當肉，安步以當車，無罪以當貴，清靜貞正以自虞。", "desc": "指從容徐步行走，如同乘車般安閒自在。", "yin": "ān bù dàng chē"}, {"rank": 404, "idiom": "積羽沉舟", "pinyin": "jī yǔ chén zhōu", "origin": "《戰國策·魏策一》", "story": "張儀為秦連橫說魏哀王曰：『臣聞積羽沉舟，群輕折軸，眾口鑠金，積毀銷骨。故願大王審定計策，與秦連橫。』說明羽毛雖輕，聚積日多亦能壓沉巨舟，細微弱小之勢聚多便不可忽視。", "quote": "積羽沉舟，群輕折軸，眾口鑠金，積毀銷骨。", "desc": "比喻細微之物積聚過多，亦能釀成巨重之災禍。", "yin": "jī yǔ chén zhōu"}, {"rank": 403, "idiom": "一諾千金", "pinyin": "yī nuò qiān jīn", "origin": "《史記·季布欒佈列傳》", "story": "季布為楚人，為氣任俠，有名於楚。項羽滅，高祖購求布千金。後夏侯嬰說高祖赦布，拜郎中。楚人諺曰：『得黃金百斤，不如得季布一諾。』足見其為人極重信義，凡答應之事必竭力踐諾。", "quote": "楚人諺曰：得黃金百斤，不如得季布一諾。", "desc": "形容信用極好，一句許諾比千兩黃金還要珍貴。", "yin": "yī nuò qiān jīn"}, {"rank": 402, "idiom": "一飯千金", "pinyin": "yī fàn qiān jīn", "origin": "《史記·淮陰侯列傳》", "story": "韓信始為布衣，貧無行，釣於城下。諸漂母漂，有一母見信飢，飯信，竟漂數十日。信喜，謂漂母曰：『吾必有以重報母。』母怒曰：『大丈夫不能自食，吾哀王孫而進食，豈望報乎！』後信為楚王，召漂母，賜千金以報之。", "quote": "韓信至國，召所從食漂母，賜千金。", "desc": "比喻受人微小恩惠，日後定當厚重報答。", "yin": "yī fàn qiān jīn"}, {"rank": 401, "idiom": "胯下之辱", "pinyin": "kuà xià zhī rǔ", "origin": "《史記·淮陰侯列傳》", "story": "淮陰屠中少年有侮信者，曰：『若雖長大，好帶刀劍，中情怯耳。』眾辱之曰：『信能死，刺我；不能死，出我胯下。』於是信孰視之，俛出袴下，蒲伏。一市人皆笑信，以為怯。信終忍辱負重，拜為大將軍封王。", "quote": "淮陰屠中少年有侮信者，信孰視之，俛出袴下，蒲伏。一市人皆笑信以為怯。", "desc": "比喻有大志遠猷者能忍耐眼前的奇恥大辱以成宏偉事業。", "yin": "kuà xià zhī rǔ"}, {"rank": 400, "idiom": "背水一戰", "pinyin": "bèi shuǐ yī zhàn", "origin": "《史記·淮陰侯列傳》", "story": "井陘之戰，韓信引兵數萬伐趙。令萬人先行，出，背水陳。趙軍望見而大笑。平旦，信建大將旗鼓，馳下井陘狹道，與趙軍大戰，佯敗棄旗鼓走水上軍。趙空壁爭逐，漢兵背水無退路，皆殊死作戰，人自為戰。漢伏兵馳入趙壁拔趙幟，立漢赤幟二千。趙軍潰亂，遂斬陳餘，擒趙王歇。", "quote": "信乃使萬人先行，出，背水陳。軍皆殊死戰，不可敗。", "desc": "比喻處於絕境無退路之下，奮力拚搏以求死裡求生。", "yin": "bèi shuǐ yī zhàn"}, {"rank": 399, "idiom": "拔旗易幟", "pinyin": "bá qí yì zhì", "origin": "《史記·淮陰侯列傳》", "story": "韓信破趙，夜半傳發，選輕騎二千人，人持一赤幟，從間道萆山而望趙軍。誡曰：『趙見我走，必空壁逐我。若疾入趙壁，拔趙幟，立漢赤幟。』趙兵果悉索而出爭搶旗鼓，漢騎乘虛馳入，盡拔趙軍旗幟，改立漢軍赤旗，趙軍回頭望見大恐奔潰。", "quote": "若疾入趙壁，拔趙幟，立漢赤幟。", "desc": "比喻徹底攻佔敵方陣地，亦比喻變更政權或取而代之。", "yin": "bá qí yì zhì"}, {"rank": 398, "idiom": "圖窮匕見", "pinyin": "tú qióng bǐ jiàn", "origin": "《史記·刺客列傳》", "story": "燕太子丹使荊軻入秦刺秦王。荊軻奉燕督亢之地圖，函封樊於期之頭，入獻秦王。秦王大喜，見軻於鹹陽宮。荊軻取圖奉之，發圖，圖窮而匕首見。因左手把秦王之袖，而右手持匕首揕之。未至身，秦王驚，引疾而起，絕袖。秦王環柱而走，卒斷荊軻股而誅之。", "quote": "荊軻取圖奉之，發圖，圖窮而匕首見。", "desc": "比喻事情發展到最後階段，真實陰謀或底牌徹底暴露露陷。", "yin": "tú qióng bǐ jiàn"}, {"rank": 397, "idiom": "怒髮衝冠", "pinyin": "nù fà chōng guān", "origin": "《史記·廉頗藺相如列傳》", "story": "藺相如奉璧入秦，秦王坐章臺見相如，相如奉璧。秦王大喜，傳以示美人及左右，左右皆呼萬歲。相如視秦王無意償趙城，乃前曰：『璧有瑕，請指示王。』王授璧，相如因持璧卻立，倚柱，怒髮上衝冠，厲斥秦王欺詐無禮。", "quote": "相如因持璧卻立，倚柱，怒髮上衝冠。", "desc": "形容憤怒到了極點，頭髮直豎幾乎頂起帽子。", "yin": "nù fà chōng guān"}, {"rank": 396, "idiom": "慷慨悲歌", "pinyin": "kāng kǎi bēi gē", "origin": "《史記·刺客列傳》", "story": "太子及賓客知其事者，皆白衣冠以送荊軻。至易水之上，既祖，取道。高漸離擊築，荊軻和而歌，為變徵之聲，士皆垂淚涕泣。又前而為歌曰：『風蕭蕭兮易水寒，壯士一去兮不復還！』復為羽聲慷慨，士皆瞋目，髮盡上指冠。於是荊軻遂就車而去，終已不顧。", "quote": "風蕭蕭兮易水寒，壯士一去兮不復還！復為羽聲慷慨，士皆瞋目，髮盡上指冠。", "desc": "形容情緒激昂、意氣豪邁而悲壯動人。", "yin": "kāng kǎi bēi gē"}, {"rank": 395, "idiom": "奇貨可居", "pinyin": "qí huò kě jū", "origin": "《史記·呂不韋列傳》", "story": "陽翟大賈呂不韋往來販賤賣貴，家累千金。往邯鄲，見秦質子異人，歸而謂父曰：『耕田之利幾倍？』曰：『十倍。』『珠玉之贏幾倍？』曰：『百倍。』『立國家之主贏幾倍？』曰：『無數。』呂不韋乃曰：『此奇貨可居！』乃資千金遊秦，立異人為太子，終拜丞相。", "quote": "子楚，秦諸庶孽孫，質於諸侯。呂不韋見而憐之，曰：此奇貨可居。", "desc": "指把稀罕少見的物品或有潛力的人物囤積控制，以待日後獲取暴利。", "yin": "qí huò kě jū"}, {"rank": 394, "idiom": "指鹿為馬", "pinyin": "zhǐ lù wèi mǎ", "origin": "《史記·秦始皇本紀》", "story": "趙高欲為亂，恐群臣不聽，乃先設驗，持鹿獻於二世，曰：『馬也。』二世笑曰：『丞相誤邪？謂鹿為馬。』問左右，左右或默，或言馬以阿順趙高。或言鹿者，高因陰中諸言鹿者以法。後群臣皆畏高，莫敢糾其非。", "quote": "趙高欲為亂，恐群臣不聽，乃先設驗，持鹿獻於二世，曰：馬也。", "desc": "比喻故意混淆黑白，顛倒是非以作威作福。", "yin": "zhǐ lù wèi mǎ"}, {"rank": 393, "idiom": "項莊舞劍", "pinyin": "xiàng zhuāng wǔ jiàn", "origin": "《史記·項羽本紀》", "story": "鴻門宴上，范增數目項王，舉所佩玉玦以示之者三，項王默然不應。范增起，出召項莊，謂曰：『君王為人不忍。若入前為壽，壽畢，請以劍舞，因擊沛公於坐，殺之。不者，若屬皆且為所虜！』莊入為壽，請劍舞。項伯亦拔劍起舞，常以身翼蔽沛公，莊不得擊。", "quote": "項莊拔劍起舞。項伯亦拔劍起舞，常以身翼蔽沛公，莊不得擊。", "desc": "比喻說話或行事表面上是一套，暗地裡另有險惡針對的意圖。", "yin": "xiàng zhuāng wǔ jiàn"}, {"rank": 392, "idiom": "秋毫無犯", "pinyin": "qiū háo wú fàn", "origin": "《史記·淮陰侯列傳》/《史記·項羽本紀》", "story": "韓信說漢王曰：『項王雖霸天下而臣諸侯，不居關中而都彭城；背義帝之約，而以親愛王諸侯，不平。諸侯之見項王遷逐義帝江南，亦皆歸逐其主而自王善地。項王所過無不殘滅者，天下多怨，百姓不附。沛公入關，秋毫無所害，除秦苛法，與民約法三章，秦民莫不欲得沛公為王。』", "quote": "沛公入關，秋毫無所害，除秦苛法，與秦民約法三章耳。", "desc": "形容軍隊紀律嚴明，對百姓絲毫不加騷擾侵害。", "yin": "qiū háo wú fàn"}, {"rank": 391, "idiom": "錦衣夜行", "pinyin": "jǐn yī yè xíng", "origin": "《史記·項羽本紀》", "story": "項羽引兵西屠鹹陽，殺秦降王子嬰，燒秦宮室，火三月不滅，收其寶貨婦女而東。人說項王曰：『關中阻山河四塞，地肥饒，可都以霸。』項王見秦宮室皆已燒殘，又心懷思欲東歸，曰：『富貴不歸故鄉，如衣繡夜行，誰知之者！』說者曰：『人言楚人沐猴而冠耳，果然。』項王聞之，烹說者。", "quote": "富貴不歸故鄉，如衣繡夜行，誰知之者！", "desc": "比喻雖有顯赫成就富貴，卻不能在故土親友面前展示展現。", "yin": "jǐn yī yè xíng"}, {"rank": 390, "idiom": "取而代之", "pinyin": "qǔ ér dài zhī", "origin": "《史記·項羽本紀》", "story": "秦始皇帝遊會稽，渡浙江，梁與籍俱觀。籍大言曰：『彼可取而代也！』梁掩其口，曰：『毋妄言，族矣！』梁以此奇籍。項羽年少即有吞吐宇宙、推翻暴秦之雄心霸氣。", "quote": "秦始皇帝遊會稽，梁與籍俱觀。籍曰：彼可取而代也！", "desc": "指推翻既有統治者或佔據者，自己取而替代其地位。", "yin": "qǔ ér dài zhī"}, {"rank": 389, "idiom": "多多益善", "pinyin": "duō duō yì shàn", "origin": "《史記·淮陰侯列傳》", "story": "高祖嘗從容與信言諸將能不，各有差。上問曰：『如我能將幾何？』信曰：『陛下不過能將十萬。』上曰：『於君何如？』曰：『臣多多而益善耳。』上笑曰：『多多益善，何為為我禽？』信曰：『陛下不能將兵，而善將將，此乃信之所以為陛下禽也。』", "quote": "上曰：於君何如？曰：臣多多而益善耳。", "desc": "形容數量越多越好，毫不嫌多。", "yin": "duō duō yì shàn"}, {"rank": 388, "idiom": "鳥盡弓藏", "pinyin": "niǎo jǐn gōng cáng", "origin": "《史記·越王句踐世家》/《史記·淮陰侯列傳》", "story": "范蠡遂去，自齊遺大夫種書曰：『蜚鳥盡，良弓藏；狡兔死，走狗烹。越王為人長頸鳥喙，可與共患難，不可與共樂。子何不去？』種稱病不朝，越王賜劍曰：『子教寡人伐吳七術，寡人用其三而敗吳，其四在子，子為我從先王試之。』種遂伏劍自刎。", "quote": "蜚鳥盡，良弓藏；狡兔死，走狗烹。", "desc": "比喻天下大定或事情成功之後，功臣被拋棄乃至殺害。", "yin": "niǎo jǐn gōng cáng"}, {"rank": 387, "idiom": "一字千金", "pinyin": "yī zì qiān jīn", "origin": "《史記·呂不韋列傳》", "story": "呂不韋使客著《呂氏春秋》，八覽、六論、十二紀，二十餘萬言，以為備天地萬物古今之事。布鹹陽市門，懸千金其上，延諸侯遊士賓客，有能增損一字者予千金。天下莫能出其右者。", "quote": "布鹹陽市門，懸千金其上，延諸侯遊士賓客，有能增損一字者予千金。", "desc": "形容文字造詣精深高妙，文章價值無可估量。", "yin": "yī zì qiān jīn"}, {"rank": 386, "idiom": "門庭若市", "pinyin": "mén tíng ruò shì", "origin": "《戰國策·齊策一》", "story": "齊鄒忌修八尺有餘，昳麗，自比城北徐公。納諫威王：『王之蔽甚矣！』威王下令：『群臣吏民能面刺寡人之過者，受上賞；上書諫寡人者，受中賞；能謗譏於市朝，聞寡人之耳者，受下賞。』令初下，群臣進諫，門庭若市；數月之後，時時而間進；期年之後，雖欲言，無可進者。燕趙韓魏聞之，皆朝於齊。", "quote": "令初下，群臣進諫，門庭若市。", "desc": "形容來訪造訪者眾多，門前人頭攢動熱鬧非凡。", "yin": "mén tíng ruò shì"}, {"rank": 385, "idiom": "作法自斃", "pinyin": "zuò fǎ zì bì", "origin": "《史記·商君列傳》", "story": "商君相秦十年，宗室貴戚多怨望。孝公卒，太子立。惠王下令捕商君。商君亡至關下，欲舍客舍。客人不知其是商君也，曰：『商君之法，舍人無驗者坐之。』商君喟然歎曰：『嗟乎，為法之敝一至此哉！』去之魏，魏不受，乃反秦，為秦軍殺於鄭黽，車裂商君以殉。", "quote": "商君喟然歎曰：嗟乎，為法之敝一至此哉！", "desc": "比喻自己定下的嚴法苛規，最終反倒害了自己。", "yin": "zuò fǎ zì bì"}, {"rank": 384, "idiom": "紙上談兵", "pinyin": "zhǐ shàng tán bīng", "origin": "《史記·廉頗藺相如列傳》", "story": "趙括自少時學兵法，言兵事，以天下莫能當。嘗與其父奢言兵事，奢不能難，然不謂善。括母問其故，奢曰：『兵，死地也，而括易言之。使趙不將括即已，若必將之，破趙軍者必括也。』後趙王以括代廉頗於長平，括一改廉頗壁壘約束，出兵擊秦，秦將白起詐走，誘趙軍入伏，絕其糧道四十六日，坑趙卒四十萬。", "quote": "兵，死地也，而括易言之。使趙不將括即已，若必將之，破趙軍者必括也。", "desc": "比喻空談理論教條，毫無實戰與實際經驗，終致慘敗。", "yin": "zhǐ shàng tán bīng"}, {"rank": 383, "idiom": "雞鳴狗盜", "pinyin": "jī míng gǒu dào", "origin": "《史記·孟嘗君列傳》", "story": "齊孟嘗君出使於秦，昭王囚欲殺之。孟嘗君使人抵昭王幸姬求救，姬曰：『願得君狐白裘。』孟嘗君客有善狗盜者，夜入秦宮藏，得狐白裘獻姬，姬為言，得釋。馳出關，夜半至函谷關，秦法雞鳴而出客。客有善為雞鳴者，野雞皆鳴，孟嘗君遂得出關。昭王追之不及。", "quote": "始孟嘗君之入秦，客有善狗盜者，夜取狐白裘；有客善為雞鳴，關吏乃出客。", "desc": "指身懷微賤伎倆技能之人，亦比喻偷偷摸摸下作之徒。", "yin": "jī míng gǒu dào"}, {"rank": 382, "idiom": "脫穎而出", "pinyin": "tuō yǐng ér chū", "origin": "《史記·平原君虞卿列傳》", "story": "平原君將合從於楚，毛遂請自薦。平原君曰：『夫賢士之處世，譬如錐之處囊中，其末立見。今先生三年無聞，無能也。』毛遂曰：『臣乃今日請處囊中耳！使遂蚤得處囊中，乃穎脫而出，非特其末見而已。』後毛遂按劍登殿，面折楚王，定楚趙十九人之合從。", "quote": "使遂蚤得處囊中，乃穎脫而出，非特其末見而已。", "desc": "比喻人的本領才能在適當時機全面顯露發揮。", "yin": "tuō yǐng ér chū"}, {"rank": 381, "idiom": "錐處囊中", "pinyin": "zhuī chù náng zhōng", "origin": "《史記·平原君虞卿列傳》", "story": "平原君以錐子放在口袋中，尖銳之鋒芒自然刺穿口袋顯露出來為喻，認為有才能之人必然隨時隨地能顯現其傑出名望與實力。", "quote": "夫賢士之處世也，譬若錐之處囊中，其末立見。", "desc": "比喻真正富有才華實力者，鋒芒終究難以被埋沒隱藏。", "yin": "zhuī chù náng zhōng"}, {"rank": 380, "idiom": "同舟共濟", "pinyin": "tóng zhōu gòng jì", "origin": "《孫子·九地》", "story": "孫子曰：『夫吳人與越人相惡也，當其同舟而濟，遇風，其相救也如左右手。』說明縱使平日仇深似海，身處同一艘風浪中的危舟時，為保全性命亦必須齊心合力、同舟共濟。", "quote": "夫吳人與越人相惡也，當其同舟而濟，遇風，其相救也如左右手。", "desc": "比喻同心協力，共同克服重重艱難險阻。", "yin": "tóng zhōu gòng jì"}, {"rank": 379, "idiom": "刎頸之交", "pinyin": "wěn jǐng zhī jiāo", "origin": "《史記·廉頗藺相如列傳》", "story": "廉頗肉袒負荊謝罪，藺相如扶起之。二人俱以國家江山社稷為重，深相敬重，相與歡笑，遂成生平生死之交。卒相與為刎頸之交，誓同生死，患難與共，外敵強秦不敢正眼窺趙三十載。", "quote": "卒相與歡，為刎頸之交。", "desc": "比喻可以割頸同死、互託性命之最深摯篤厚的友誼。", "yin": "wěn jǐng zhī jiāo"}, {"rank": 378, "idiom": "投筆從戎", "pinyin": "tóu bǐ cóng róng", "origin": "《後漢書·班超傳》", "story": "班超為人有大志，家貧，常為官府抄書以供養母親，久勞苦。嘗輟業投筆歎曰：『大丈夫無它志略，猶當效傅介子、張騫立功異域，以取封侯，安能久事筆研間乎？』後率三十六人撫平西域五十餘國，官封定遠侯。", "quote": "大丈夫無它志略，猶當效傅介子、張騫立功異域，以取封侯，安能久事筆研間乎？", "desc": "指拋棄文墨案牘工作，毅然參軍投身保家衛國之戰鬥。", "yin": "tóu bǐ cóng róng"}, {"rank": 377, "idiom": "不入虎穴", "pinyin": "bù rù hǔ xué", "origin": "《後漢書·班超傳》", "story": "班超使鄯善，匈奴使亦至，鄯善王敬禮漸疏。超召其部下三十六人飲酒，激厲之曰：『不入虎穴，不得虎子。當今之計，獨有因夜以火攻虜使，彼不知我人數，必大震怖，乃可殄盡也。』乃親率士卒夜燒匈奴使營，斬首百餘級，鄯善舉國震懾降漢。", "quote": "超曰：不入虎穴，不得虎子。當今之計，獨有因夜以火攻虜使。", "desc": "比喻不冒艱險深入絕境，就無法取得重大的突破與勝利。", "yin": "bù rù hǔ xué"}, {"rank": 376, "idiom": "請纓報國", "pinyin": "qǐng yīng bào guó", "origin": "《漢書·終軍傳》", "story": "終軍字子雲，年十八選為博士弟子。南越與漢和親，軍自請願受長纓，必羈南越王而致之闕下。漢武帝壯其節，遣軍往使。軍至南越，說服南越王降漢請置吏，其慷慨請纓成為後世青年從軍報國之楷模。", "quote": "軍自請：願受長纓，必羈南越王而致之闕下。", "desc": "比喻熱血青年主動請領重任，投身報效國家。", "yin": "qǐng yīng bào guó"}, {"rank": 375, "idiom": "舉案齊眉", "pinyin": "jǔ àn qí méi", "origin": "《後漢書·逸民傳·梁鴻》", "story": "梁鴻尚孟光，孟光力作同甘共苦。至吳，依大家皋伯通，居廡下，為人賃舂。每歸，妻為具食，不敢於鴻前仰視，舉案齊眉。伯通見之驚曰：『彼傭也，使其妻敬之如此，非凡人也！』乃舍之於家，鴻因得潛心著書十餘篇。", "quote": "每歸，妻為具食，不敢於鴻前仰視，舉案齊眉。", "desc": "形容夫妻之間相互敬重相愛，相敬如賓。", "yin": "jǔ àn qí méi"}, {"rank": 374, "idiom": "推心置腹", "pinyin": "tuī xīn zhì fù", "origin": "《後漢書·光武帝紀》", "story": "光武帝劉秀降銅馬流寇百萬，拜其渠帥為列侯。降者猶懷疑懼不自安。光武乃敕令降將各歸本營，勒兵嚴備；光武輕騎巡行各營，神色坦然毫無戒備之色。降賊相謂曰：『蕭王推赤心置人腹中，安得不反死乎！』由是皆傾心歸附。", "quote": "降者更相謂曰：蕭王推赤心置人腹中，安得不反死乎！", "desc": "比喻真心誠意待人，坦誠相見毫不隱瞞防範。", "yin": "tuī xīn zhì fù"}, {"rank": 373, "idiom": "水落石出", "pinyin": "shuǐ luò shí chū", "origin": "宋·蘇軾《後赤壁賦》", "story": "是歲十月之望，蘇軾步自雪堂，將歸於臨皋。二客從予過黃泥之坂。江流有聲，斷岸千尺；山高月小，水落石出。曾日月之幾何，而江山不可復識矣！蘇子攀棲鶻之危巢，俯馮夷之幽宮，發天地自然蕭瑟純粹之至理。", "quote": "江流有聲，斷岸千尺；山高月小，水落石出。", "desc": "原指冬日江水退落水底頑石顯露，後比喻事情真相徹底大白。", "yin": "shuǐ luò shí chū"}, {"rank": 372, "idiom": "奉公守法", "pinyin": "fèng gōng shǒu fǎ", "origin": "《史記·廉頗藺相如列傳》", "story": "趙奢為田部吏，收租稅。平原君家不肯出，趙奢以法治之，殺平原君用事者九人。平原君怒，欲殺奢。奢因說曰：『君於趙為貴公子，今縱君家而不奉公則法削，法削則國弱，國弱則諸侯加兵，諸侯加兵是無趙也，君安得有此富乎？以君之貴，奉公如法則上下平，上下平則國強。』平原君賢之，薦於王，趙奢遂為大將。", "quote": "以君之貴，奉公如法則上下平，上下平則國強。", "desc": "形容克己奉公，恪盡職守，嚴格遵守國家律法紀律。", "yin": "fèng gōng shǒu fǎ"}, {"rank": 371, "idiom": "家徒四壁", "pinyin": "jiā tú sì bì", "origin": "《史記·司馬相如列傳》", "story": "司馬相如客臨邛，卓文君夜奔相如。相如馳歸成都，買田宅貧甚，家居徒四壁立。文君久之不樂，乃與相如俱至臨邛，盡賣車騎，買一酒舍酤酒，文君當壚，相如滌器於市中。卓王孫大慚，分資百萬，文君相如遂成鉅富。", "quote": "文君夜亡奔相如，相如乃與馳歸成都。家居徒四壁立。", "desc": "形容家境極端貧寒困窘，室內除四面牆壁別無長物。", "yin": "jiā tú sì bì"}, {"rank": 370, "idiom": "勢如破竹", "pinyin": "shì rú pò zhú", "origin": "《晉書·杜預傳》", "story": "杜預帥大軍伐吳，破西陵，克江陵，沅湘以南諸郡望風歸順。時朝議以春水暴漲不可久留，預曰：『今兵威已振，譬如破竹，數節之後，皆迎刃而解，無復著手處也。』遂指授諸將直取建康，孫皓面縛輿櫬出降，三國歸晉。", "quote": "今兵威已振，譬如破竹，數節之後，皆迎刃而解，無復著手處也。", "desc": "形容形勢進展勢不可擋，順利解決接踵而來之問題。", "yin": "shì rú pò zhú"}, {"rank": 369, "idiom": "逐客之令", "pinyin": "zhú kè zhī lìng", "origin": "《史記·李斯列傳》", "story": "秦王政十年，韓國水工鄭國間諜事發，秦宗室大臣皆言於秦王曰：『諸侯人來事秦者，大抵為其主遊間於秦耳，請一切逐客。』李斯議亦在逐中，乃上《諫逐客書》，博引穆公、孝公、惠王、昭王用客致霸之史實，力證太山不讓土壤故能成其大，秦王乃悟，立除逐客之令。", "quote": "泰山不讓土壤，故能成其大；河海不擇細流，故能就其深。秦王乃除逐客之令。", "desc": "指主人驅逐賓客或組織排擠外來賢才的命令。", "yin": "zhú kè zhī lìng"}, {"rank": 368, "idiom": "禍起蕭牆", "pinyin": "huò qǐ xiāo qiáng", "origin": "《論語·季氏》", "story": "季氏將伐顓臾。孔子曰：『求！無乃爾是過與？丘也聞有國有家者，不患寡而患不均，不患貧而患不安。蓋均無貧，和無寡，安無傾。今夫顓臾，固而近於費，今不取，後世必為子孫憂。吾恐季孫之憂，不在顓臾，而在蕭牆之內也！』揭示內亂往往始於門牆內部政爭。", "quote": "吾恐季孫之憂，不在顓臾，而在蕭牆之內也。", "desc": "比喻內部發生重大糾紛變故或災禍。", "yin": "huò qǐ xiāo qiáng"}, {"rank": 367, "idiom": "金石為開", "pinyin": "jīn shí wèi kāi", "origin": "漢·劉向《新序·雜事四》/《後漢書·廣陵思王荊傳》", "story": "楚熊渠子夜行，見寢石以為伏虎，彎弓射之，沒金飲羽，下視知其石也。因復射之，矢摧無跡。漢李廣出獵亦射石陷羽。古人謂精誠所至，金石為開，意志專一至極，天地頑石亦能為之洞穿折服。", "quote": "精誠所至，金石為開。", "desc": "比喻只要心意精誠執著到了極點，多大困難都能迎刃化解。", "yin": "jīn shí wèi kāi"}, {"rank": 366, "idiom": "運籌決勝", "pinyin": "yùn chóu jué shèng", "origin": "《漢書·高帝紀》", "story": "漢高祖論張良運籌帷幄決勝千里，指出天下之大爭非徒憑武夫匹夫之勇，決勝大計全在帷帳深處審時度勢、周密佈局之高瞻遠矚。", "quote": "夫運籌帷幄之中，決勝千里之外，吾不如子房。", "desc": "指在後方精心籌劃制定克敵制勝之大戰略。", "yin": "yùn chóu jué shèng"}, {"rank": 365, "idiom": "差強人意", "pinyin": "chā qiáng rén yì", "origin": "《後漢書·吳漢傳》", "story": "吳漢為人忠勇質樸，每隨光武徵戰，諸將敗退失色，漢神色自若，整厲兵器，繕治士卒。帝見之歎曰：『吳公差強人意，隱若一敵國矣！』在全軍頹靡之時，唯吳漢振奮士氣，令人振作滿意。", "quote": "帝時遣人觀大司馬何為，還言方修戰具，乃歎曰：吳公差強人意，隱若一敵國矣！", "desc": "原指尚能振奮人心，現多指勉強令人滿意。", "yin": "chā qiáng rén yì"}, {"rank": 364, "idiom": "疾風勁草", "pinyin": "jí fēng jìn cǎo", "origin": "《後漢書·王霸傳》", "story": "王霸少有志節。光武起兵，霸從擊邯鄲。同舍生多以途艱離散去，唯霸獨留不改。光武感慨謂霸曰：『潁川從我者皆逝矣，而子獨留努力，疾風知勁草，嚴霜識貞木，信矣哉！』封霸為關內侯。", "quote": "光武謂霸曰：潁川從我者皆逝，而子獨留努力，疾風知勁草，信矣哉！", "desc": "比喻在艱危嚴峻的考驗面前，才能彰顯剛毅堅定的節操品質。", "yin": "jí fēng jìn cǎo"}, {"rank": 363, "idiom": "乘風破浪", "pinyin": "chéng fēng pò làng", "origin": "《宋書·宗愨傳》", "story": "宗愨字元幹，少時有膽氣，好武藝。叔父炳問其志向，愨慨然答曰：『願乘長風破萬裡浪！』炳深贊其志：『汝不富貴，即破我家矣。』後宗愨從徵林邑，屢立奇功，勇冠三軍，官至左衛將軍。", "quote": "愨少時，炳問其所志，愨曰：願乘長風破萬裡浪。", "desc": "比喻志向高遠廣大，不懼艱險奮勇前進。", "yin": "chéng fēng pò làng"}, {"rank": 362, "idiom": "樂不思蜀", "pinyin": "lè bù sī shǔ", "origin": "《三國志·蜀書·後主傳》裴松之注引《漢晉春秋》", "story": "蜀降魏，司馬昭封劉禪為安樂公。昭宴禪，使作蜀技，旁人皆為之感愴，禪怡然自若。昭謂賈充曰：『人之無情，乃可至於是乎！』他日，昭問禪曰：『頗思蜀否？』禪答曰：『此間樂，不思蜀。』郤正聞之，教禪以悲感對，昭又問，禪如正言對，昭笑曰：『何乃似郤正語邪！』禪驚視曰：『誠如尊命。』左右皆笑。", "quote": "司馬文王問禪曰：頗思蜀否？禪曰：此間樂，不思蜀。", "desc": "比喻留戀新環境的安樂享受，忘記了故土責任或家國根本。", "yin": "lè bù sī shǔ"}, {"rank": 361, "idiom": "倒行逆施", "pinyin": "dào xíng nì shī", "origin": "《史記·伍子胥列傳》", "story": "伍子胥父兄為楚平王所殺，子胥奔吳，引吳兵破楚入郢。平王已死，子胥掘楚平王墓，出其屍，鞭之三百。申包胥遺書責之曰：『子之報讎，其以甚乎！』子胥答曰：『吾日暮途遠，故倒行而逆施之！』", "quote": "吾日暮途遠，故倒行而逆施之。", "desc": "形容行事完全背離常理與正道，倒退逆流而行。", "yin": "dào xíng nì shī"}, {"rank": 360, "idiom": "臨渴掘井", "pinyin": "lín kě jué jǐng", "origin": "《黃帝內經·素問·四氣調神大論》/《晏子春秋》", "story": "夫病已成而後藥之，亂已成而後治之，譬猶渴而穿井，鬬而鑄錐，不亦晚乎！景公好奢，晏子亦諫曰：事至而圖之，猶渴而穿井，何以及民之救哉！", "quote": "夫病已成而後藥之，亂已成而後治之，譬猶渴而穿井，鬬而鑄錐，不亦晚乎！", "desc": "比喻事先毫不防備準備，事到臨頭才慌忙想辦法，悔之已晚。", "yin": "lín kě jué jǐng"}, {"rank": 359, "idiom": "曲突徙薪", "pinyin": "qū tū xǐ xīn", "origin": "《漢書·霍光傳》", "story": "客有見主人灶突直而薪旁積，告主人曰：『更為曲突，遠徙其薪，不然且有火患。』主人不應。俄而家果失火，鄉黨救火得滅。主人殺牛置酒謝鄰裡，焦頭爛額者坐上客，而不延言曲突徙薪者。客謂主人曰：『曲突徙薪無恩澤，焦頭爛額為上客邪？』主人乃悟而迎客。", "quote": "曲突徙薪亡恩澤，焦頭爛額為上客邪？", "desc": "比喻事先採取預防措施以消除隱患，亦指防範於未然者往往反遭冷落。", "yin": "qū tū xǐ xīn"}, {"rank": 358, "idiom": "防微杜漸", "pinyin": "fáng wēi dù jiàn", "origin": "《後漢書·丁鴻傳》", "story": "和帝即位幼弱，竇太后臨朝，兄竇憲專權擅威。大司徒丁鴻因日食上疏，引《易》言履霜堅冰至：『若隱微之際不防，萌芽之變不塞，漸積日久，禍亂不可圖也。夫民之情，日滋月甚，必防於微而杜於漸。』和帝悟，乃收竇憲大將軍印綬。", "quote": "防微杜漸，禁於未然，若隱微之際不防，萌芽之變不塞，禍必至矣。", "desc": "指在事物的萌芽隱微階段就加以遏制防範，防止其滋長蔓延。", "yin": "fáng wēi dù jiàn"}, {"rank": 357, "idiom": "韋編三絕", "pinyin": "wéi biān sān jué", "origin": "《史記·孔子世家》", "story": "孔子晚而喜《易》，序《彖》、《象》、《說卦》、《文言》。讀《易》，韋編三絕。曰：『假我數年，若是，我於《易》則彬彬矣！』古書以竹簡書寫，以熟牛皮條編聯，孔子研讀周易反覆深沉，連皮繩都被磨斷了多次。", "quote": "孔子晚而喜易，序彖、象、說卦、文言。讀易，韋編三絕。", "desc": "比喻求學讀書勤勉刻苦，專注研討不輟。", "yin": "wéi biān sān jué"}, {"rank": 356, "idiom": "汗馬功勞", "pinyin": "hàn mǎ gōng láo", "origin": "《韓非子·五蠹》/《史記·蕭相國世家》", "story": "高祖論功封侯，諸將日夜爭功曰：『臣等身被堅執銳，多者百餘戰，攻城略地，今蕭何未嘗有汗馬之勞，徒持文墨議論，顧反居臣等上，何也？』高祖以獵人與獵狗為喻，謂蕭何為功人，諸將為功狗，力辨戰略與戰術之首輔定位。", "quote": "諸將曰：臣等身被堅執銳，今蕭何未嘗有汗馬之勞，何居臣等上？", "desc": "指在戰爭前線或艱苦事業中立下的卓越卓著功勞。", "yin": "hàn mǎ gōng láo"}, {"rank": 355, "idiom": "鹿死誰手", "pinyin": "lù sǐ shuí shǒu", "origin": "《晉書·石勒載記》", "story": "後趙石勒因大宴，引問徐光曰：『朕方自古何等主也？』光對曰：『陛下神武超過漢高，卓犖勝於魏武。』勒笑曰：『人豈不自知！朕若逢高皇，當北面而事之，與韓彭並騖；若遇光武，當並驅中原，未知鹿死誰手。大丈夫行事光明磊落，豈如曹孟德、司馬仲達孤兒寡婦以取天下哉！』", "quote": "朕若遇光武，當並驅中原，未知鹿死誰手。", "desc": "比喻群雄角逐爭奪政權或勝利，不知最終落入誰人之手。", "yin": "lù sǐ shuí shǒu"}, {"rank": 354, "idiom": "三顧茅廬", "pinyin": "sān gù máo lú", "origin": "蜀漢·諸葛亮《前出師表》/《三國志·蜀書·諸葛亮傳》", "story": "先主屯新野。徐庶薦諸葛孔明曰：『此人可就見，不可屈致也。將軍宜枉駕顧之。』由是先主遂詣亮，凡三往，乃見。因屏人曰：『漢室傾頹，奸臣竊命，主上蒙塵。孤不度德量力，欲信大義於天下，而智術淺短，遂猖蹶至於今日。然志猶未已，君謂計將安出？』亮乃竭心剖陳隆中策。", "quote": "臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯。先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中。", "desc": "比喻統治者或求才者誠懇至極地再三登門敦聘賢能。", "yin": "sān gù máo lú"}, {"rank": 353, "idiom": "鞠躬盡瘁", "pinyin": "jū gōng jǐn cuì", "origin": "蜀漢·諸葛亮《後出師表》", "story": "蜀主建興六年，諸葛亮上《後出師表》，力主北伐中原討賊復漢，深感局勢危急創業艱難，慨然誓言：『臣受命之日，寢不安席，食不甘味。臣鞠躬盡瘁，死而後已；至於成敗利鈍，非臣之明所能逆睹也！』其耿耿忠忱萬世景仰。", "quote": "臣鞠躬盡瘁，死而後已；至於成敗利鈍，非臣之明所能逆睹也。", "desc": "形容恭敬謹慎，竭盡全力為事業或職守奮鬥至生命最後一刻。", "yin": "jū gōng jǐn cuì"}, {"rank": 352, "idiom": "望梅止渴", "pinyin": "wàng méi zhǐ kě", "origin": "南朝宋·劉義慶《世說新語·假譎》", "story": "魏武少時行軍，途逢荒原，絕水，士卒皆渴，疲睏不堪。魏武登高遠望，心生一計，乃按轡指前方山坳謂眾曰：『前有大梅林，饒子，甘酸可以解渴！』士卒聞之，口皆出涎，頓增力量，行疾如飛，終得行至前方水泉處。", "quote": "魏武行役失汲道，軍皆渴，乃令曰：前有大梅林，饒子，甘酸可以解渴。士卒聞之，口皆出涎，乘此得及泉。", "desc": "比喻用空想或虛幻景象來自我安慰、緩解渴望。", "yin": "wàng méi zhǐ kě"}, {"rank": 351, "idiom": "如魚得水", "pinyin": "rú yú dé shuǐ", "origin": "《三國志·蜀書·諸葛亮傳》", "story": "劉備三顧茅廬得諸葛亮，情好日密。關羽、張飛等不悅，備解之曰：『孤之有孔明，猶魚之有水也。願諸君勿復言。』羽、飛乃止。明主與名臣之契合互補，千載傳為美談。", "quote": "先主曰：孤之有孔明，猶魚之有水也。願諸君勿復言。", "desc": "比喻得到與自己志同道合、互相信賴的夥伴或處於極其順遂之環境。", "yin": "rú yú dé shuǐ"}, {"rank": 350, "idiom": "刮目相待", "pinyin": "guā mù xiāng dài", "origin": "《三國志·吳書·呂蒙傳》裴松之注引《江表傳》", "story": "魯肅代周瑜過下陸，過蒙營，蒙為肅籌畫五策。肅拊蒙背曰：『吾謂大弟但有武略耳，至於今者，學識英博，非復吳下阿蒙！』蒙曰：『士別三日，即更刮目相待，大兄何見事之晚乎！』肅遂拜蒙母，結友而別。", "quote": "士別三日，即更刮目相待，大兄何見事之晚乎！", "desc": "指抹亮眼睛重新以全新眼光看待對方進步卓越之成就。", "yin": "guā mù xiāng dài"}, {"rank": 349, "idiom": "煮豆燃萁", "pinyin": "zhǔ dòu rán qí", "origin": "南朝宋·劉義慶《世說新語·文學》", "story": "魏文帝曹丕嘗令東阿王曹植七步中作詩，不成者行大法。植應聲便為詩曰：『煮豆持作羹，漉豉以為汁。萁在釜下燃，豆在釜中泣。本自同根生，相煎何太急！』文帝甚有慚色，乃赦免之。", "quote": "萁在釜下燃，豆在釜中泣。本自同根生，相煎何太急！", "desc": "比喻骨肉兄弟或內部同室操戈、骨肉相殘。", "yin": "zhǔ dòu rán qí"}, {"rank": 348, "idiom": "單刀赴會", "pinyin": "dān dāo fù huì", "origin": "《三國志·吳書·魯肅傳》", "story": "孫權欲索荊州，肅請羽相見，各駐兵馬百步上，但諸將各佩單刀赴會。肅因責羽：『國家區區本以土地借卿家者，卿家無足藉之資，今既得益州，更欲兼併荊州，此非匹夫所忍行，況大人之仁義乎！』羽不能對。", "quote": "肅請羽相見，各駐兵馬百步上，但請將軍單刀赴會。", "desc": "比喻具有膽識謀略者隻身涉險，前往敵方營壘赴約周旋。", "yin": "dān dāo fù huì"}, {"rank": 347, "idiom": "手不釋卷", "pinyin": "shǒu bù shì juǎn", "origin": "《三國志·吳書·呂蒙傳》裴松之注引《江表傳》", "story": "初，孫權謂呂蒙曰：『卿今當塗掌事，不可不學！』蒙辭以軍中多務。權曰：『孤常讀書，自以為大有所益。卿言多務，孰若孤？孤常手不釋卷，涉獵群書。』蒙始就學，篤志不倦，學識邁群，卒成東吳柱石。", "quote": "光武當兵馬之務，手不釋卷；魏武亦謂老而好學。卿何獨不能邪？", "desc": "形容熱愛讀書學習，書卷隨時拿在手中，片刻不捨放下。", "yin": "shǒu bù shì juǎn"}, {"rank": 346, "idiom": "開誠布公", "pinyin": "kāi chéng bù gōng", "origin": "《三國志·蜀書·諸葛亮傳評》", "story": "陳壽評諸葛亮曰：『諸葛亮之為相國也，撫百姓，示儀軌，約官職，從權制，開誠心，布公道；盡忠益時者雖仇必賞，犯法怠慢者雖親必罰。終於邦域之內，鹹畏而愛之。』其治蜀綱紀肅然，大德垂範。", "quote": "諸葛亮之為相國也，開誠心，布公道，盡忠益時者雖仇必賞。", "desc": "指敞開胸襟展現至誠，公正無私地處理一切政務與人際事物。", "yin": "kāi chéng bù gōng"}, {"rank": 345, "idiom": "才高八斗", "pinyin": "cái gāo bā dǒu", "origin": "南朝宋·謝靈運言（唐·李延壽《南史》/宋·李石《續博物志》）", "story": "南朝詩人謝靈運自負才高，嘗言曰：『天下才共一石，曹子建獨得八斗，我得一斗，自古及今凡天下之人共分其餘一斗。』以此盛讚曹植才華超群絕倫，橫絕百代。", "quote": "天下才共一石，曹子建獨得八斗，我得一斗，天下共分一斗。", "desc": "極言文才超群出眾，才學雄厚至極。", "yin": "cái gāo bā dǒu"}, {"rank": 344, "idiom": "一身是膽", "pinyin": "yī shēn shì dǎn", "origin": "《三國志·蜀書·趙雲傳》裴松之注引《雲別傳》", "story": "漢水之戰，曹公大軍掩至。趙雲入曹軍陣突圍，救黃忠，復入營救張著。曹軍追至雲寨，雲大開寨門，偃旗息鼓。曹軍疑有伏兵，引退。雲令軍士擂鼓震天，強弩射曹軍後部。曹軍驚駭自相蹂踐，墮漢水死者甚多。先主明旦自來至雲營，視昨戰處，曰：『子龍一身都是膽也！』", "quote": "先主明旦自來至雲營圍視昨戰處，曰：子龍一身都是膽也！", "desc": "形容人無所畏懼，膽量魄力極其巨大豪邁。", "yin": "yī shēn shì dǎn"}, {"rank": 343, "idiom": "白衣渡江", "pinyin": "bái yī dù jiāng", "origin": "《三國志·吳書·呂蒙傳》", "story": "呂蒙密謀襲荊州，使部卒化裝為商人，著白衣搖櫓，伏精兵於舟中，晝夜兼道溯江而上。關羽江邊烽火臺候望者皆被掩捕捆縛，關羽竟毫無所察。呂蒙兵不血刃徑襲公安、江陵，盡拔南郡諸城。", "quote": "蒙到尋陽，盡伏其精兵艎舡中，使白衣搖櫓，作商賈人服，晝夜兼行。", "desc": "比喻暗中偽裝隱蔽以出其不意襲擊敵方之高妙戰術。", "yin": "bái yī dù jiāng"}, {"rank": 342, "idiom": "顧全大局", "pinyin": "gù quán dà jú", "origin": "《漢書·韋賢傳》引申/清·吳趼人《二十年目睹之怪現狀》", "story": "漢朝重臣商略國是，常以社稷宗廟整體為慮，不計較一時一隅之得失私恩。後世因以顧全大局指從全盤根本利益出發，顧及全局而隱忍個人或局部利益。", "quote": "天下大事，當重其綱目，凡君子立身，必以顧全大局為要。", "desc": "指從全盤全局利益出發，妥善兼顧整體，不因細枝末節而誤大事。", "yin": "gù quán dà jú"}, {"rank": 341, "idiom": "老驥伏櫪", "pinyin": "lǎo jì fú lì", "origin": "魏·曹操《步出夏門行·龜雖壽》", "story": "曹操平定烏桓，統一天下北方，班師回朝，登碣石觀海，撫今追昔，作《龜雖壽》：『神龜雖壽，猶有竟時；螣蛇乘霧，終為土灰。老驥伏櫪，志在千里；烈士暮年，壯心不已！』老馬雖伏於馬槽，馳騁千里之雄心絲毫不減。", "quote": "老驥伏櫪，志在千里；烈士暮年，壯心不已。", "desc": "比喻有志之士雖年紀衰老，仍保持著雄心壯志與奮進精神。", "yin": "lǎo jì fú lì"}, {"rank": 340, "idiom": "堅壁清野", "pinyin": "jiān bì qīng yě", "origin": "《三國志·魏書·荀彧傳》", "story": "曹操徵陶謙，張邈、陳宮迎呂布襲兗州。彧謂操曰：『昔高祖保關中，光武據河內，皆深根固本以制天下。今若分兵東徵，百姓皆堅壁清野以待，將軍何食以養兵？』力勸曹操深根固本，穩住兗州根本。", "quote": "今東方皆以收麥，必堅壁清野以待將軍，將軍攻之不拔，略之無獲。", "desc": "指加固壁壘防守，將田野物資收空移走，使進攻敵軍無處得食之戰術。", "yin": "jiān bì qīng yě"}, {"rank": 339, "idiom": "兵貴神速", "pinyin": "bīng guì shén sù", "origin": "《三國志·魏書·郭嘉傳》", "story": "太祖將徵袁尚及三郡烏丸。郭嘉說太祖曰：『兵貴神速。今千里襲人，輜重多，難以趣利，且彼聞之，必為備。不如留輜重，輕兵兼道以出，掩其不意。』太祖乃密出盧龍寨，直指柳城，一戰斬蹋頓，破平三郡烏丸。", "quote": "嘉言曰：兵貴神速。今千里襲人，不如留輜重，輕兵兼道以出，掩其不備。", "desc": "指用兵作戰最寶貴的是行動迅捷神速，趁敵未備搶佔先機。", "yin": "bīng guì shén sù"}, {"rank": 338, "idiom": "登高自卑", "pinyin": "dēng gāo zì bēi", "origin": "《禮記·中庸》", "story": "君子之道，闢如行遠必自邇，闢如登高必自卑。《中庸》論修養德業，謂如同遠行必須從近處起步，攀登萬仞高峰必須從平地低處立足，腳踏實地，循序漸進方能造極。", "quote": "君子之道，闢如行遠必自邇，闢如登高必自卑。", "desc": "比喻事情要一步一步由淺入深、自低而高地循序漸進。", "yin": "dēng gāo zì bēi"}, {"rank": 337, "idiom": "步步為營", "pinyin": "bù bù wèi yíng", "origin": "明·羅貫中《三國演義》第七十一回", "story": "定軍山之戰，黃忠、法正進兵。法正諫黃忠曰：『今魏兵勢大，不可輕敵，當引兵按圖索路，步步為營，移兵向山而進。』忠從之，每下一寨，深溝高壘，徐徐圖之，終斬夏侯淵，奪取漢中天險。", "quote": "法正曰：不可輕進，當步步為營，誘敵深入。", "desc": "比喻行事謹慎穩健，每向前走一步都防守周密，穩紮穩打。", "yin": "bù bù wèi yíng"}, {"rank": 336, "idiom": "如雷貫耳", "pinyin": "rú léi guàn ěr", "origin": "元·無名氏《凍蘇秦》/明·羅貫中《三國演義》", "story": "兩軍交鋒或英雄相會，常聞『久仰將軍大名，如雷貫耳』之語，極言對方崇高盛名在海內響徹震動，如轟雷震貫雙耳，令人無比欽仰。", "quote": "久仰大名，如雷貫耳，今日得晤，三生有幸。", "desc": "形容人的威名或名聲極其響亮，天下聞名。", "yin": "rú léi guàn ěr"}, {"rank": 335, "idiom": "出其不意", "pinyin": "chū qí bù yì", "origin": "《孫子·計篇》", "story": "孫子曰：『兵者，詭道也。攻其無備，出其不意。此兵家之勝，不可先傳也。』軍事用兵與行事策略的核心，在於在對方毫無戒備防範之時發起行動，出現在其料想不到的時間與地點。", "quote": "攻其無備，出其不意。此兵家之勝，不可先傳也。", "desc": "指在對方意料之外、全無防備之時突然採取行動。", "yin": "chū qí bù yì"}, {"rank": 334, "idiom": "攻其不備", "pinyin": "gōng qí bù bèi", "origin": "《孫子·計篇》", "story": "孫武論用兵克敵制勝之機，強調善戰者必審查敵方虛實弱點，趁其疏懈無備之際以雷霆之勢掩殺，方能以最小代價贏得全勝。", "quote": "兵者詭道也，故能而示之不能，用而示之不用，攻其無備，出其不意。", "desc": "指趁著對方沒有防備或疏忽懈怠之際發動攻擊。", "yin": "gōng qí bù bèi"}, {"rank": 333, "idiom": "養精蓄銳", "pinyin": "yǎng jīng xù ruì", "origin": "明·羅貫中《三國演義》第三十四回", "story": "劉備屯兵新野，劉表疑之。伊籍密謂玄德曰：『今蔡瑁懷不良之心，將軍當養精蓄銳，廣積糧草，以圖大事。』指修養精神氣力，積蓄充足銳氣，以待良機一展雄圖。", "quote": "且休出戰，各守寨柵，養精蓄銳，待敵疲敝而擊之。", "desc": "指保養精神體力，積累戰鬥力量，準備隨時投入任務。", "yin": "yǎng jīng xù ruì"}, {"rank": 332, "idiom": "偃旗息鼓", "pinyin": "yǎn qí xī gǔ", "origin": "《三國志·蜀書·趙雲傳》裴松之注引《雲別傳》", "story": "漢水之戰，曹公軍追至趙雲營壘。雲入營，更大開門，偃旗息鼓。曹軍見雲營寂然無聲，旌旗放倒，鼓聲皆歇，疑有伏兵，慌亂引退。雲乘其驚疑引弩射之，曹軍自相踐踏大潰。", "quote": "雲入營，更大開門，偃旗息鼓。公軍疑有伏兵，引去。", "desc": "原指放倒軍旗、停敲戰鼓以隱蔽軍事行動，後比喻停止爭吵或放棄某種活動。", "yin": "yǎn qí xī gǔ"}, {"rank": 331, "idiom": "吳下阿蒙", "pinyin": "wú xià ā méng", "origin": "《三國志·吳書·呂蒙傳》裴松之注引《江表傳》", "story": "魯肅初以呂蒙為行伍武夫，不屑一顧。及至聽聞呂蒙指畫天下形勢，條分縷析，歎服其才學非昔日吳郡之下粗鄙之阿蒙所能比擬。", "quote": "魯肅拊蒙背曰：吾謂大弟但有武略耳，至於今者，學識英博，非復吳下阿蒙！", "desc": "比喻原先學識淺陋、毫無名氣之人，後經進步判若兩人。", "yin": "wú xià ā méng"}, {"rank": 330, "idiom": "東床快婿", "pinyin": "dōng chuáng kuài xù", "origin": "南朝宋·劉義慶《世說新語·雅量》", "story": "太尉郗鑒使門生求女婿於王丞相，丞相令往東廂看子弟。門生歸白郗公曰：『王家諸郎，亦皆可嘉，聞來覓婿，鹹自矜持；唯有一郎在東床上坦腹臥，如不聞。』郗公曰：『正此好！』訪之，乃逸少（王羲之）也，因以女妻之。", "quote": "郗公曰：正此好！訪之，乃逸少也，因以女妻之。", "desc": "指為人稱心滿意的好女婿。", "yin": "dōng chuáng kuài xù"}, {"rank": 329, "idiom": "管寧割席", "pinyin": "guǎn níng gē xí", "origin": "南朝宋·劉義慶《世說新語·德行》", "story": "管寧、華歆共園中鋤菜，見地有片金，管揮鋤與瓦石不異，華捉而擲去之。又嘗同席讀書，有乘軒冕過門者，寧讀如故，歆廢書出看。寧割席分坐曰：『子非吾友也！』志不同道不合，毅然斷交。", "quote": "寧割席分坐，曰：子非吾友也。", "desc": "比喻朋友之間因志趣理念徹底不同而毅然斷絕交情往來。", "yin": "guǎn níng gē xí"}, {"rank": 328, "idiom": "漸入佳境", "pinyin": "jiàn rù jiā jìng", "origin": "《晉書·顧愷之傳》", "story": "顧愷之每食甘蔗，恆自尾至本。人怪問之，愷之笑答曰：『漸至佳境。』先吃淡薄無味之梢部，越往下嚼越甘甜多汁，比喻情況日益好轉，意趣日趨高妙深醇。", "quote": "顧長康每食甘蔗，恆自尾至本。人怪問之，曰：漸入佳境。", "desc": "比喻事物、狀況或藝術境界逐步進入極佳之境界。", "yin": "jiàn rù jiā jìng"}, {"rank": 327, "idiom": "拾人牙慧", "pinyin": "shí rén yá huì", "origin": "南朝宋·劉義慶《世說新語·文學》", "story": "殷中軍雲：『康伯未得我牙後慧。』韓康伯為殷浩之甥，好清談辯難，每借舅父言論以為己說。牙慧指牙齒咀嚼掉落之殘渣，意指蹈襲他人唾餘，毫無個人獨創見解。", "quote": "殷中軍雲：康伯未得我牙後慧。", "desc": "比喻抄襲剽竊他人的言語文字或觀點，毫無獨創成果。", "yin": "shí rén yá huì"}, {"rank": 326, "idiom": "小時了了", "pinyin": "xiǎo shí liǎo liǎo", "origin": "南朝宋·劉義慶《世說新語·言語》", "story": "孔文舉年十歲，隨父到洛。李元禮有盛名，文舉至門曰：『我是李府君親。』既見，元禮問：『何親？』答曰：『古者孔子與老子同德相師，通家也。』賓客莫不奇之。中大夫陳韙後至，曰：『小時了了，大未必佳。』文舉曰：『想君小時，必當了了。』韙大慚屈。", "quote": "陳韙曰：小時了了，大未必佳。文舉曰：想君小時，必當了了。", "desc": "指幼小時聰慧敏捷，長大後不一定有傑出成就。", "yin": "xiǎo shí liǎo liǎo"}, {"rank": 325, "idiom": "咄咄怪事", "pinyin": "duō duō guài shì", "origin": "南朝宋·劉義慶《世說新語·黜免》", "story": "殷浩自幼有重名，任中軍將軍北伐失利，被桓溫所廢，徙東陽。浩雖被黜廢，終無怨言，神色自若，口不宣是非，唯終日以手在空中畫字，視之，唯作『咄咄怪事』四字而已。", "quote": "殷中軍被廢東陽，終日以手在空中書字，唯作咄咄怪事四字。", "desc": "形容令人極度驚訝、不可思議之怪異事件。", "yin": "duō duō guài shì"}, {"rank": 324, "idiom": "鶴立雞群", "pinyin": "hè lì jī qún", "origin": "南朝宋·劉義慶《世說新語·容止》", "story": "有人語王戎曰：『嵇延祖卓卓如野鶴之在雞群。』嵇紹為嵇康之子，體貌魁梧儀態俊秀，風神蕭灑，立於眾人之中，猶如仙鶴傲立於群雞之間，超凡脫俗，惹人注目。", "quote": "有人語王戎曰：嵇延祖卓卓如野鶴之在雞群。", "desc": "比喻一個人的才能儀態在一群普通人中極其出眾突出。", "yin": "hè lì jī qún"}, {"rank": 323, "idiom": "絕妙好辭", "pinyin": "jué miào hǎo cí", "origin": "南朝宋·劉義慶《世說新語·捷悟》", "story": "魏武嘗過曹娥碑下，楊修從。碑背有八字題：『黃絹幼婦，外孫齏臼。』魏武謂修曰：『卿解不？』答曰：『解。』魏武曰：『卿未可言，待我思之。』行三十里，魏武乃曰：『吾已得。』令修各記之。修曰：『黃絹色絲，絕字也；幼婦少女，妙字也；外孫女子，好字也；齏臼受辛，辭字也。所謂絕妙好辭也。』魏武歎曰：『我才不及卿，乃覺三十里！』", "quote": "修曰：黃絹色絲，幼婦少女，外孫女子，齏臼受辛，所謂絕妙好辭也。", "desc": "極言詩詞文章辭採華美，造詣精妙到了極致。", "yin": "jué miào hǎo cí"}, {"rank": 322, "idiom": "難兄難弟", "pinyin": "nán xiōng nán dì", "origin": "南朝宋·劉義慶《世說新語·德行》", "story": "陳元方子長文有英才，與季方子孝先各論其父功德，爭之不能決，諮於太丘。太丘曰：『元方難為兄，季方難為弟！』意謂二子皆品德學問卓絕，實難以分出誰高誰低。", "quote": "陳太丘曰：元方難為兄，季方難為弟。", "desc": "原指兄弟二人德才俱佳難分伯仲，現亦多戲指彼此處境同樣困難之人。", "yin": "nán xiōng nán dì"}, {"rank": 321, "idiom": "別出心裁", "pinyin": "bié chū xīn cái", "origin": "明·李漁《閒情偶寄》/明·張岱《陶庵夢憶》", "story": "李漁論文章演劇之造化，指出大家匠手立意行文，必當別具性靈，從心坎靈犀處另出巧思，獨闢畦徑，切不可陳陳相因拾人唾餘。", "quote": "獨創一格，別出心裁，令人目爽神怡。", "desc": "指獨創一格，想出與眾不同的精妙新主意或新辦法。", "yin": "bié chū xīn cái"}, {"rank": 320, "idiom": "標新立異", "pinyin": "biāo xīn lì yì", "origin": "南朝宋·劉義慶《世說新語·文學》", "story": "支道林造《即色論》，至洛陽見謝安。安讀之歎曰：『支理標新立異，名理冠世，人不能折！』支遁大師闡發佛家般若性空義理，獨樹新幟，立論新穎宏深，名動天下。", "quote": "支公作即色論，謝太傅稱之曰：標新立異，名理實冠當世。", "desc": "指提出新穎獨創的主張或見解，立意不同凡響。", "yin": "biāo xīn lì yì"}, {"rank": 319, "idiom": "入木三分", "pinyin": "rù mù sān fēn", "origin": "唐·張懷瓘《書斷·王羲之》", "story": "晉帝祭北郊，更祝版，工人削之，筆入木三分。王羲之運筆氣力雄健無匹，墨汁筆鋒入木板竟深達三分之厚，足見其書法沉著痛快、神功造化。", "quote": "王羲之書祝版，工人削之，筆入木三分。", "desc": "形容書法用筆遒勁有力，亦比喻議論剖析事物極深刻透徹。", "yin": "rù mù sān fēn"}, {"rank": 318, "idiom": "倚馬可待", "pinyin": "yǐ mǎ kě dài", "origin": "南朝宋·劉義慶《世說新語·文學》", "story": "桓宣武北伐，使袁虎倚馬前作檄文，手不輟筆，俄得七紙，殊可觀。袁宏才思敏捷若江河奔湧，在軍前靠著戰馬站立片刻即寫就數千言浩瀚討逆檄文，文采斐然。", "quote": "桓宣武北伐，使袁虎倚馬前作檄文，手不輟筆，俄成七紙。", "desc": "形容才思極其敏捷，寫作文章一氣呵成，立即可成。", "yin": "yǐ mǎ kě dài"}, {"rank": 317, "idiom": "見獵心喜", "pinyin": "jiàn liè xīn xǐ", "origin": "宋·晁補之《雞肋集》/《二程全書》", "story": "程顥年少時好畋獵。後歸道學，自謂已絕此好。周敦頤曰：『何言之易！獺嗜魚，狼嗜肉，本性難移。子異日見獵，當復心喜。』後數年，程顥行野外果見獵者，果然心動欣躍，始悟習氣消除之難。", "quote": "明道先生少時好獵，後見獵者，不覺有喜色，始知舊習未盡除去。", "desc": "比喻重見自己喜愛擅長的舊事物，情不自禁感到欣喜躍躍欲試。", "yin": "jiàn liè xīn xǐ"}, {"rank": 316, "idiom": "楚囚相對", "pinyin": "chǔ qiú xiāng duì", "origin": "南朝宋·劉義慶《世說新語·言語》", "story": "過江諸人，每至美日，輒相攜新亭，藉卉飲宴。周顗中坐而歎曰：『風景不殊，正自有山河之異！』皆相視流淚。唯丞相王導愀然變色曰：『當共戮力王室，克復神州，何至作楚囚相對！』眾人皆竦敬愧服。", "quote": "王導愀然變色曰：當共戮力王室，克復神州，何至作楚囚相對！", "desc": "形容身處危難困厄之境，毫無作為，只管相對痛哭哀歎。", "yin": "chǔ qiú xiāng duì"}, {"rank": 315, "idiom": "捉刀代筆", "pinyin": "zhuō dāo dài bǐ", "origin": "南朝宋·劉義慶《世說新語·容止》", "story": "魏武將見匈奴使，自以形陋，不足雄遠國，使崔季珪代，帝自捉刀立床頭。既畢，令間諜問使曰：『魏王何如？』使曰：『魏王雅望非常，然床頭捉刀人，此乃真英雄也！』魏武聞之，乃追殺此使。", "quote": "魏武將見匈奴使，使崔琰代，帝自捉刀立床頭。匈奴使曰：床頭捉刀人，乃真英雄也。", "desc": "指代他人撰寫文字或替代他人承擔事務。", "yin": "zhuō dāo dài bǐ"}, {"rank": 314, "idiom": "詠絮之才", "pinyin": "yǒng xù zhī cái", "origin": "南朝宋·劉義慶《世說新語·言語》", "story": "謝安寒雪日內集，與兒女講論文義。俄而雪驟，公欣然曰：『白雪紛紛何所似？』兄子胡兒曰：『撒鹽空中差可擬。』兄女謝道韞曰：『未若柳絮因風起。』公大笑樂。道韞才思飄逸敏妙，千古傳為佳話。", "quote": "公欣然曰：白雪紛紛何所似？兄女道韞曰：未若柳絮因風起。", "desc": "用以讚揚女子具有超凡脫俗之卓越詩才與文學天賦。", "yin": "yǒng xù zhī cái"}, {"rank": 313, "idiom": "坦腹東床", "pinyin": "tǎn fù dōng chuáng", "origin": "南朝宋·劉義慶《世說新語·雅量》", "story": "郗太尉在京口，遣門生與王丞相書，求女婿。丞相語客曰：『君往東廂，任意選之。』門生歸白郗公：『王家諸郎，各個矜持端坐，獨有一郎坦腹臥東床，若無其事。』此人即王羲之，郗公大喜，遂以女妻之。", "quote": "郗公求婿，門生曰：唯有一郎坦腹臥東床。郗公曰：正此佳婿。", "desc": "指瀟灑不群、自得風度之好女婿。", "yin": "tǎn fù dōng chuáng"}, {"rank": 312, "idiom": "乘興而來", "pinyin": "chéng xìng ér lái", "origin": "南朝宋·劉義慶《世說新語·任誕》", "story": "王子猷居山陰，夜大雪，眠覺，開室，命酌酒，四望皎然。因起仿徨，詠左思《招隱詩》。忽憶戴安道，時戴在剡，即便夜乘小船就之。經宿方至，造門不前而返。人問其故，王曰：『吾本乘興而行，興盡而返，何必見戴！』", "quote": "王子猷曰：吾本乘興而行，興盡而返，何必見戴！", "desc": "指趁著一時興致乘興前往，不計較結果或功利收穫。", "yin": "chéng xìng ér lái"}, {"rank": 311, "idiom": "剪燭西窗", "pinyin": "jiǎn zhú xī chuāng", "origin": "唐·李商隱《夜雨寄北》", "story": "君問歸期未有期，巴山夜雨漲秋池。何當共剪西窗燭，卻話巴山夜雨時！詩人身處巴蜀夜雨之深秋，懸想歸家之後與知己在西窗下共剪燭花夜話，傾訴相思之苦。", "quote": "何當共剪西窗燭，卻話巴山夜雨時。", "desc": "指親朋好友劫後重逢或久別相聚，促膝深談舊情往事。", "yin": "jiǎn zhú xī chuāng"}, {"rank": 310, "idiom": "蓴鱸之思", "pinyin": "chún lú zhī sī", "origin": "《晉書·張翰傳》", "story": "張翰字季鷹，吳郡人。有清才，仕齊王冏。在洛見秋風起，因思吳中菰菜、蓴羹、鱸魚膾，曰：『人生貴得適志，何能羈宦數千里以要名爵乎！』遂命駕而歸。俄而齊王冏敗，人皆重其先見之明。", "quote": "張翰見秋風起，因思吳中菰菜、蓴羹、鱸魚膾，命駕便歸。", "desc": "比喻對故鄉美食風物的深刻思念，亦指歸隱田園之志。", "yin": "chún lú zhī sī"}, {"rank": 309, "idiom": "陸海潘江", "pinyin": "lù hǎi pān jiāng", "origin": "南朝梁·鍾嶸《詩品·捲上》", "story": "鍾嶸品評西晉文壇兩大家陸機與潘岳曰：『陸才如海，潘才如江。』陸機著述汪洋恣肆深不可測如大海，潘岳詞藻明麗奔湧不息若巨江，後世合稱陸海潘江，推為詞林宗匠。", "quote": "陸才如海，潘才如江，各擅其勝。", "desc": "極言文學才華浩瀚澎湃，辭藻豐贍絕倫。", "yin": "lù hǎi pān jiāng"}, {"rank": 308, "idiom": "醉翁之意", "pinyin": "zuì wēng zhī yì", "origin": "宋·歐陽修《醉翁亭記》", "story": "環滁皆山也。望之蔚然而深秀者，瑯琊也。醉翁之意不在酒，在乎山水之間也。山水之樂，得之心而寓之酒也。歐陽修貶滁州，自號醉翁，藉飲酒賞玩山水舒展懷抱，與民同樂。", "quote": "醉翁之意不在酒，在乎山水之間也。山水之樂，得之心而寓之酒也。", "desc": "本謂寄情山水自然，現多比喻言行表面一套，心裡另有深意目的所在。", "yin": "zuì wēng zhī yì"}, {"rank": 307, "idiom": "峰迴路轉", "pinyin": "fēng huí lù zhuǎn", "origin": "宋·歐陽修《醉翁亭記》", "story": "山行六七里，漸聞水聲潺潺，而瀉出於兩峰之間者，釀泉也。峰迴路轉，有亭翼然臨於泉上者，醉翁亭也。群山環抱曲折迴旋，道路隨山勢轉折，眼前忽豁然顯現別致名亭。", "quote": "峰迴路轉，有亭翼然臨於泉上者，醉翁亭也。", "desc": "形容山路曲折盤桓，亦比喻事情處於困境之時突然出現全新轉機。", "yin": "fēng huí lù zhuǎn"}, {"rank": 306, "idiom": "豁然開朗", "pinyin": "huò rán kāi lǎng", "origin": "晉·陶淵明《桃花源記》", "story": "晉太元中，武陵人捕魚為業。初極狹，才通人。復行數十步，豁然開朗。土地平曠，屋舍儼然，有良田美池桑竹之屬。阡陌交通，雞犬相聞。漁人穿過幽暗狹隘石洞，眼前驟然展現出一片光明燦爛樂土。", "quote": "初極狹，才通人。復行數十步，豁然開朗。", "desc": "形容由狹隘幽暗驟然變為開闊明朗，亦指對深奧道理突然領悟通曉。", "yin": "huò rán kāi lǎng"}, {"rank": 305, "idiom": "世外桃源", "pinyin": "shì wài táo yuán", "origin": "晉·陶淵明《桃花源記》", "story": "武陵漁人偶入桃源，見先世避秦苛法之男女老幼生活其間，怡然自得，無徭役戰亂之擾。問今是何世，乃不知有漢，無論魏晉。陶潛藉此構建了千古文人心靈神往之理想安寧社會。", "quote": "自雲先世避秦時亂，率妻子邑人來此絕境，不復出焉，遂與外人間隔。", "desc": "指遠離世俗喧囂、寧靜祥和的理想安逸樂土。", "yin": "shì wài táo yuán"}, {"rank": 304, "idiom": "怡然自樂", "pinyin": "yí rán zì lè", "origin": "晉·陶淵明《桃花源記》", "story": "桃花源中男女衣著，悉如外人。黃髮垂髫，並怡然自樂。老人童稚皆心態安閒純真，無憂無慮，享受生命恬淡自在之至樂。", "quote": "黃髮垂髫，並怡然自樂。", "desc": "形容高興愉悅、心滿意足之自得神態。", "yin": "yí rán zì lè"}, {"rank": 303, "idiom": "萍水相逢", "pinyin": "píng shuǐ xiāng féng", "origin": "唐·王勃《滕王閣序》", "story": "王勃路過洪州，適逢閻公滕王閣大宴，慨然賦序：『關山難越，誰悲失路之人？萍水相逢，盡是他鄉之客！』如水上浮萍偶聚於江流，道盡四海羈客偶聚共聚之深沉共鳴。", "quote": "關山難越，誰悲失路之人？萍水相逢，盡是他鄉之客！", "desc": "比喻素不相識的人在旅途中偶然相遇。", "yin": "píng shuǐ xiāng féng"}, {"rank": 302, "idiom": "馮唐易老", "pinyin": "féng táng yì lǎo", "origin": "唐·王勃《滕王閣序》", "story": "漢文帝時馮唐為郎署長，垂暮之年始得面見文帝，論廉頗、李牧用兵之法，文帝拜為車騎都尉，武帝即位求賢，唐年已九十餘不能復任。王勃以此慨歎命運乖舛、歲月蹉跎才智未伸。", "quote": "馮唐易老，李廣難封。屈賈誼於長沙，非無聖主；竄梁鴻於海曲，豈乏明時！", "desc": "慨嘆賢能之士蹉跎歲月，直到衰老方逢際遇或終身難獲重用。", "yin": "féng táng yì lǎo"}, {"rank": 301, "idiom": "李廣難封", "pinyin": "lǐ guǎng nán fēng", "origin": "唐·王勃《滕王閣序》", "story": "漢名將李廣善射，身經大小七十餘戰，匈奴畏服稱為飛將軍。麾下部將往往因功封侯，廣戰功卓著卻命數多奇，終身不得封侯爵，後世引為命途多舛英雄失意之千古代表。", "quote": "嗟乎！時運不齊，命途多舛。馮唐易老，李廣難封。", "desc": "慨歎英雄戰功卓著才華超群，卻命運坎坷無從獲得應有封賞與地位。", "yin": "lǐ guǎng nán fēng"}, {"rank": 300, "idiom": "業精於勤", "pinyin": "yè jīng yú qín", "origin": "唐·韓愈《進學解》", "story": "國子先生晨入太學，召諸生立館下，誨之曰：『業精於勤，荒於嬉；行成於思，毀於隨。方今聖賢相逢，治具畢張。拔擢通敏之德，蓄極道義之光。諸生業患不能精，無患有司之不明；行患不能成，無患有司之不公。』勉勵生徒刻苦研鑽勤勉不怠。", "quote": "業精於勤，荒於嬉；行成於思，毀於隨。", "desc": "學業與事業的精深在於勤勉奮發，因嬉戲怠惰而荒廢廢棄。", "yin": "yè jīng yú qín"}, {"rank": 299, "idiom": "行成於思", "pinyin": "xíng chéng yú sī", "origin": "唐·韓愈《進學解》", "story": "韓愈告誡太學生徒，品德修為與事業功績的確立，在於獨立深沉的獨立思考與嚴格自律，若隨波逐流盲從世俗，終將導致德業之毀滅敗壞。", "quote": "行成於思，毀於隨。", "desc": "指成功與德行建基於審慎獨立的深思，隨波逐流則招致敗亡。", "yin": "xíng chéng yú sī"}, {"rank": 298, "idiom": "雜亂無章", "pinyin": "zá luàn wú zhāng", "origin": "唐·韓愈《送孟東野序》", "story": "韓愈論文章之聲律與結構曰：『大凡物不得其平則鳴。草木之無聲，風撓之鳴。金石之無聲，一扣而鳴。其聲之高下，必有條理，切不可雜亂無章也。』要求為文如樂章之起伏，秩序井然。", "quote": "天地自然之聲，莫不各有其條理，無有雜亂無章者也。", "desc": "形容混亂繁雜，毫無條理章法可言。", "yin": "zá luàn wú zhāng"}, {"rank": 297, "idiom": "垂涎三尺", "pinyin": "chuí xián sān chǐ", "origin": "唐·柳宗元《三戒·臨江之麋》", "story": "臨江之人得麋麑，蓄之。群犬垂涎，搖尾皆來。麋麑稍長，以為犬良友，與之臥起。後出門，見外犬，群犬見而垂涎喜躍，共殺而食之。麋至死不悟。", "quote": "臨江之人畋得麋麑，蓄之。入門，群犬垂涎，揚尾皆來。", "desc": "形容饞嘴到了極點口水流淌三尺長，亦比喻對某利益極度貪婪渴望。", "yin": "chuí xián sān chǐ"}, {"rank": 296, "idiom": "膾炙人口", "pinyin": "kuài zhì rén kǒu", "origin": "五代·王定保《唐摭言·海敘不公》/《孟子·盡心下》", "story": "孟子曰：『膾炙，與羊棗孰美？』公孫醜曰：『膾炙哉！』細切肉為膾，烤肉為炙，乃人人皆喜愛之至味佳餚。五代時因稱李白、杜甫妙句名篇流傳海內如膾炙入口，人人喜聞樂道。", "quote": "孟子曰：膾炙與羊棗孰美？公孫醜曰：膾炙哉！", "desc": "比喻優秀美妙的文藝作品或人物事蹟廣為人知、備受歡迎傳頌。", "yin": "kuài zhì rén kǒu"}, {"rank": 295, "idiom": "洛陽紙貴", "pinyin": "luò yáng zhǐ guì", "origin": "《晉書·文苑·左思傳》", "story": "左思妹惠為貴嬪，思構思十年作《三都賦》，家置紙筆，門庭藩溷皆有所著。賦成，名士皇甫謐、張華、張載極口稱揚。於是豪貴之家競相傳寫，洛陽紙價為之大漲騰貴，時稱『洛陽紙貴』。", "quote": "於是豪貴之家競相傳寫，洛陽為之紙貴。", "desc": "極言著作極為風行受人爭購，價值影響風靡一時。", "yin": "luò yáng zhǐ guì"}, {"rank": 294, "idiom": "走馬看花", "pinyin": "zǒu mǎ kàn huā", "origin": "唐·孟郊《登科後》", "story": "孟郊早年貧困潦倒，歷經多次科場失意，至四十六歲終登進士第。狂喜之際策馬遊長安，寫下千古絕唱：『昔日齷齪不足誇，今朝放蕩思無涯。春風得意馬蹄疾，一日看盡長安花！』春風暢快，走馬觀花神采飛揚。", "quote": "春風得意馬蹄疾，一日看盡長安花。", "desc": "原形容策馬春風之得意歡暢，後多比喻匆忙粗略地瀏覽觀察事物。", "yin": "zǒu mǎ kàn huā"}, {"rank": 293, "idiom": "胸有成竹", "pinyin": "xiōng yǒu chéng zhú", "origin": "宋·蘇軾《文與可畫簹簹谷偃竹記》", "story": "蘇軾評文同（與可）畫竹曰：『竹之始生，一寸之萌耳，而節葉具焉。故畫竹必先得成竹於胸中，執筆熟視，乃見其所欲畫者，急起從之，振筆直遂，以追其所見，如兔起鶻落，少縱則逝矣！』", "quote": "故畫竹必先得成竹於胸中，執筆熟視，乃見其所欲畫者。", "desc": "比喻在做事動筆之前，心中已經有了完整成熟的全盤考量策劃。", "yin": "xiōng yǒu chéng zhú"}, {"rank": 292, "idiom": "出水芙蓉", "pinyin": "chū shuǐ fú róng", "origin": "南朝梁·鍾嶸《詩品·卷中》", "story": "鍾嶸品評鮑照與謝朓詩，引謝朓評顏延之與謝靈運語：『謝詩如初發芙蓉，自然可愛；顏詩如鋪錦列繡，亦雕繢滿眼。』以荷花初綻水面之自然清麗，推崇不施粉黛、天然雕飾之至高審美。", "quote": "謝詩如初發芙蓉，自然可愛。", "desc": "形容天然清新美麗，毫不做作，亦形容書法文章清新高遠。", "yin": "chū shuǐ fú róng"}, {"rank": 291, "idiom": "青梅竹馬", "pinyin": "qīng méi zhú mǎ", "origin": "唐·李白《長幹行》", "story": "妾髮初覆額，折花門前劇。郎騎竹馬來，遶床弄青梅。同居長幹裡，兩小無嫌猜。李白以生動洗鍊筆墨，勾勒出一對幼年孩童嬉戲玩耍、純真無邪之美好童年時光。", "quote": "郎騎竹馬來，遶床弄青梅。同居長幹裡，兩小無嫌猜。", "desc": "形容男女幼童天真純潔、一同玩耍成長之童年親密關係。", "yin": "qīng méi zhú mǎ"}, {"rank": 290, "idiom": "兩小無猜", "pinyin": "liǎng xiǎo wú cāi", "origin": "唐·李白《長幹行》", "story": "長幹裡少男少女自幼相伴，男孩折竹當馬飛馳而來，女孩採折青梅相擲嬉鬧，彼此間純潔無瑕，全無絲毫嫌隙、猜疑與防範。", "quote": "郎騎竹馬來，遶床弄青梅。同居長幹裡，兩小無嫌猜。", "desc": "形容小男孩和小女孩天真單純，一起相處沒有任何猜疑顧忌。", "yin": "liǎng xiǎo wú cāi"}, {"rank": 289, "idiom": "近水樓臺", "pinyin": "jìn shuǐ lóu tái", "origin": "宋·俞文豹《清夜錄》/宋·蘇麟", "story": "范仲淹知杭州，城中官員皆得推薦提拔，唯通判蘇麟因公出在外未得顧及。蘇麟因獻詩二句於范仲淹曰：『近水樓臺先得月，向陽花木易為春。』仲淹見之大笑，當即親為薦拔。", "quote": "近水樓臺先得月，向陽花木易為春。", "desc": "比喻由於地理環境便利或關係親近而最先獲得優先便利的機會待遇。", "yin": "jìn shuǐ lóu tái"}, {"rank": 288, "idiom": "沉舟側畔", "pinyin": "chén zhōu cè pàn", "origin": "唐·劉禹錫《酬樂天揚州初逢席上見贈》", "story": "劉禹錫罷和州刺史，罷歸途經揚州，與白居易相逢。白居易席上贈詩悲憫其二十三年貶謫生涯。劉禹錫答曰：『巴山楚水淒涼地，二十三年棄置身。懷舊空吟聞笛賦，到鄉翻似爛柯人。沉舟側畔千帆過，病樹前頭萬木春！』以新陳代謝之大觀盡顯曠達豪氣。", "quote": "沉舟側畔千帆過，病樹前頭萬木春。", "desc": "比喻新事物必然代替舊事物，社會大潮奔騰向前不可阻擋。", "yin": "chén zhōu cè pàn"}, {"rank": 287, "idiom": "千呼萬喚", "pinyin": "qiān hū wàn huàn", "origin": "唐·白居易《琵琶行》", "story": "潯陽江頭夜送客，忽聞水上琵琶聲。尋聲暗問彈者誰，琵琶聲停欲語遲。移船相近邀相見，添酒回燈重開宴。千呼萬喚始出來，猶抱琵琶半遮面。轉軸撥弦三兩聲，未成曲調先有情。", "quote": "千呼萬喚始出來，猶抱琵琶半遮面。", "desc": "形容再三呼喚邀請方才遲遲露面，亦指極度矜持或再三敦促催促。", "yin": "qiān hū wàn huàn"}, {"rank": 286, "idiom": "司空見慣", "pinyin": "sī kōng jiàn guàn", "origin": "唐·劉禹錫《贈李司空妓》", "story": "劉禹錫任蘇州刺史，司空李紳邀其赴宴，命歌妓勸酒。歌妓容顏絕美歌聲妙絕。劉禹錫即席賦詩曰：『高髻雲鬟宮樣妝，春風一曲杜韋娘。司空見慣渾閒事，斷盡江南刺史腸！』", "quote": "司空見慣渾閒事，斷盡江南刺史腸。", "desc": "指某種事情見得多了，習以為常，不再感到新奇詫異。", "yin": "sī kōng jiàn guàn"}, {"rank": 285, "idiom": "鐵杵磨針", "pinyin": "tiě chǔ mó zhēn", "origin": "宋·祝穆《方輿勝覽·眉州》", "story": "李白少讀書未成，棄去。過象耳山下小溪，逢一老媼磨鐵杵。白怪而問其故，媼曰：『欲作針。』白笑曰：『鐵杵何能磨成針？』媼曰：『只要功夫深，鐵杵磨成針！』白感其言，遂還讀書，終成大器。", "quote": "媼曰：只要功夫深，鐵杵磨成針。太白感悟，遂還卒業。", "desc": "比喻只要意志堅定、持之以恆，再艱難的工程也能剋期完成。", "yin": "tiě chǔ mó zhēn"}, {"rank": 284, "idiom": "妙筆生花", "pinyin": "miào bǐ shēng huā", "origin": "五代·王仁裕《開元天寶遺事·夢筆頭生花》", "story": "李太白少時，夢所用之筆頭上生花。後天才贍逸，名聞天下。玄宗召入翰林，草詔如流，天子以七寶床賜食，御手調羹。妙筆生花乃天賦異稟與極致文采之絕頂象徵。", "quote": "李白少時，夢所用之筆頭上生花。後天才贍逸，名聞天下。", "desc": "比喻才思橫溢，文筆卓越生動，寫出的文章詩篇精妙絕倫。", "yin": "miào bǐ shēng huā"}, {"rank": 283, "idiom": "兢兢業業", "pinyin": "jīng jīng yè yè", "origin": "《尚書·皋陶謨》", "story": "皋陶矢厥謨，禹拜曰：『都，帝德廣運，乃聖乃神，乃武乃文。皇天眷命，奄有四海，為天下君。』皋陶曰：『兢兢業業，一日二日萬幾！無曠庶官，天工人其代之。』告誡君臣治理政事須時刻戒懼謹慎，如履薄冰。", "quote": "兢兢業業，一日二日萬幾。無曠庶官，天工人其代之。", "desc": "形容做事嚴肅謹慎，一絲不苟，認真負責勤懇工作。", "yin": "jīng jīng yè yè"}, {"rank": 282, "idiom": "如履薄冰", "pinyin": "rú lǚ bó bīng", "origin": "《詩經·小雅·小旻》", "story": "戰戰兢兢，如臨深淵，如履薄冰。《詩經》以此比喻賢者修己防過，每臨大事臨深淵恐其墜落，走薄冰恐其陷裂，時刻保持內心敬畏警覺，免蹈傾覆之禍。", "quote": "戰戰兢兢，如臨深淵，如履薄冰。", "desc": "形容處境危險或行事心存戒懼，極其小心謹慎。", "yin": "rú lǚ bó bīng"}, {"rank": 281, "idiom": "小心翼翼", "pinyin": "xiǎo xīn yì yì", "origin": "《詩經·大雅·大明》", "story": "維此文王，小心翼翼。昭事上帝，聿懷多福。周文王躬行仁義道德，虔誠恭敬奉事上天，一舉一動嚴守禮義法度，戒慎恐懼毫不放縱，終集天下萬民之景從與多福。", "quote": "維此文王，小心翼翼，昭事上帝，聿懷多福。", "desc": "形容舉止言語十分謹慎，不敢有絲毫疏忽大意。", "yin": "xiǎo xīn yì yì"}, {"rank": 280, "idiom": "桃李不言", "pinyin": "táo lǐ bù yán", "origin": "《史記·李將軍列傳》", "story": "太史公曰：『傳曰：其身正，不令而行；其身不正，雖令不從。其李將軍之謂也！餘睹李將軍，悛悛如鄙人，口不能出各。及死之日，天下知與不知，皆為盡哀。彼其忠實心誠信於士大夫也。諺曰：桃李不言，下自成蹊。此言雖小，可以諭大也。』", "quote": "諺曰：桃李不言，下自成蹊。此言雖小，可以諭大也。", "desc": "比喻為人品格高尚真誠，不用自我張揚，自能感動他人前來仰慕。", "yin": "táo lǐ bù yán"}, {"rank": 279, "idiom": "下自成蹊", "pinyin": "xià zì chéng qī", "origin": "《史記·李將軍列傳》", "story": "桃花李樹雖不會開口說話自我誇飾，因其花朵嬌艷芬芳、果實甜美可口，人們爭相前來採摘觀賞，樹下自然踩踏踩出一條條行人小徑。", "quote": "桃李不言，下自成蹊。", "desc": "比喻德行卓越高尚者自然贏得海內萬民之誠摯愛戴與歸向。", "yin": "xià zì chéng qī"}, {"rank": 278, "idiom": "甘拜下風", "pinyin": "gān bài xià fēng", "origin": "《左傳·僖公十五年》", "story": "韓之戰，晉侯獲秦伯。秦大夫皆被甲佩劍以從。晉侯使韓簡勞之，晉大夫請退。秦伯歎曰：『天誘其衷，寡人敢不拜下風！』古人以在上風為尊，處在下風表示敬讓尊崇，甘心認輸。", "quote": "秦伯曰：皇天不憖，曾是在位，寡人敢不拜下風！", "desc": "表示真心佩服他人，自認不如對方而甘願認輸屈尊。", "yin": "gān bài xià fēng"}, {"rank": 277, "idiom": "無懈可擊", "pinyin": "wú xiè kě jī", "origin": "《孫子·計篇》/《左傳》", "story": "古者兵家謀略，全在致人而不致於人。陣形周密如常山之蛇，擊其首則尾至，擊其尾則首至，擊其中則首尾俱至。防守嚴整縝密，毫無絲毫瑕疵破綻可資敵方利用攻擊。", "quote": "深溝高壘，守禦周密，無懈可擊。", "desc": "形容防守嚴密或議論周到無瑕，找不出絲毫破綻與漏洞。", "yin": "wú xiè kě jī"}, {"rank": 276, "idiom": "當仁不讓", "pinyin": "dāng rén bù ràng", "origin": "《論語·衛靈公》", "story": "子曰：『當仁，不讓於師。』孔子教誨門生，平時事奉師長長輩固當謙遜退讓守禮；但若是面臨實踐仁德大義之關頭，必須勇往直前勇於承擔，即使面對師長亦不可謙退推諉。", "quote": "子曰：當仁，不讓於師。", "desc": "指遇到應該做的好事或大義公理，應當積極主動勇挑重擔，絕不退讓。", "yin": "dāng rén bù ràng"}, {"rank": 275, "idiom": "循序漸進", "pinyin": "xún xù jiàn jìn", "origin": "《論語·憲問》朱熹集註/《四書章句集註》", "story": "孔子教人由博返約，下學而上達。朱熹注曰：『君子之學，循序而漸進，由淺入深，由近及遠，不可躐等而求速效也。』學習修持必當按照先後次序步步夯實。", "quote": "君子之學，循序漸進，由粗及精，必有其程。", "desc": "指按一定的順序、步驟與法則逐漸深入提高。", "yin": "xún xù jiàn jìn"}, {"rank": 274, "idiom": "捫心自問", "pinyin": "mén xīn zì wèn", "origin": "宋·葉適《祭葉主簿文》", "story": "宋葉適文論士人出處立身，謂臨事當撫捫胸膛自我反省拷問：吾此心果無愧於天地君親邪？果無負於本來天良邪？捫心審視，心懷坦蕩則鬼神亦欽服。", "quote": "自古君子立身，捫心自問，不欺幽室而已矣。", "desc": "指摸著胸口反躬自問，反覆檢查自己的良心與行為有無過錯。", "yin": "mén xīn zì wèn"}, {"rank": 273, "idiom": "正心誠意", "pinyin": "zhèng xīn chéng yì", "origin": "《禮記·大學》", "story": "欲修其身者，先正其心；欲正其心者，先誠其意；欲誠其意者，先致其知，致知在格物。物格而後知至，知至而後意誠，意誠而後心正，心正而後身修，身修而後家齊，家齊而後國治，國治而後天下平。", "quote": "意誠而後心正，心正而後身修，身修而後家齊，家齊而後國治，國治而後天下平。", "desc": "儒家修身核心綱領，指端正內心思緒，使心志忠誠無妄。", "yin": "zhèng xīn chéng yì"}, {"rank": 272, "idiom": "禮賢下士", "pinyin": "lǐ xián xià shì", "origin": "《新唐書·李勉傳》/《三國志·魏書·文帝紀》", "story": "李勉為李唐宗室賢相，天性夷粹質直。為長官時，知人善任，雖卑官賤士，有一善一才，必待以殊禮，提攜引進，推誠相待，天下歸心。古稱明君宰輔必放下尊崇身段禮遇天下賢良。", "quote": "李勉開誠待物，禮賢下士，自得海內賢士之奉。", "desc": "指身處高位之人能放下架子，尊敬並謙恭結交各方有德有才之士。", "yin": "lǐ xián xià shì"}, {"rank": 271, "idiom": "德高望重", "pinyin": "dé gāo wàng zhòng", "origin": "《晉書·簡文三子傳》", "story": "晉簡文帝第三子司馬道子少有令問。太元中，朝臣皆言尚書僕射謝安、太常陸納等『德高望重，社稷之元老，天下所瞻仰也』。極言其道德情操高尚，海內聲望威隆深重。", "quote": "朝野名士，莫不以此翁德高望重，推為宗仰。", "desc": "形容道德品格崇高，海內聲望威望極其深厚廣大。", "yin": "dé gāo wàng zhòng"}, {"rank": 270, "idiom": "高山仰止", "pinyin": "gāo shān yǎng zhǐ", "origin": "《詩經·小雅·車舝》/《史記·孔子世家》", "story": "高山仰止，景行行止。四牡騑騑，六轡如琴。司馬遷作《孔子世家贊》引此歎曰：『餘讀孔氏書，想見其為人。適魯，觀仲尼廟堂車服禮器，諸生以時習禮其家，餘祗迴留之不能去雲。高山仰止，景行行止。雖不能至，然心鄉往之！』", "quote": "高山仰止，景行行止。雖不能至，然心鄉往之。", "desc": "比喻對高尚品格與偉大聖賢的無限仰慕敬仰與追隨嚮往。", "yin": "gāo shān yǎng zhǐ"}, {"rank": 269, "idiom": "景行行止", "pinyin": "jǐng xíng xíng zhǐ", "origin": "《詩經·小雅·車舝》", "story": "景行者，大道光明之道也；行止者，依此大道身體力行也。儒家學者以崇高品德為人生高山，以光明大道為必由之徑，勉力前行終生不輟。", "quote": "高山仰止，景行行止。", "desc": "指依循光明正大之道德大道切實前進實踐。", "yin": "jǐng xíng xíng zhǐ"}, {"rank": 268, "idiom": "集思廣益", "pinyin": "jí sī guǎng yì", "origin": "三國蜀·諸葛亮《教與軍師長史參軍掾屬》", "story": "諸葛亮在漢中主持軍務，發布令文告誡屬官曰：『夫參署者，集眾思，廣忠益也。若猶預莫敢面折，以致差池，斯非相助之意也。夫避難免疑，何以治蜀！』告誡眾人務必暢所欲言，集合眾人智慧以謀取國家至高利益。", "quote": "夫參署者，集眾思，廣忠益也。", "desc": "指集中眾人的智慧與思考，廣泛吸收各方有益的意見以求完善。", "yin": "jí sī guǎng yì"}, {"rank": 267, "idiom": "綱舉目張", "pinyin": "gāng jǔ mù zhāng", "origin": "漢·鄭玄《詩譜序》", "story": "鄭玄為《詩經》作《詩譜序》，論統攝全體之要曰：『舉一綱而萬目張，解一卷而眾篇明。』綱指大漁網的總繩索，目指網眼。拉動大繩，千萬網眼自然齊整張開，比喻抓住主要矛盾便能帶動全局。", "quote": "舉一綱而萬目張，解一卷而眾篇明。", "desc": "比喻抓住事物的關鍵核心環節，帶動其他各個次要環節自然順理成章。", "yin": "gāng jǔ mù zhāng"}, {"rank": 266, "idiom": "殊途同歸", "pinyin": "shū tú tóng guī", "origin": "《周易·繫辭下》", "story": "《易》曰：『天下何思何慮？天下同歸而殊塗，一致而百慮。天下何思何慮？』萬物發展與諸子百家求索真理，出發的具體道路、角度各有不同，然而追求天下大治與終極大道之歸宿卻完全一致。", "quote": "天下同歸而殊塗，一致而百慮。天下何思何慮？", "desc": "比喻採取不同的道路或方法，最終達到了完全相同之目的結果。", "yin": "shū tú tóng guī"}, {"rank": 265, "idiom": "居仁由義", "pinyin": "jū rén yóu yì", "origin": "《孟子·盡心上》", "story": "孟子曰：『居惡在？仁是也；路惡在？義是也。居仁由義，大人之事備矣。』孟子指出君子立身處世，心靈安居於仁愛之宅邸，出入行走於正義之坦途，內仁外義，大人之品德便已圓滿具備。", "quote": "居惡在？仁是也；路惡在？義是也。居仁由義，大人之事備矣。", "desc": "指內心安處於仁愛之中，行事完全遵循正義之公理。", "yin": "jū rén yóu yì"}, {"rank": 264, "idiom": "反求諸己", "pinyin": "fǎn qiú zhū jǐ", "origin": "《孟子·離婁上》", "story": "孟子曰：『愛人不親，反其仁；治人不治，反其智；禮人不答，反其敬。行有不得者皆反求諸己，其身正而天下歸之。』每逢做事結果不如預期，不應推諉埋怨他人，當從自身尋找根本原因以加修正。", "quote": "行有不得者，皆反求諸己，其身正而天下歸之。", "desc": "遇到挫折或問題時，首先回過頭來從自己身上尋找原因與不足。", "yin": "fǎn qiú zhū jǐ"}, {"rank": 263, "idiom": "孜孜不倦", "pinyin": "zī zī bù juàn", "origin": "《尚書·益稷》/《三國志·蜀書·向朗傳》", "story": "禹拜曰：『都！予何言？予思日孜孜。』皋陶曰：『籲！如何？』禹曰：『洪水滔天，浩浩懷山襄陵，下民昏墊。予乘四載，隨山刊木，決九川距四海，濬畎澮距川。』大禹平治洪水日夜勤勉不知疲倦。後漢向朗更八十猶手自校書，孜孜不倦。", "quote": "禹曰：予思日孜孜。向朗潛心典籍，孜孜不倦。", "desc": "形容勤勉努力，工作或求學毫不倦怠鬆懈。", "yin": "zī zī bù juàn"}, {"rank": 262, "idiom": "義正辭嚴", "pinyin": "yì zhèng cí yán", "origin": "宋·朱熹《答蔣元質書》", "story": "朱熹在與門人辨正學術宗旨之書札中指出：立論立言，必須『義正而辭嚴，理明而氣盛』。所持的道義純粹端正，其辭句自能嚴謹堅決、擲地有聲，折服百代邪說異端。", "quote": "正其義而明其理，義正辭嚴，直斥其非。", "desc": "指理由正當充足，說話氣勢莊重嚴肅，無可辯駁。", "yin": "yì zhèng cí yán"}, {"rank": 261, "idiom": "剛正不阿", "pinyin": "gāng zhèng bù ā", "origin": "《明史·海瑞傳》", "story": "海瑞官戶部主事，時世宗好神仙長生，不視朝三十年，群臣莫敢指陳。瑞獨自買棺訣別妻子，上疏直言極諫帝之失。詔下獄拷問，終無悔意。世宗崩，得釋，為巡撫，力挫豪強，平反冤獄，世稱『海青天』，剛正不阿，天下景仰。", "quote": "海瑞為人，剛正不阿，雖貴戚強宗，望風屏跡。", "desc": "形容人剛直方正，堅持正道，絕不逢迎阿諛權貴。", "yin": "gāng zhèng bù ā"}, {"rank": 260, "idiom": "卓爾不群", "pinyin": "zhuó ěr bù qún", "origin": "漢·班固《漢書·景十三王傳贊》", "story": "班固贊河間獻王劉德好儒學、修先王之政、招致海內學者曰：『夫唯大雅，卓爾不群，河間獻王近之矣。』盛讚其識見才德卓越超拔，如鶴立雞群，遠遠超越尋常庸眾之上。", "quote": "夫唯大雅，卓爾不群，河間獻王近之矣。", "desc": "指才能品行卓越非凡，遠遠超越於同輩一般人之上。", "yin": "zhuó ěr bù qún"}, {"rank": 259, "idiom": "積毀銷骨", "pinyin": "jī huǐ xiāo gǔ", "origin": "《史記·張儀列傳》", "story": "張儀說魏王曰：『臣聞積羽沉舟，群輕折軸，眾口鑠金，積毀銷骨。』眾人不斷的造謠毀謗，日積月累，其毀滅性力量甚至可以銷蝕堅硬之骨骼，告誡不可輕忽讒言之禍害。", "quote": "眾口鑠金，積毀銷骨，讒諂蔽明，賢人見退。", "desc": "比喻毀謗造謠的話積聚多了，足以置人於死地或徹底毀掉一個人。", "yin": "jī huǐ xiāo gǔ"}, {"rank": 258, "idiom": "畫地為牢", "pinyin": "huà dì wèi láo", "origin": "漢·司馬遷《報任少卿書》", "story": "司馬遷受宮刑之後，忍辱負重成太史公書。在與任安書中慷慨陳詞曰：『古者士大夫顧廉恥，故畫地為牢，勢不可入；削木為吏，議不可對。期每至乎網繩，未嘗不痛心疾首也！』極言古代士大夫重名節至極，劃地圈定亦誓不越入。", "quote": "古者士大夫顧廉恥，故畫地為牢，勢不可入；削木為吏，議不可對。", "desc": "原指士人重視自律自尊，後多比喻只在指定範圍內活動，不準逾越界線一步。", "yin": "huà dì wèi láo"}, {"rank": 257, "idiom": "千慮一得", "pinyin": "qiān lǜ yī de", "origin": "《史記·淮陰侯列傳》", "story": "韓信破趙，求見廣武君李左車，解除其縛，客禮之，問伐燕齊之策。廣武君辭曰：『臣聞敗軍之將，不可以言勇；亡國之大夫，不可以圖存。』信曰：『僕委心歸計，願先生勿辭。』廣武君曰：『臣聞智者千慮，必有一失；愚者千慮，必有一得。故蒭蕘之言，聖人擇焉。』乃獻定燕齊全策。", "quote": "臣聞智者千慮，必有一失；愚者千慮，必有一得。", "desc": "指平凡普通人的反覆思索中，也必定能產生有價值可取的見解策略。", "yin": "qiān lǜ yī de"}, {"rank": 256, "idiom": "畫虎類狗", "pinyin": "huà hǔ lèi gǒu", "origin": "《後漢書·馬援傳》", "story": "馬援在交趾，與兄子嚴、敦書戒之曰：『吾欲汝曹聞人過失，如聞父母之名，耳可得聞，口不可得言也。龍伯高敦厚周慎，吾愛之重之，願汝曹效之；杜季良豪俠好義，憂人之憂，樂人之樂，清濁與同，吾愛之重之，不願汝曹效之。效伯高不得，猶為謹敕之士，所謂刻鵠不成尚類鶩者也；效季良不得，陷為天下輕薄子，所謂畫虎不成反類狗者也。』", "quote": "效季良不得，陷為天下輕薄子，所謂畫虎不成反類狗者也。", "desc": "比喻好高騖遠模仿他人不成，反而弄得不倫不類成為笑柄。", "yin": "huà hǔ lèi gǒu"}, {"rank": 255, "idiom": "羽翼已成", "pinyin": "yǔ yì yǐ chéng", "origin": "《史記·留侯世家》", "story": "漢高祖欲廢太子劉盈，立戚夫人子趙王如意。呂后用張良計，卑辭厚幣迎請商山四皓輔佐太子。高祖偶見四皓皓首白須，年皆八十有餘，從太子入朝。高祖大驚，召戚夫人指之曰：『我欲易之，彼四人輔之，羽翼已成，難動矣！呂后真而主矣。』戚夫人泣涕，高祖撫琴作鴻鵠歌。", "quote": "鴻鵠高飛，一舉千里。羽翮已就，橫絕四海。羽翼已成，難動矣。", "desc": "比喻勢力實力已經培植完備強大，難以輕易動搖改變。", "yin": "yǔ yì yǐ chéng"}, {"rank": 254, "idiom": "馬革裹屍", "pinyin": "mǎ gé guǒ shī", "origin": "《後漢書·馬援傳》", "story": "馬援字文淵，少有大志。常謂賓客曰：『大丈夫立志，窮當益堅，老當益壯。男兒要當死於邊野，以馬革裹屍還葬耳，何能臥床上在兒女子手中邪！』後出征交趾、武陵，年逾六十仍請纓跨馬，終卒於軍中，忠烈照千古。", "quote": "男兒要當死於邊野，以馬革裹屍還葬耳，何能臥床上在兒女子手中邪！", "desc": "形容英勇豪邁的軍人獻身疆場、死而後已的崇高壯烈情懷。", "yin": "mǎ gé guǒ shī"}, {"rank": 253, "idiom": "鑿壁偷光", "pinyin": "záo bì tōu guāng", "origin": "晉·葛洪《西京雜記·卷二》", "story": "匡衡字稚圭，勤學而無燭。鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。邑人大姓文不識，家富多書，衡乃與其傭作而不求償。主人怪問之，衡曰：『願得盡讀主家書。』主人感歎，資給以書，衡遂成一代大儒，位至丞相。", "quote": "匡衡勤學而無燭，鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。", "desc": "形容家境極度貧寒之士克服萬難，極其刻苦攻讀學問。", "yin": "záo bì tōu guāng"}, {"rank": 252, "idiom": "囊螢映雪", "pinyin": "náng yíng yìng xuě", "origin": "《晉書·車胤傳》/《晉書·孫康傳》", "story": "晉車胤字武子，家貧不常得油，夏月則練囊盛數十螢火蟲以照書，夜以繼日焉，後官至吏部尚書。同時孫康家貧無油，冬月常映雪讀書，手足凍裂亦不輟，後博通經史官至御史大夫。二典並稱囊螢映雪。", "quote": "車胤夏月則練囊盛螢以照書；孫康冬夜映雪讀書。", "desc": "比喻家貧如洗卻刻苦攻讀、堅持不懈之苦學楷模。", "yin": "náng yíng yìng xuě"}, {"rank": 251, "idiom": "牛角掛書", "pinyin": "niú jiǎo guà shū", "origin": "《新唐書·李密傳》", "story": "李密字玄邃，少時好讀書。嘗騎黃牛，以蒲韉乘之，掛《漢書》一帙於角上，一手捉牛靷，一手翻卷諷讀。越國公楊素行見而怪之，按轡躡其後曰：『何書生之勤苦至此？』密識素，下拜。素問所讀，曰：『《項羽傳》。』素大奇之，謂子玄感曰：『李密識度如此，汝等不及也。』", "quote": "李密乘黃牛，掛漢書一帙於牛角，一手捉牛靷，一手翻卷諷讀。", "desc": "形容抓緊一切零碎時間勤奮刻苦讀書求知。", "yin": "niú jiǎo guà shū"}, {"rank": 250, "idiom": "斷機教子", "pinyin": "duàn jī jiào zi", "origin": "漢·劉向《列女傳·母儀傳·鄒孟軻母》", "story": "孟子之少也，既學而歸，孟母方績，問曰：『學何所至矣？』孟子曰：『自若也。』孟母以刀斷其織。孟子懼而問其故，孟母曰：『子之廢學，若吾斷斯織也！夫君子學以立名，問則廣知。今廢學，不免於役隸。』孟子懼，旦夕勤勉不輟，遂成天下大儒。", "quote": "孟母引刀斷其織曰：子之廢學，若吾斷斯織也！", "desc": "比喻慈母以決絕生動的行動警戒勸勉子女切勿半途廢學。", "yin": "duàn jī jiào zi"}, {"rank": 249, "idiom": "程門立雪", "pinyin": "chéng mén lì xuě", "origin": "《宋史·楊時傳》", "story": "楊時字中立，調官不赴，往見程頤於洛。時蓋年四十矣，一日見頤，頤偶瞑坐，時與遊酢侍立不去。頤既覺，則門外雪深一尺矣。學者尊師重道，侍立風雪之中毫無怠惰，千載傳為求道極致典範。", "quote": "頤瞑坐，時與遊酢侍立不去。頤既覺，則門外雪深一尺矣。", "desc": "形容尊師重道，極度虔誠求學之精神。", "yin": "chéng mén lì xuě"}, {"rank": 248, "idiom": "焚膏繼晷", "pinyin": "fén gāo jì guǐ", "origin": "唐·韓愈《進學解》", "story": "韓愈自述研經求學之艱辛曰：『先生口不絕吟於六藝之文，手不停披於百家之編；記事者必提其要，纂言者必鉤其玄。貪多務得，細大不捐。焚膏油以繼晷，恆兀兀以窮年。』點燃燈油接續白晝日光，日以繼夜苦讀。", "quote": "焚膏油以繼晷，恆兀兀以窮年。", "desc": "形容夜以繼日、廢寢忘食地刻苦努力工作或讀書。", "yin": "fén gāo jì guǐ"}, {"rank": 247, "idiom": "亢龍有悔", "pinyin": "kàng lóng yǒu huǐ", "origin": "《周易·乾卦·上九》", "story": "乾卦上九曰：『亢龍，有悔。』子曰：『貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。』龍飛至最高極限處，居高臨下亢極不返，必生傾覆懊悔之患。警醒世人凡事盛極必衰，當居盈持滿戒慎恐懼。", "quote": "上九：亢龍，有悔。何謂也？子曰：貴而無位，高而無民，是以動而有悔也。", "desc": "比喻居高位者過於驕橫自滿或發展達到頂點，必然引發後悔失敗。", "yin": "kàng lóng yǒu huǐ"}, {"rank": 246, "idiom": "潛龍勿用", "pinyin": "qián lóng wù yòng", "origin": "《周易·乾卦·初九》", "story": "乾卦初九曰：『潛龍，勿用。』子曰：『龍德而隱者也。不易乎世，不成乎名；遯世無悶，不見是而無悶；樂則行之，憂則違之；確乎其不可拔，潛龍也。』君子在時機未至、實力尚處蓄積之初，當沉潛修德，切忌輕舉妄動。", "quote": "初九：潛龍，勿用。何謂也？子曰：龍德而隱者也。", "desc": "比喻人才尚在潛伏隱伏積累之期，應當韜光養晦，不可盲目冒進。", "yin": "qián lóng wù yòng"}, {"rank": 245, "idiom": "厚積薄發", "pinyin": "hòu jī báo fā", "origin": "宋·蘇軾《稼說送張琥》", "story": "蘇軾以農夫種稼為喻，誡張琥曰：『博觀而約取，厚積而薄發，吾告子止於此矣。』如同富貴之家蓄積充盈而用度節制，學人必當博覽深蓄無窮學養，待其純熟至極方從容展現發揮其精粹。", "quote": "博觀而約取，厚積而薄發，吾告子止於此矣。", "desc": "指經過長久深厚的儲備累積，然後才能從容釋放展現巨大的能量。", "yin": "hòu jī báo fā"}, {"rank": 244, "idiom": "不落窠臼", "pinyin": "bù luò kē jiù", "origin": "宋·嚴羽《滄浪詩話·詩評》", "story": "嚴羽論詩之高境曰：『盛唐諸公之詩，如空中之音，相中之色，水中之月，鏡中之象，言有盡而意無窮。初學必須立志高遠，擺脫前人陳套，不落窠臼，方能自成大家風範。』", "quote": "起步必高，行文命意，自不落窠臼。", "desc": "比喻藝術文章或構想立意獨創新穎，不落入陳舊俗套的格式之中。", "yin": "bù luò kē jiù"}, {"rank": 243, "idiom": "鬼斧神工", "pinyin": "guǐ fǔ shén gōng", "origin": "《莊子·達生》", "story": "梓慶削木為鐻，鐻成，見者驚猶鬼神。魯侯見而問焉，曰：『子何術以為焉？』對曰：『臣工人，何術之有！雖然，有一焉：臣將為鐻，未嘗敢氣也，必齊以靜心。齊三日而不敢懷慶賞爵祿，齊五日不敢懷非譽巧拙，齊七日輒然忘吾有四枝形體也。當是時也，無公朝，其巧專而外骨消。然後入山林，觀天性；形軀至矣，然後成見鐻，然後加手焉。以天合天，器之所以疑神者，其是與！』", "quote": "以天合天，器之所以疑神者，其是與！", "desc": "形容技藝精巧高超到了極點，彷彿非人力所為，出於鬼神斧鑿天工。", "yin": "guǐ fǔ shén gōng"}, {"rank": 242, "idiom": "渾然天成", "pinyin": "hún rán tiān chéng", "origin": "唐·韓愈《清河張君墓誌銘》", "story": "韓愈撰張君墓銘，讚其為人文質兼美，行事順應天然情理，文章德行『如天工織雲，水注大壑，渾然天成，無斧鑿痕跡』。自然融通毫無割裂生硬之感。", "quote": "文章妙處，渾然天成，不見斧鑿之痕跡。", "desc": "形容詩文結構或事物天然圓融，毫無牽強人工造作之痕跡。", "yin": "hún rán tiān chéng"}, {"rank": 241, "idiom": "巧奪天工", "pinyin": "qiǎo duó tiān gōng", "origin": "元·趙孟頫《贈放煙火者》", "story": "人間巧藝奪天工，煉藥燃燈清晝同。元代大書畫家趙孟頫觀賞民間巧匠製作之煙火奇觀，五彩絢爛若神霄絳闕，讚歎人工製作之巧妙精緻甚至勝過大自然的鬼斧造化。", "quote": "人間巧藝奪天工，煉藥燃燈清晝同。", "desc": "形容人工技藝精美巧妙到了極致，勝過大自然鬼斧神工之造化。", "yin": "qiǎo duó tiān gōng"}, {"rank": 240, "idiom": "大巧若拙", "pinyin": "dà qiǎo ruò zhuō", "origin": "《老子·第四十五章》", "story": "老子曰：『大成若缺，其用不弊。大盈若沖，其用不窮。大直若屈，大巧若拙，大辯若訥。躁勝寒，靜勝炅，清靜為天下正。』真正至高之大智慧大技巧，表面看來質樸純真，毫不賣弄雕琢之浮華。", "quote": "大直若屈，大巧若拙，大辯若訥。", "desc": "指真正具有絕頂才智技巧者，外表看起來反而純樸拙笨而不顯露炫耀。", "yin": "dà qiǎo ruò zhuō"}, {"rank": 239, "idiom": "登堂入室", "pinyin": "dēng táng rù shì", "origin": "《論語·先進》", "story": "子曰：『由也升堂矣，未入於室也。』子路彈瑟，門人不敬。孔子解喻子路的學問好比已經登上宗廟大堂，只是尚未進到深處內室而已，雖未臻極頂，已相當深厚，門人不應輕侮。", "quote": "子曰：由也升堂矣，未入於室也。", "desc": "比喻學問、技藝由淺入深，逐步達到了高深精湛的極佳境地。", "yin": "dēng táng rù shì"}, {"rank": 238, "idiom": "按圖索驥", "pinyin": "àn tú suǒ jì", "origin": "漢·班固《漢書·梅福傳》", "story": "孫陽（伯樂）著《相馬經》，書有馬相：『額頭隆起如日，目如懸蕫，蹄如垂麴。』其子按書中描摹尋求千里馬，出門見大蟾蜍，歸告其父曰：『得一馬，略與同，但蹄不垂麴耳！』伯樂笑曰：『此馬好跳，不堪御也！』後以比喻不知變通機械照搬教條尋求人才。", "quote": "今海內通識之士，按圖索驥，恐失千里之良足也。", "desc": "比喻墨守成規不知變通地照線索尋找，亦指按照線索追查事物。", "yin": "àn tú suǒ jì"}, {"rank": 237, "idiom": "白頭偕老", "pinyin": "bái tóu xié lǎo", "origin": "《詩經·衛風·氓》/明·陸採《懷香記》", "story": "及爾偕老，老使我怨。淇則有岸，隰則有泮。《詩經》本歌詠結髮夫妻相濡以沫同甘共苦之初心，後世因稱夫妻二人忠貞相守，自青春年華直至頭髮斑白依然相伴白首。", "quote": "結髮為夫妻，恩愛兩不疑。生當復來歸，死當長相思。白頭偕老，永以為好。", "desc": "形容夫妻共同生活恩愛長久，一直到白髮蒼蒼的老年。", "yin": "bái tóu xié lǎo"}, {"rank": 236, "idiom": "同甘共苦", "pinyin": "tóng gān gòng kǔ", "origin": "《戰國策·燕策一》", "story": "燕昭王即位，卑身厚幣以招賢。弔死問孤，與百姓同甘共苦。二十八年，燕國殷富，士卒樂軼輕戰，遂使樂毅將兵大破齊國七十餘城，報齊破燕之深仇。", "quote": "燕昭王弔死問孤，與百姓同甘共苦，二十八年，國富兵強。", "desc": "形容共同承擔艱辛苦楚，共同分享歡樂幸福。", "yin": "tóng gān gòng kǔ"}, {"rank": 235, "idiom": "琴瑟和鳴", "pinyin": "qín sè hé míng", "origin": "《詩經·小雅·棠棣》", "story": "妻子好合，如鼓琴瑟。兄弟既翕，和樂且湛。《詩經》以大琴與小瑟之五音調和、和諧共振，象徵家庭和睦融洽、夫妻恩愛和順之天倫至樂。", "quote": "妻子好合，如鼓琴瑟。兄弟既翕，和樂且湛。", "desc": "比喻夫妻感情和諧篤厚，情投意合融洽相處。", "yin": "qín sè hé míng"}, {"rank": 234, "idiom": "鸞鳳和鳴", "pinyin": "luán fèng hé míng", "origin": "《左傳·莊公二十二年》", "story": "陳公子完奔齊，齊桓公欲妻之。懿仲筮之，妻敬仲。其妻佔之，曰：『吉。是謂鳳凰於飛，和鳴鏘鏘。有媯之後，將育於姜。五世其昌，並於正卿。八世之後，莫之與京！』以瑞鳥鸞鳳高鳴齊飛，兆示良緣天成興旺發達。", "quote": "是謂鳳凰於飛，和鳴鏘鏘。五世其昌，並於正卿。", "desc": "舊時常用於祝頌新婚夫妻百年好合、和諧美滿吉祥如意。", "yin": "luán fèng hé míng"}, {"rank": 233, "idiom": "破鏡重圓", "pinyin": "pò jìng chóng yuán", "origin": "唐·孟棨《本事詩·情感》", "story": "陳太子舍人徐德言娶陳後主妹樂昌公主。陳將亡，德言破一銅鏡，各持其半，約曰：『日後必以正月望日賣合於都市。』陳亡，公主入隋越國公楊素家。及期，德言至京師，果見一僕求半鏡如天價。德言出半鏡合之，題詩曰：『鏡與人俱去，鏡歸人不歸。無復姮娥影，空留明月輝！』楊素聞之感愴，乃召德言還其妻，厚贈資產遣歸。", "quote": "鏡與人俱去，鏡歸人不歸。無復姮娥影，空留明月輝！", "desc": "比喻夫妻在分散失散之後重新團聚，或破裂關係重新修好合好。", "yin": "pò jìng chóng yuán"}, {"rank": 232, "idiom": "聞雞起舞", "pinyin": "wén jī qǐ wǔ", "origin": "《晉書·祖逖傳》", "story": "範陽祖逖少有大志，與譙國劉琨俱為司州主簿，情好綢繆，共被同寢。中夜聞荒雞鳴，蹴琨覺曰：『此非惡聲也！』因起舞劍。逖、琨自此中宵起舞練劍，研習兵書，後二人皆為晉朝抵禦強胡克復失土之北方督帥忠臣。", "quote": "中夜聞荒雞鳴，蹴琨覺曰：此非惡聲也！因起舞。", "desc": "形容有志之士抓緊光陰刻苦習武學藝，準備立功報國之奮發圖強精神。", "yin": "wén jī qǐ wǔ"}, {"rank": 231, "idiom": "枕戈待旦", "pinyin": "zhěn gē dài dàn", "origin": "《晉書·劉琨傳》", "story": "劉琨與祖逖同懷收復中原之志。五胡亂華，中原淪沒，琨在幷州與胡狄血戰數年。在與親故書中痛切陳詞曰：『吾枕戈待旦，志梟逆虜，常恐祖生先吾著鞭！』枕著兵器睡覺等待天明，日夜戒備誓殺國賊。", "quote": "吾枕戈待旦，志梟逆虜，常恐祖生先吾著鞭！", "desc": "形容時刻高度戒備，時刻準備著投入打擊敵人之戰鬥。", "yin": "zhěn gē dài dàn"}, {"rank": 230, "idiom": "投鞭斷流", "pinyin": "tóu biān duàn liú", "origin": "《晉書·苻堅載記》", "story": "前秦苻堅大舉伐晉，發兵百萬。陽平公苻融等苦諫不可伐江東，堅笑傲群臣曰：『吾統承大業垂三十載，四方略定，唯東南一隅未賓。今以吾百萬之眾，投鞭於江，足斷其流，又何險之足憚哉！』驕狂自滿，卒致淝水全軍潰敗。", "quote": "堅曰：以吾之眾旅，投鞭於江，足斷其流，何險之足憚！", "desc": "形容兵馬陣容極其浩大眾多，亦含有驕傲輕敵之教訓。", "yin": "tóu biān duàn liú"}, {"rank": 229, "idiom": "草木皆兵", "pinyin": "cǎo mù jiē bīng", "origin": "《晉書·苻堅載記》", "story": "淝水之戰，秦王苻堅與苻融登壽陽城望晉軍。見晉軍部隊嚴整齊肅，又遠望八公山上草木皆類人形，堅大驚失色，顧謂融曰：『此亦勍敵也，何謂弱乎！』憮然有懼色。驚疑過度，將漫山遍野草木搖曳皆看成晉軍伏兵。", "quote": "堅與苻融登城而望王師，望八公山上草木，皆類人形，顧謂融曰：此亦勍敵，何謂弱也！", "desc": "形容極度驚恐疑懼，把周圍一草一木都看作了襲擊自己的敵兵。", "yin": "cǎo mù jiē bīng"}, {"rank": 228, "idiom": "風聲鶴唳", "pinyin": "fēng shēng hè lì", "origin": "《晉書·謝玄傳》", "story": "淝水之役，謝玄、謝琰率八千精騎大破前秦軍，苻融陣亡。秦兵大潰自相蹂踐，奔逃晝夜不敢息，聞風聲鶴唳，皆以為王師已至，草行露宿，凍餒死者十七八。極度恐慌之中，連夜風呼嘯仙鶴哀鳴亦以為追兵殺到。", "quote": "秦軍大敗，潰兵逃散，聞風聲鶴唳，皆以為晉軍且至。", "desc": "形容失敗者在逃亡潰散時極度疑懼驚慌、自相驚擾的神態。", "yin": "fēng shēng hè lì"}, {"rank": 227, "idiom": "江郎才盡", "pinyin": "jiāng láng cái jǐn", "origin": "《南史·江淹傳》", "story": "江淹字文通，少以文章稱盛，晚節名位日隆，詩文反見退步，無復昔日清麗警拔之採。傳其嘗宿守冶亭，夢一人自稱郭璞曰：『吾有筆在卿處多年，可以見還。』淹探懷中得五色筆授之，爾後為詩絕無美句，時人謂之『江郎才盡』。", "quote": "淹探懷中得五色筆授之，爾後為詩，絕無美句，時人謂之江郎才盡。", "desc": "比喻文思枯竭，才華創造力退步消失，不復往日風采。", "yin": "jiāng láng cái jǐn"}, {"rank": 226, "idiom": "七步成詩", "pinyin": "qī bù chéng shī", "origin": "南朝宋·劉義慶《世說新語·文學》", "story": "魏文帝嫉曹植之才，命其走完七步之內吟詩一首，否則處以極刑。曹植從容邁步，應聲吟出千古絕唱《七步詩》，悲憤陳辭『本自同根生，相煎何太急』。文帝大慚赦免。千古贊其神思超邁敏捷至極。", "quote": "文帝令東阿王七步中作詩，不成者行大法。植應聲便為詩。", "desc": "形容才思極其敏捷，在極短的時間內就能創作出精彩高超的詩章文篇。", "yin": "qī bù chéng shī"}, {"rank": 225, "idiom": "請君入甕", "pinyin": "qǐng jūn rù wèng", "origin": "《資治通鑑·唐紀二十·天授二年》", "story": "武后時，周興、來俊臣皆以酷吏橫行。有人告周興謀反，太后命來俊臣審之。俊臣請興飲酒，問曰：『囚多不肯承，當何以治之？』興笑曰：『此甚易！取大甕，以炭火四面燒之，令囚入中，何事不承！』俊臣命取甕炭如法，起謂興曰：『有敕命按君謀反，請君入甕！』興大驚失色，叩頭服罪。", "quote": "俊臣起謂興曰：有敕按君，請君入此甕！興大驚，叩頭伏罪。", "desc": "比喻用某人發明用來懲治別人的惡毒手段反過來整治其本人。", "yin": "qǐng jūn rù wèng"}, {"rank": 224, "idiom": "水漲船高", "pinyin": "shuǐ zhǎng chuán gāo", "origin": "宋·釋道原《景德傳燈錄·卷二十九》", "story": "禪宗語錄借自然之機明道曰：『水長船高，泥多佛大。』河水漲起一尺，水面上之舟船自然亦隨之浮升一尺。說明事物往往隨其依託的客觀基礎或條件之提高而相應提高昇華。", "quote": "水長船高，泥多佛大，自然之理也。", "desc": "比喻事物隨其所憑藉的基礎提高而相應得到提升。", "yin": "shuǐ zhǎng chuán gāo"}, {"rank": 223, "idiom": "黃粱一夢", "pinyin": "huáng liáng yī mèng", "origin": "唐·沈既濟《枕中記》", "story": "盧生少年貧困，於邯鄲旅舍遇道士呂翁。生歎困窘，翁授青瓷枕，生入夢。夢娶清河崔氏女，登進士，累官節度使、同中書門下平章事，出將入相五十年，子孫滿堂極富貴。壽八十餘病篤，驚覺，見身仍臥旅肆，主人所蒸黃粱米飯尚未蒸熟。翁笑曰：『黃粱猶未熟，一夢到華胥！』", "quote": "生欠伸而悟，見其身方偃於邸舍，主人蒸黍尚未熟，觸類如故。", "desc": "比喻榮華富貴如夢幻泡影短暫無常，亦比喻美好的願望落空。", "yin": "huáng liáng yī mèng"}, {"rank": 222, "idiom": "南柯一夢", "pinyin": "nán kē yī mèng", "origin": "唐·李公佐《南柯太守傳》", "story": "淳于棼醉臥古槐下，夢入大槐安國，尚金枝公主，拜南柯太守，政績卓著，富貴顯赫二十年。後檀蘿國進攻，兵敗，公主死，被黜遣返。驚覺醒來，見夕陽未落，尋槐樹下，乃見槐樹大穴中有大蟻穴，即所謂大槐安國，南面一枝即南柯郡也。", "quote": "棼感南柯之幻，悟人生之如寄，遂棲心道門。", "desc": "形容得失榮華如同虛無虛妄的一場大夢，轉瞬成空。", "yin": "nán kē yī mèng"}, {"rank": 221, "idiom": "東窗事發", "pinyin": "dōng chuāng shì fā", "origin": "明·田汝成《西湖遊覽志餘·卷四》", "story": "秦檜欲殺嶽飛，於東窗下與妻王氏密謀。王氏曰：『縛虎容易縱虎難，宜斬草除根！』遂害嶽武穆。檜死，其子熺為請道士超度，道士入冥界見檜荷鐵枷受地獄劇苦，檜謂道士曰：『可告吾妻，東窗事發矣！』密謀暗害忠良之罪孽在陰司徹底暴露。", "quote": "檜荷鐵枷受罪，語道士曰：寄語夫人，東窗事發矣！", "desc": "比喻秘密謀劃的罪惡陰謀敗露被揭發。", "yin": "dōng chuāng shì fā"}, {"rank": 220, "idiom": "精忠報國", "pinyin": "jīng zhōng bào guó", "origin": "《宋史·嶽飛傳》", "story": "嶽飛字鵬舉，相州湯陰人。少負氣節，母姚氏刺『精忠報國』四字於其背，深入膚理。飛矢志克復中原，迎還二聖，率岳家軍百戰百勝，朱仙鎮大破金兀朮，終以莫須有冤獄屈死風波亭，其精忠壯志萬代崇仰。", "quote": "初命何鑄鞫之，飛裂裳以背示鑄，有精忠報國四大字，深入膚理。", "desc": "形容至誠至忠、誓死報效祖國的赤子忠心。", "yin": "jīng zhōng bào guó"}, {"rank": 219, "idiom": "徙木立信", "pinyin": "xǐ mù lì xìn", "origin": "《史記·商君列傳》", "story": "商鞅變法，令既具，未布，恐民不信。乃立三丈之木於國都市南門，募民有能徙置北門者予十金。民怪之，莫敢徙。復曰：『能徙者予五十金！』有一人徙之，輒予五十金，以明不欺。卒下令變法，秦人由是大信商鞅法令。", "quote": "有一人徙之，輒予五十金，以明不欺。卒下令。", "desc": "比喻通過具體行動彰顯誠信，以樹立朝廷法度之絕對權威。", "yin": "xǐ mù lì xìn"}, {"rank": 218, "idiom": "信賞必罰", "pinyin": "xìn shǎng bì fá", "origin": "《韓非子·外儲說右上》", "story": "韓非子論明君治國之柄曰：『賞存則爵祿慶賞必信，罰存則刑戮誅罰必果。夫賞罰不信，則士民莫肯用命；信賞必罰，則百官肅服，天下莫敢犯紀。』強調信賞必罰乃法治之柱石綱領。", "quote": "信賞必罰，以示不欺，則雖赴湯蹈火，民無退心。", "desc": "指有功勞者必定賞賜，有過犯者必定懲處，賞罰極其分明嚴格。", "yin": "xìn shǎng bì fá"}, {"rank": 217, "idiom": "強項令名", "pinyin": "qiáng xiàng lìng míng", "origin": "《後漢書·酷吏傳·董宣》", "story": "董宣為洛陽令。光武帝姊湖陽公主蒼頭白日殺人，匿主家，吏不能捕。宣候主出行，攔車拉奴下車格殺之。主入宮訴帝，帝大怒，召宣欲撾殺之。宣叩頭論法，帝令宣叩頭謝主，宣兩手據地，頸項強硬直立，終不肯俛首。帝乃笑曰：『枹鼓之吏，何其強項邪！敕強項令出，賜錢三十萬。』", "quote": "帝令小黃門持宣使叩頭謝主，宣兩手據地，終不肯俛。帝敕強項令出！", "desc": "形容為官剛正嚴明不畏強暴權貴、絕不低頭折節之硬骨頭精神。", "yin": "qiáng xiàng lìng míng"}, {"rank": 216, "idiom": "蘇武牧羊", "pinyin": "sū wǔ mù yáng", "origin": "《漢書·蘇武傳》", "story": "武帝天漢元年，蘇武持節使匈奴，遇虞常謀反事發受牽連，武引刀自刺明志。單於壯其節欲降之，置之大窖中絕飲食，武雪與旃毛同嚥，數日不死。單於乃徙武北海無人處牧羝，曰：『羝乳乃得歸！』武臥起操持漢節，節毛盡落。十九年不屈，終全節歸漢。", "quote": "武臥起操持，節毛盡落。杖漢節牧羊，歷十九年不屈。", "desc": "形容在極端嚴酷屈辱的環境下，堅貞不屈維護國家民族尊嚴氣節。", "yin": "sū wǔ mù yáng"}, {"rank": 215, "idiom": "鴻鵠之志", "pinyin": "hóng hú zhī zhì", "origin": "《史記·陳涉世家》", "story": "陳涉少時，嘗與人傭耕，輟耕之壟上，悵恨久之，曰：『苟富貴，無相忘。』傭者笑而應曰：『若為傭耕，何富貴也？』陳涉太息曰：『嗟乎，燕雀安知鴻鵠之志哉！』後果然首舉義旗抗暴秦，天下英雄雲集。", "quote": "陳涉太息曰：嗟乎，燕雀安知鴻鵠之志哉！", "desc": "比喻遠大宏偉的崇高志向與理想抱負。", "yin": "hóng hú zhī zhì"}, {"rank": 214, "idiom": "瞞天過海", "pinyin": "mán tiān guò hǎi", "origin": "《三十六計·勝戰計》", "story": "三十六計第一計：瞞天過海。語出唐太宗徵高麗，畏江海風浪大不敢登舟，將軍薛仁貴引帝至大帳設宴飲酒，內飾彩繡如宮殿。酒酣波濤驟起，帳幔捲起，帝始悟大船早已破浪行於大海深處。", "quote": "備周則意怠，常見則不疑。陰在陽之內，不在陽之對。太陽，太陰。", "desc": "比喻偽裝隱瞞真相，在公開平靜的假象掩飾下暗中實施重大行動。", "yin": "mán tiān guò hǎi"}, {"rank": 213, "idiom": "聲東擊西", "pinyin": "shēng dōng jī xī", "origin": "《淮南子·兵略訓》/《通典·兵六》", "story": "聲東者，虛張聲勢以惑敵也；擊西者，隱蔽主攻直擣要害也。漢高祖伐魏豹，陳船臨晉佯作渡河狀，暗伏木罌從夏陽偷渡安邑，一舉俘虜魏豹。", "quote": "聲言擊東，其實擊西，出其不備，破敵於冥冥。", "desc": "指表面上製造聲勢要攻打東面，實際卻突襲西面的奇巧作戰謀略。", "yin": "shēng dōng jī xī"}, {"rank": 212, "idiom": "無中生有", "pinyin": "wú zhōng shēng yǒu", "origin": "《老子·第四十章》/《三十六計·敵戰計》", "story": "老子曰：天下萬物生於有，有生於無。兵法引申為：誑也，非誑也，實其所誑也。少陰、太陰、太陽。張巡守雍丘，夜縋草人千餘引令狐潮箭矢數十萬，次夜縋真人勇士直衝賊營大破之。", "quote": "誑也，非誑也，實其所誑也。少陰、太陰、太陽。", "desc": "比喻憑空捏造事端假象，或運用虛實轉化策略化無為有克敵制勝。", "yin": "wú zhōng shēng yǒu"}, {"rank": 211, "idiom": "暗度陳倉", "pinyin": "àn dù chén cāng", "origin": "《史記·高祖本紀》/《三十六計·敵戰計》", "story": "漢王劉邦起巴蜀，韓信為大將軍。明修子午道棧道以迷惑章邯，暗中卻率大軍出陳倉故道，奇襲三秦，一舉平定關中，奠定漢家天下根本基石。", "quote": "明修棧道，暗度陳倉，遂定三秦。", "desc": "比喻將真實企圖隱蔽在偽裝迷惑行動之後，暗中採取決定性行動。", "yin": "àn dù chén cāng"}, {"rank": 210, "idiom": "隔岸觀火", "pinyin": "gé àn guān huǒ", "origin": "《三十六計·攻戰計》", "story": "陽乖序亂，陰以待逆。暴戾恣睢，其勢自斃。順以聽之，事與逆機。曹操破袁紹，袁尚、袁熙奔遼東投公孫康。諸將請急攻之，操曰：『吾方使康斬二袁送首，不勞兵也。』康果疑二袁吞己，置酒伏兵斬之送操。", "quote": "陽乖序亂，陰以待逆。暴戾恣睢，其勢自斃。", "desc": "比喻對別人的危難爭鬥採取冷眼旁觀態度，坐待時機變化。", "yin": "gé àn guān huǒ"}, {"rank": 209, "idiom": "李代桃僵", "pinyin": "lǐ dài táo jiāng", "origin": "樂府古辭《雞鳴》/《三十六計·敵戰計》", "story": "桃生露井上，李樹生桃旁。蟲來齧桃根，李樹代桃僵。樹木且相代，兄弟何相忘！原本歌詠兄弟互為犧牲承擔災難，兵法引伸為局部付出相應代價以換取全局決定性勝利。", "quote": "桃生露井上，李樹生桃旁。蟲來齧桃根，李樹代桃僵。", "desc": "比喻以此代彼，或犧牲局部利益以保全全盤大局。", "yin": "lǐ dài táo jiāng"}, {"rank": 208, "idiom": "順手牽羊", "pinyin": "shùn shǒu qiān yáng", "origin": "《三十六計·混戰計》", "story": "微隙在所必乘，纖利在所必得。少陰，少陽。戰場上遇敵方微小破綻漏洞，當順手捉拿利用，隨時隨地積聚細微勝利以擴大戰果。", "quote": "微隙在所必乘，纖利在所必得。", "desc": "比喻趁著做某件事的順便機會，輕而易舉地取得別的便宜或物資。", "yin": "shùn shǒu qiān yáng"}, {"rank": 207, "idiom": "打草驚蛇", "pinyin": "dǎ cǎo jīng shé", "origin": "宋·鄭文寶《南唐近事》/《三十六計·混戰計》", "story": "南唐當塗令王魯貪墨，百姓狀告主簿行賄索賄。王魯判牘自批八字曰：『汝雖打草，吾已蛇驚！』懼其貪行亦將敗露。兵家因以比喻試探性行動使敵方驚動暴露真相。", "quote": "汝雖打草，吾已蛇驚！", "desc": "比喻行事不密或試探行動草率，反而使對方有所警覺防範。", "yin": "dǎ cǎo jīng shé"}, {"rank": 206, "idiom": "借屍還魂", "pinyin": "jiè shī huán hún", "origin": "《三十六計·攻戰計》", "story": "有用者不可借，不能者不可用。借不能者而用之，匪我求童蒙，童蒙求我。劉備借劉琦荊州刺史長子之名分收撫荊襄；借漢室皇叔之名召聚天下人心，均為此策神用。", "quote": "有用者不可借，不能者不可用。借不能者而用之。", "desc": "比喻已經死亡消亡或過時的事物，藉助另一種形式偽裝復活。", "yin": "jiè shī huán hún"}, {"rank": 205, "idiom": "調虎離山", "pinyin": "diào hǔ lí shān", "origin": "《三十六計·攻戰計》", "story": "待天以困之，用人以誘之。往蹇來連。老虎身處險峻深山威不可當，一旦用計誘騙引其離開巢穴來到平川，其威猛之勢自消，便可輕易制服捉拿。", "quote": "待天以困之，用人以誘之，引其出穴，聚而殲之。", "desc": "比喻用計謀誘使對方離開堅固強大的據點或基地，以便趁機將其擊破。", "yin": "diào hǔ lí shān"}, {"rank": 204, "idiom": "欲擒故縱", "pinyin": "yù qín gù zòng", "origin": "《三十六計·攻戰計》", "story": "逼則反兵，走則減勢。緊隨勿迫，熠氣以耗其力，消其鬥志，散而後擒。諸葛亮南征孟獲，七擒七縱，心悅誠服，南方終身不復叛反，深得此計精髓。", "quote": "逼則反兵，走則減勢。緊隨勿迫，熠氣以耗其力，消其鬥志，散而後擒。", "desc": "比喻為了徹底控制或達到目的，故意先放鬆約束任其自流以瓦解抵抗。", "yin": "yù qín gù zòng"}, {"rank": 203, "idiom": "拋磚引玉", "pinyin": "pāo zhuān yǐn yù", "origin": "宋·釋道原《景德傳燈錄·卷十》/《三十六計·敵戰計》", "story": "唐詩人常建敬慕趙嘏名詩。知嘏將遊蘇州靈巖寺，建先於寺壁題詩二句，嘏至，續成四句絕句，文采超邁遠過前聯。時人笑稱常建以粗糙破磚引出無價美玉。", "quote": "類以誘之，擊蒙也。以粗淺之言引出博雅之見，曰拋磚引玉。", "desc": "謙稱用自己粗淺成熟度不高的發言作品，引出他人高雅精彩之言論成果。", "yin": "pāo zhuān yǐn yù"}, {"rank": 202, "idiom": "擒賊擒王", "pinyin": "qín zéi qín wáng", "origin": "唐·杜甫《前出塞九首·其六》/《三十六計·攻戰計》", "story": "挽弓當挽強，用箭當用長。射人先射馬，擒賊先擒王。杜甫詩論戰陣之精要，摧毀敵陣務必先解決其魁首核心，首腦一斃，群龍無首，其餘部屬自作鳥獸散。", "quote": "射人先射馬，擒賊先擒王。", "desc": "比喻處理複雜紛亂問題，必須首先抓住主要關鍵人物或核心要害。", "yin": "qín zéi qín wáng"}, {"rank": 201, "idiom": "釜底抽薪", "pinyin": "fǔ dǐ chōu xīn", "origin": "漢·董卓《董嶠傳》/《三十六計·混戰計》", "story": "水沸不可止，抽其薪則止矣。阻敵之勢，莫如拔除其根本所資。官渡之戰曹操夜襲烏巢，燒毀袁紹全部糧草積聚，袁軍軍心大亂，不戰自潰。", "quote": "抽薪止沸，剪草除根，從根本解決問題也。", "desc": "比喻從根本上抽調或解決問題的關鍵支撐，以徹底瓦解事態危機。", "yin": "fǔ dǐ chōu xīn"}, {"rank": 200, "idiom": "金蟬脫殼", "pinyin": "jīn chán tuō ké", "origin": "《三十六計·混戰計》/元·關漢卿《謝天香》", "story": "存其形，完其勢；友不疑，敵不動。巽而止蠱。蟬蛻變之時，外殼依然牢牢留在樹枝之上，完好無損，本體卻早已悄然脫化飛去。諸葛亮身故五丈原，楊儀以木雕諸葛亮坐車中，姜維勒兵，司馬懿望之驚走，蜀軍安然全軍退回漢中。", "quote": "存其形，完其勢；友不疑，敵不動。巽而止蠱。", "desc": "比喻製造假象迷惑對方以隱蔽轉移，悄悄脫身逃離險境。", "yin": "jīn chán tuō ké"}, {"rank": 199, "idiom": "關門捉賊", "pinyin": "guān mén zhuō zéi", "origin": "《三十六計·混戰計》", "story": "小敵困之。剝，不利有攸往。對於孤立無援的小股敵軍，必須斷其逃路退路，合圍聚殲。若任其逃脫，往往死灰復燃竄入山險釀成大患。", "quote": "小敵困之。截斷其後，閉關合圍，一舉擒戮。", "desc": "比喻關閉所有門戶通道，將潛入之盜賊或敵對勢力徹底聚殲捉拿。", "yin": "guān mén zhuō zéi"}, {"rank": 198, "idiom": "遠交近攻", "pinyin": "yuǎn jiāo jìn gōng", "origin": "《戰國策·秦策三》", "story": "范雎入秦，見秦昭王，說之曰：『王不如遠交而近攻，得寸則王之寸也，得尺亦王之尺也。今釋此而攻齊，跨韓魏而越險阻，破之亦不能有。王若交齊楚而伐韓魏，因以蠶食中原，霸業成矣！』秦王大悅，用其策，終一統天下。", "quote": "王不如遠交而近攻，得寸則王之寸也，得尺亦王之尺也。", "desc": "指結交離自己較遠的國家或勢力，集中全力攻打臨近弱小對手之戰略。", "yin": "yuǎn jiāo jìn gōng"}, {"rank": 197, "idiom": "借刀殺人", "pinyin": "jiè dāo shā rén", "origin": "《三十六計·勝戰計》", "story": "敵已明，友未定，引友殺敵，不自出力，以損推演。三國赤壁之戰前夕，曹操遣蔣幹說周瑜，周瑜偽造曹操水軍都督蔡瑁、張允暗通江東之密信，使蔣幹盜回，曹操閱後盛怒斬殺二將，自毀水軍主力棟樑。", "quote": "引友殺敵，不自出力，因其所忌而剪除之。", "desc": "比喻自己不出面，借用第三者或對方的刀劍力量去消滅仇人或對手。", "yin": "jiè dāo shā rén"}, {"rank": 196, "idiom": "偷梁換柱", "pinyin": "tōu liáng huàn zhù", "origin": "《三十六計·並戰計》", "story": "頻更其陣，抽其勁旅，待其自敗，掩而覆之。趁著混戰協同之機，暗中抽換更替敵方或盟友之主力中堅支柱，換以疲軟衰朽之輩，使其內部架構崩解，任我掌控宰割。", "quote": "抽其勁旅，以疲弱代之，使其傾頹自斃。", "desc": "比喻暗中玩弄手法，以假代真或抽換本質骨幹，使事物面目全非。", "yin": "tōu liáng huàn zhù"}, {"rank": 195, "idiom": "指桑罵槐", "pinyin": "zhǐ sāng mà huái", "origin": "《三十六計·並戰計》", "story": "大淩小者，警以誘之。剛中而應，行險而順。齊景公遣田穰苠為將抵禦晉燕之兵，莊賈監軍遲到，穰苠按軍法斬莊賈以肅軍紀。三軍士卒皆股慄肅然，此即藉懲治近臣樹立軍威，指桑罵槐，使眾人望風奉令。", "quote": "大淩小者，警以誘之。嚴立法度，以警三軍。", "desc": "比喻表面上藉責罵這一方，實際上暗指並斥責另一方。", "yin": "zhǐ sāng mà huái"}, {"rank": 194, "idiom": "假痴不癲", "pinyin": "jiǎ chī bù diān", "origin": "《三十六計·並戰計》", "story": "寧偽作不知不為，不偽作假動。靜以伏莽。三國司馬懿面對曹爽專橫擅權，在家裝病裝痴，口流口水，連粥羹皆灑於胸前。曹爽放鬆戒備出城祭掃高平陵，司馬懿立即召集舊部閉門發難，一舉誅殺曹爽三族奪得魏國大權。", "quote": "寧偽作不知不為，不偽作假動。靜以待機，伺虛發難。", "desc": "比喻表面上假裝糊塗痴呆，以麻痺對手戒心，暗中積聚力量尋求致勝戰機。", "yin": "jiǎ chī bù diān"}, {"rank": 193, "idiom": "上屋抽梯", "pinyin": "shàng wū chōu tī", "origin": "《三十六計·並戰計》/《三國志·蜀書·諸葛亮傳》", "story": "劉表長子劉琦因蔡瑁擁立少子劉琮，自身危急，問計於諸葛亮。亮每避而不答。琦乃邀亮入後園高樓飲酒，令人撤去登樓梯蹬，謂亮曰：『今上不至天，下不至地，出子之口，入琦之耳，可言未？』亮乃教以申生在內而亡，重耳在外而安之策，令其出鎮江夏保全性命。", "quote": "劉琦誘亮登高樓飲，命去其梯，乃請保身之策。", "desc": "比喻用計誘人登高或深入險境，然後撤走其退路，使其別無選擇只能從命。", "yin": "shàng wū chōu tī"}, {"rank": 192, "idiom": "反客為主", "pinyin": "fǎn kè wèi zhǔ", "origin": "《三十六計·並戰計》", "story": "乘隙插足，扼其主機，漸之進也。步步滲透以奪取主導支配權。劉備入益州，劉璋迎之以拒張魯。劉備借葭萌關屯駐，廣施恩德收攬蜀中民心軍心，反戈進攻成都，終取代劉璋建立蜀漢基業。", "quote": "乘隙插足，扼其主機，漸進奪魁，反客為主。", "desc": "比喻本處於被動客隨地位，經過巧妙周旋轉化為主動掌控大局者。", "yin": "fǎn kè wèi zhǔ"}, {"rank": 191, "idiom": "笑裡藏刀", "pinyin": "xiào lǐ cáng dāo", "origin": "《新唐書·李義府傳》/《三十六計》", "story": "唐高宗時李義府貌似溫恭，與人言談必嘻怡微笑，而內心陰狠嫉忌，凡觸犯自己者，必暗中傾陷殘害，死傷相藉。時人痛斥其為『笑中有刀』，又號為『李貓』。", "quote": "義府貌狀溫恭，與人語必嬉怡微笑，而褊忌陰賊，人謂之笑中有刀。", "desc": "形容外表和藹可親，內心卻隱藏著極其陰險毒辣之害人手段。", "yin": "xiào lǐ cáng dāo"}, {"rank": 190, "idiom": "趁火打劫", "pinyin": "chèn huǒ dǎ jié", "origin": "《三十六計·勝戰計》", "story": "敵之害大，就勢取利。剛決柔也。趁著對方陷入火災之難、內亂混亂之危殆關頭，不但不施以援手，反倒乘虛而入大肆掠奪掠取暴利。", "quote": "敵之害大，就勢取利，乘其危困而傾覆之。", "desc": "比喻趁著別人的危難困境之際，大肆敲詐索取、牟取私利。", "yin": "chèn huǒ dǎ jié"}, {"rank": 189, "idiom": "樹上開花", "pinyin": "shù shàng kāi huā", "origin": "《三十六計·並戰計》", "story": "借局布勢，力小勢大。鴻漸於陸，其羽可用為儀。樹上本無花，剪綵紙為花貼於枝頭，遠遠望去繁花似錦。長坂坡張飛帶二十餘騎斷後，令軍士於樹林後拖曳樹枝揚塵，曹操追兵見塵土蔽天，疑有大隊伏兵，不敢進逼。", "quote": "借局布勢，力小勢大，以虛聲震懾敵膽也。", "desc": "比喻借用他人的聲勢或虛設盛大外觀，使微弱力量顯得無比龐大盛大。", "yin": "shù shàng kāi huā"}, {"rank": 188, "idiom": "走為上計", "pinyin": "zǒu wèi shàng jì", "origin": "《南齊書·王敬則傳》/《三十六計》", "story": "南齊王敬則起兵反蕭鸞，聞朝廷派軍討伐，謂其部將曰：『檀公三十六策，走是上計！汝父子唯急走耳。』檀道濟善用兵，退兵時量沙唱籌以安軍心。面對絕對劣勢無法力敵之局，及時全軍退走保全實力乃最高明決斷。", "quote": "檀公三十六策，走為上計。全師避難，伺機復起。", "desc": "指事情陷入絕對無望不利境地時，撤退避走乃是最為上乘之自保策略。", "yin": "zǒu wèi shàng jì"}, {"rank": 187, "idiom": "兵不厭詐", "pinyin": "bīng bù yàn zhà", "origin": "《韓非子·難一》", "story": "晉文公將與楚戰於城濮，召咎犯問曰：『楚眾我寡，奈何？』咎犯對曰：『臣聞繁禮君子，不厭忠信；戰陣之間，不厭詐偽。君其詐之而已矣。』兩軍對壘性命江山攸關，只要能克敵取勝，一切智謀偽裝皆合兵道。", "quote": "戰陣之間，不厭詐偽。君其詐之而已矣。", "desc": "指作戰用兵為了克敵制勝，不排斥使用各種虛實偽詐的計謀戰法。", "yin": "bīng bù yàn zhà"}, {"rank": 186, "idiom": "知己知彼", "pinyin": "zhī jǐ zhī bǐ", "origin": "《孫子·謀攻》", "story": "孫子曰：『故知勝有五：知可以戰與不可以戰者勝，識眾寡之用者勝，上下同欲者勝，以虞待不虞者勝，將能而君不御者勝。此五者，知勝之道也。故曰：知己知彼，百戰不殆；不知彼而知己，一勝一負；不知彼不知己，每戰必殆。』", "quote": "知己知彼，百戰不殆；不知彼而知己，一勝一負；不知彼不知己，每戰必殆。", "desc": "指對自己的實力底細和對方的虛實底細都能瞭如指掌透徹洞察。", "yin": "zhī jǐ zhī bǐ"}, {"rank": 185, "idiom": "百戰百勝", "pinyin": "bǎi zhàn bǎi shèng", "origin": "《孫子·謀攻》", "story": "孫子曰：『凡用兵之法，全國為上，破國次之；全軍為上，破軍次之。是故百戰百勝，非善之善者也；不戰而屈人之兵，善之善者也。』極言軍事實戰逢戰必捷，但至高之道在於不戰屈敵。", "quote": "百戰百勝，非善之善者也；不戰而屈人之兵，善之善者也。", "desc": "形容每戰必勝，所向無敵，具有卓越至極的戰鬥勝利本領。", "yin": "bǎi zhàn bǎi shèng"}, {"rank": 184, "idiom": "避實就虛", "pinyin": "bì shí jiù xū", "origin": "《孫子·虛實》", "story": "孫子曰：『夫兵形象水，水之行，避高而趨下；兵之勝，避實而擊虛。水因地而制流，兵因敵而制勝。故兵無常勢，水無常形。能因敵變化而取勝者，謂之神。』用兵如同流水，避開敵方重兵堅壁，直擣其薄弱虛空要害。", "quote": "兵之形避高而趨下，兵之勝避實而擊虛。", "desc": "指避開敵方堅固防守主力，專門尋找並打擊對方的薄弱空隙處。", "yin": "bì shí jiù xū"}, {"rank": 183, "idiom": "出奇制勝", "pinyin": "chū qí zhì shèng", "origin": "《孫子·勢篇》", "story": "孫子曰：『凡戰者，以正合，以奇勝。故善出奇者，無窮如天地，不竭如江海。奇正相生，如循環之無端，孰能窮之！』以常規正面兵力牽制抵抗，以意料之外的奇兵偏師出其不意奪取全勝。", "quote": "凡戰者，以正合，以奇勝。故善出奇者，無窮如天地。", "desc": "指使用意料之外的新穎奇巧戰術或策略，出其不意取得勝利。", "yin": "chū qí zhì shèng"}, {"rank": 182, "idiom": "勢均力敵", "pinyin": "shì jūn lì dí", "origin": "《南史·劉穆之傳》", "story": "宋高祖劉裕創興大業，劉穆之為首謀重臣。論四方群雄角逐時局，謂雙方兵甲實力、謀略智勇彼此相當，難分高下，如弈棋對壘，勝負全在一著之微差。", "quote": "兩雄相抗，勢均力敵，非智略決絕者不能勝。", "desc": "形容雙方勢力、力量、水平均等，實力不相上下。", "yin": "shì jūn lì dí"}, {"rank": 181, "idiom": "旗鼓相當", "pinyin": "qí gǔ xiāng dāng", "origin": "《後漢書·隗囂傳》", "story": "隗囂割據隴右，與公孫述抗衡，移書長官曰：『如令子陽到漢中、三輔，願因將軍兵馬，鼓旗相當。』比喻雙方陣容規模旗幟戰鼓齊整對峙，實力旗鼓相當難分勝負。", "quote": "如令子陽入關，願因將軍兵馬，旗鼓相當以角雌雄。", "desc": "比喻雙方本領、陣容或實力不相上下，實力相當。", "yin": "qí gǔ xiāng dāng"}, {"rank": 180, "idiom": "棋逢敵手", "pinyin": "qí féng dí shǒu", "origin": "唐·尚顏《懷陸龜蒙處士》", "story": "夜坐空書枕，秋吟欲到天。棋逢敵手難藏幸，詩到窮時始見工。弈棋遇到真正旗鼓相當的對手，絕無任何僥倖贏棋之機，步步必須深思熟慮竭盡平生絕技。", "quote": "棋逢敵手難藏幸，詩到窮時始見工。", "desc": "比喻遇上了水平技術不相上下的強勁對手。", "yin": "qí féng dí shǒu"}, {"rank": 179, "idiom": "針鋒相對", "pinyin": "zhēn fēng xiāng duì", "origin": "宋·釋道原《景德傳燈錄·卷二》", "story": "禪宗大德機鋒對辯，截斷眾流。語錄雲：『夫為法王，問答玄機，針鋒相對，絲毫不容寬貸藉藉。』兩根針的針尖對碰在一起，比喻在議論交鋒或鬥爭中雙方針鋒相對毫無退讓讓步。", "quote": "玄機妙辨，如針鋒相對，不差分毫。", "desc": "比喻雙方在言論、行動或態度上尖銳對立，寸步不讓。", "yin": "zhēn fēng xiāng duì"}, {"rank": 178, "idiom": "銳不可當", "pinyin": "ruì bù kě dāng", "origin": "《史記·淮南衡山列傳》", "story": "伍被諫淮南王安反漢曰：『今漢帝春秋鼎盛，大將軍衛青、霍去病材力絕人，士卒勇悍，百戰百勝，氣勢鋒銳不可當也！王若發難，必無後福。』銳氣之鋒芒盛大，天下無人能抵擋阻截。", "quote": "將軍精悍，戰氣正旺，其銳不可當也。", "desc": "形容氣勢迅猛勇銳，力量浩大，不可阻擋抵禦。", "yin": "ruì bù kě dāng"}, {"rank": 177, "idiom": "所向披靡", "pinyin": "suǒ xiàng pī mǐ", "origin": "《史記·項羽本紀》", "story": "項王垓下突圍，至東城，乃有二十八騎。項王謂其騎曰：『吾起兵至今八歲矣，身七十餘戰，所當者破，所擊者服，未嘗敗北，遂霸有天下。然今卒困於此，此天之亡我，非戰之罪也！』項王大呼馳下，漢軍皆披靡，遂斬漢一將。", "quote": "項王大呼馳下，漢軍皆披靡，遂斬漢一將。", "desc": "比喻軍隊力量或威力無比強大，所到之處敵人紛紛潰退瓦解。", "yin": "suǒ xiàng pī mǐ"}, {"rank": 176, "idiom": "風捲殘雲", "pinyin": "fēng juǎn cán yún", "origin": "唐·戎昱《苦熱行》/元·王實甫《西廂記》", "story": "烈風狂捲過長空，殘存零星烏雲剎那間被席捲掃蕩乾淨無蹤。比喻以摧枯拉朽之神速，將殘餘事物一掃而光徹底解決。", "quote": "狂飆掠野，如風捲殘雲，天地澄明一洗而空。", "desc": "形容狂風把殘存雲片一掃而光，比喻一舉將殘存之物消滅蕩滌殆盡。", "yin": "fēng juǎn cán yún"}, {"rank": 175, "idiom": "摧枯拉朽", "pinyin": "cuī kū lā xiǔ", "origin": "《晉書·甘卓傳》", "story": "甘卓起兵討王敦，梁州刺史周訪遺卓書曰：『大將軍首唱大義，天下莫不響應。王敦逆天罔上，其敗必矣。以將軍之威名，督大軍順流而下討賊，譬如摧枯拉朽，何難之有！』摧折枯死之草木，拔除朽爛之竹竿，言其極其容易迅速。", "quote": "將軍順流討逆，若摧枯拉朽，何難之有！", "desc": "形容摧毀腐朽破敗的反動殘餘勢力極其迅速徹底、毫不費力。", "yin": "cuī kū lā xiǔ"}, {"rank": 174, "idiom": "雷霆萬鈞", "pinyin": "léi tíng wàn jūn", "origin": "漢·賈山《至言》", "story": "賈山諫漢文帝興禮樂安萬民，論及地皇天威曰：『雷霆之所擊，無不糜碎；萬鈞之所壓，無不破滅。明主之威若雷霆萬鈞，天下安敢有抗命者！』極言威力聲勢宏巨雄壯到了極致。", "quote": "雷霆之所擊無不糜碎，萬鈞之所壓無不破滅。", "desc": "形容威力和聲勢無比強大，如同雷震重壓，摧毀一切阻擋。", "yin": "léi tíng wàn jūn"}, {"rank": 173, "idiom": "排山倒海", "pinyin": "pái shān dǎo hǎi", "origin": "《資治通鑑·齊紀·東昏侯》", "story": "崔慧景圍建康城，聲勢甚盛，齊帝令衛尉蕭懿入援。懿將兵順流而下，軍容盛大，旗幟如林。史臣讚其軍威滔滔如潮湧動，『氣象萬千，若排山而倒海也』，沛莫能禦。", "quote": "大軍進擊，若排山倒海，天地動色。", "desc": "形容力量聲勢極其浩大磅礴，如同搬動高山傾倒大海一般。", "yin": "pái shān dǎo hǎi"}, {"rank": 172, "idiom": "翻天覆地", "pinyin": "fān tiān fù dì", "origin": "唐·劉商《金井哀》", "story": "劉商感歎世道滄桑巨變，作詩詠人事造化轉移，言其翻轉天地傾覆乾坤，舊日體制山河徹底重塑，造化功力磅礴浩大。", "quote": "人事翻天覆地，山川變幻，唯大道常存。", "desc": "形容變化巨大而徹底，亦形容秩序鬧得不可開交天翻地覆。", "yin": "fān tiān fù dì"}, {"rank": 171, "idiom": "滄海桑田", "pinyin": "cāng hǎi sāng tián", "origin": "晉·葛洪《神仙傳·麻姑》", "story": "神仙麻姑謂王方平曰：『接待以來，已見東海三為桑田。向到蓬萊，水又淺於往者會時略半也，豈將復為陵陸乎？』方平笑曰：『聖人皆言海中行復揚塵也。』大海化為種桑良田，滄桑變化，極言時光久遠世事巨變。", "quote": "麻姑自說雲：接侍以來，已見東海三為桑田。", "desc": "比喻世事滄桑，世間事物與社會環境發生了巨大深刻的變化。", "yin": "cāng hǎi sāng tián"}, {"rank": 170, "idiom": "白雲蒼狗", "pinyin": "bái yún cāng gǒu", "origin": "唐·杜甫《可嘆》", "story": "天上浮雲如白衣，斯須改變如蒼狗。古往今來共如此，人生何事苦淹留！杜甫感歎世事風雲無常，天際潔白如衣裳之雲塊，轉眼之間幻化為蒼黑奔犬，比喻人間世局富貴榮華幻化轉瞬即逝。", "quote": "天上浮雲如白衣，斯須改變如蒼狗。", "desc": "比喻事物或世局變化多端無常，不可預測捉摸。", "yin": "bái yún cāng gǒu"}, {"rank": 169, "idiom": "鬥轉星移", "pinyin": "dòu zhuǎn xīng yí", "origin": "唐·王勃《滕王閣序》", "story": "閑雲潭影日悠悠，物換星移幾度秋。閣中帝子今何在？檻外長江空自流！王勃在詩中描繪北斗星杓旋轉指移，群星流轉季候變遷，慨歎歲月光陰在自然規律中飛速流淌流逝。", "quote": "閑雲潭影日悠悠，物換星移幾度秋。", "desc": "形容時光日月流逝、四季氣候歲月迅速更替遷流。", "yin": "dòu zhuǎn xīng yí"}, {"rank": 168, "idiom": "物換星移", "pinyin": "wù huàn xīng yí", "origin": "唐·王勃《滕王閣序》", "story": "萬物更替，鬥宿轉移。滕王昔日歌舞昇平之繁華盛宴早已隨風消散，唯餘秋水長天萬古江流，深沉抒發宇宙浩瀚永恆與人生興衰轉變。", "quote": "閑雲潭影日悠悠，物換星移幾度秋。", "desc": "指景物人事變換，星宿移動，慨歎時光與人間世事的重大變遷。", "yin": "wù huàn xīng yí"}, {"rank": 167, "idiom": "光陰似箭", "pinyin": "guāng yīn shì jiàn", "origin": "唐·韋莊《關河道中》", "story": "落第關河道中，韋莊長嘯長空：『朝露暗迎新節序，夕陽空送遠行客。光陰似箭催人老，日月如梭趕少年！』時光如同離弦之飛箭疾馳而去，片刻不停，勉勵世人惜陰奮進。", "quote": "光陰似箭催人老，日月如梭趕少年。", "desc": "形容時間過得極快，如同離弦的飛箭般飛逝。", "yin": "guāng yīn shì jiàn"}, {"rank": 166, "idiom": "日月如梭", "pinyin": "rì yuè rú suō", "origin": "宋·高登《高東溪文集》", "story": "日往月來，如同織布之梭子在織機經緯線間飛速穿梭往返。高登文論人生韶光之短暫，警醒學者切勿虛擲青春年華於怠惰消磨之中。", "quote": "日月如梭，光陰不居，盛年不再，及時當勉。", "desc": "形容太陽和月亮交替運轉，日子過得極快如同飛梭。", "yin": "rì yuè rú suō"}, {"rank": 165, "idiom": "歲月蹉跎", "pinyin": "suì yuè cuō tuó", "origin": "晉·阮籍《詠懷詩》", "story": "娛樂未畢，白日西匿。促促靡所騁，歲月逝蹉跎！阮籍在詠懷詩中慨歎志願未申而白日西沉，時光白白浪費虛度而無所成就，流露憂世深沉之悲鳴。", "quote": "娛樂未畢，白日西匿。促促靡所騁，歲月逝蹉跎！", "desc": "形容白白浪費大好時光，虛度歲月年華而一事無成。", "yin": "suì yuè cuō tuó"}, {"rank": 164, "idiom": "尺璧非寶", "pinyin": "chǐ bì fēi bǎo", "origin": "《淮南子·原道訓》/《千字文》", "story": "聖人不貴尺之璧，而重寸之陰，時難得而易失也。禹之趨時也，履遺而弗取，冠掛而弗顧，非爭其先也，而爭其疾也。徑尺之和氏美玉固然珍貴，亦比不上片刻光陰之稍縱即逝。", "quote": "尺璧非寶，寸陰是競。時難得而易失也。", "desc": "指一尺直徑的和璧寶玉並非真正至寶，片刻時光才是真正無價之珍寶。", "yin": "chǐ bì fēi bǎo"}, {"rank": 163, "idiom": "寸陰是競", "pinyin": "cùn yīn shì jìng", "origin": "《晉書·陶侃傳》/《千字文》", "story": "陶侃常語人曰：『大禹聖者，乃惜寸陰；至於眾人，當惜分陰。虛擲歲月，生無益於時，死無聞於後，是自棄也！』侃任官勤恪終日，躬自檢閱書牘，寸陰是惜，終建立東晉中興元勳。", "quote": "大禹聖者，乃惜寸陰；至於眾人，當惜分陰。寸陰是競，不可虛度。", "desc": "指爭分奪秒，珍惜每一寸光陰，絕不浪費絲毫時間。", "yin": "cùn yīn shì jìng"}, {"rank": 162, "idiom": "盛年不重", "pinyin": "shèng nián bù zhòng", "origin": "晉·陶淵明《雜詩》", "story": "人生無根蒂，飄如陌上塵。分散逐風轉，此已非常身。盛年不重來，一日難再晨。及時當勉勵，歲月不待人！陶潛藉人生短促之痛，勉勵後生切勿延宕光陰，把握壯年韶光努力立身立德。", "quote": "盛年不重來，一日難再晨。及時當勉勵，歲月不待人。", "desc": "指人生的青春鼎盛年華一去不復返，警醒人應及時努力奮勉。", "yin": "shèng nián bù zhòng"}, {"rank": 161, "idiom": "及時當勉", "pinyin": "jí shí dāng miǎn", "origin": "晉·陶淵明《雜詩》", "story": "陶淵明力勸學者趁著精壯年華抓緊時機奮勉上進，日月逝矣歲月不居，一旦韶華老去悔之已晚，當抓緊眼前時機自強自勵。", "quote": "盛年不重來，一日難再晨。及時當勉勵，歲月不待人。", "desc": "指應當抓緊當下寶貴時機自我奮勉勉勵，努力建功立業求知求學。", "yin": "jí shí dāng miǎn"}, {"rank": 160, "idiom": "學海無涯", "pinyin": "xué hǎi wú yá", "origin": "唐·韓愈《進學解》引申/明·趙弼《效顰集》", "story": "學問之大海浩瀚汪洋，廣袤無邊無際。韓愈《進學解》言百家經傳宏富至極，學者終身窮索猶覺淺陋，後世遂以學海無涯苦作舟相勉，學無止境。", "quote": "書山有路勤為徑，學海無涯苦作舟。", "desc": "比喻知識學問如浩瀚海洋般深廣廣闊，永無止境。", "yin": "xué hǎi wú yá"}, {"rank": 159, "idiom": "循循善誘", "pinyin": "xún xún shàn yòu", "origin": "《論語·子罕》", "story": "顏淵喟然歎曰：『仰之彌高，鑽之彌堅；瞻之在前，忽焉在後。夫子循循然善誘人，博我以文，約我以禮，欲罷不能。既竭吾才，如有所立卓爾。』孔子施教善於一步步有次序地誘導啟發學生智慧。", "quote": "夫子循循然善誘人，博我以文，約我以禮，欲罷不能。", "desc": "指善於有步驟、有秩序、耐心地引導教育他人。", "yin": "xún xún shàn yòu"}, {"rank": 158, "idiom": "誨人不倦", "pinyin": "huì rén bù juàn", "origin": "《論語·述而》", "story": "子曰：『默而識之，學而不厭，誨人不倦，何有於我哉？』孔子自謙平生德業，唯此三者勉力實踐：默默牢記真理、勤奮求學從不自滿、耐心施教啟發後進永不覺疲倦。", "quote": "默而識之，學而不厭，誨人不倦，何有於我哉？", "desc": "指耐心地教育教導人，始終堅持不懈，不知疲倦。", "yin": "huì rén bù juàn"}, {"rank": 157, "idiom": "春風化雨", "pinyin": "chūn fēng huà yǔ", "origin": "《孟子·盡心上》", "story": "孟子曰：『君子之所以教者五：有如時雨化之者，有成德者，有達財者，有答問者，有私淑艾者。此五者，君子之所以教也。』優秀良師之薰陶教誨，如同春風吹拂、甘霖潤澤萬物，潤物細無聲。", "quote": "君子之教，有如時雨化之者，隨時霑潤，莫不滋榮。", "desc": "比喻良好適時的師道教育陶冶，自然深沉地感化滋潤人心。", "yin": "chūn fēng huà yǔ"}, {"rank": 156, "idiom": "桃李滿門", "pinyin": "táo lǐ mǎn mén", "origin": "《資治通鑑·唐紀·武后天授二年》", "story": "狄仁傑為宰相，每薦拔人才，皆忠直勤勞之士，張柬之、姚崇皆出其門下。或謂仁傑曰：『天下桃李，悉在公門矣！』仁傑笑曰：『薦賢為國，非為私也。』以此極讚其門生故吏人才濟濟遍天下。", "quote": "或謂仁傑曰：天下桃李，悉在公門矣！仁傑曰：薦賢為國，非為私也。", "desc": "形容所培養教育的優秀門生弟子極其眾多，遍佈各地。", "yin": "táo lǐ mǎn mén"}, {"rank": 155, "idiom": "薪火相傳", "pinyin": "xīn huǒ xiāng chuán", "origin": "《莊子·養生主》", "story": "指窮於為薪，火傳也，不知其盡也。《莊子》以此名理揭示生命精神與道術之真諦：作為燃燒載體之柴薪終有燒盡枯竭之時，然而燃起的火種卻代代相傳延續，薪火不熄，萬劫長存。", "quote": "指窮於為薪，火傳也，不知其盡也。", "desc": "比喻學問、思想、精神或技藝代代相傳，傳承不絕。", "yin": "xīn huǒ xiāng chuán"}, {"rank": 154, "idiom": "繼往開來", "pinyin": "jì wǎng kāi lái", "origin": "宋·朱熹《朱子全書·道統》", "story": "朱熹總結儒家道統傳承之功，贊周敦頤、二程接續孔孟絕學曰：『繼往聖之絕學，開來世之太平。』繼承前人開創之輝煌基業學統，開闢拓展通向未來之康莊大道。", "quote": "繼往聖之絕學，開來世之宏圖，前修未密，後學是賴。", "desc": "指繼承前人的崇高事業或傳統，並為未來的發展開闢全新道路。", "yin": "jì wǎng kāi lái"}, {"rank": 153, "idiom": "革故鼎新", "pinyin": "gé gù dǐng xīn", "origin": "《周易·雜卦》", "story": "《周易·雜卦傳》曰：『革，去故也；鼎，取新也。』革卦代表破除陳舊腐朽、消除積弊弊端；鼎卦代表確立全新法度、開創新體制新局面。推陳出新乃天地大化變革之至理。", "quote": "革，去故也；鼎，取新也。革故鼎新，天下大治。", "desc": "指破除革除舊有的陳規陋習與腐朽制度，創立推行全新制度與風氣。", "yin": "gé gù dǐng xīn"}, {"rank": 152, "idiom": "獨樹一幟", "pinyin": "dú shù yī zhì", "origin": "清·袁枚《隨園詩話》", "story": "袁枚評詩論藝，倡導性靈之說，反對因襲摹擬前人，指出名家必當：『不隨世俗步趨，獨立精神，獨樹一幟，自立門戶！』在文壇或事業中獨立樹立起一面鮮明的旗幟風格。", "quote": "夫立論命旨，當獨樹一幟，自立門庭，豈可俯仰由人！", "desc": "比喻獨自創立一種新流派、新主張或獨特風格，與眾不同。", "yin": "dú shù yī zhì"}, {"rank": 151, "idiom": "別具一格", "pinyin": "bié jù yī gé", "origin": "清·呂留良《東莊詩存序》", "story": "呂留良評東莊詩文，讚其風骨高邁，在當時爭奇鬥艷之流俗中另立規矩，品貌特立，『自有一種瀟灑沉雄之格調，別具一格，令人讀之醒目』。", "quote": "其詩不入俗流，別具一格，自成高境。", "desc": "指另外有一種與眾不同的獨特風格或新穎格調。", "yin": "bié jù yī gé"}, {"rank": 150, "idiom": "自成一家", "pinyin": "zì chéng yī jiā", "origin": "《漢書·司馬遷傳贊》/南朝宋·劉義慶《世說新語》", "story": "司馬遷作《史記》，網羅天下放失舊聞，考之行事，稽其成敗興壞之理，凡百三十篇，成一家之言。班固讚其學識體系前無古人，獨具匠心，卓然自立自成一家。", "quote": "亦欲以究天人之際，通古今之變，成一家之言。", "desc": "指在學術、藝術或某項領域內具有獨特的風格體系，自立門戶。", "yin": "zì chéng yī jiā"}, {"rank": 149, "idiom": "匠心獨運", "pinyin": "jiàng xīn dú yùn", "origin": "唐·王士源《孟浩然集序》", "story": "王士源序孟浩然詩集，盛讚其山水田園詩幽深淡遠、高妙渾成：『文不按古，匠心獨運。神清氣朗，獨超眾類！』能不受前人框架拘束，在心靈深處獨特運籌設計藝術佳境。", "quote": "文不按古，匠心獨運，神骨超然。", "desc": "形容在文學、藝術或設計發明中具有獨創巧妙的心思與獨特構思。", "yin": "jiàng xīn dú yùn"}, {"rank": 148, "idiom": "妙手偶得", "pinyin": "miào shǒu ǒu dé", "origin": "宋·陸遊《文章》", "story": "文章本天成，妙手偶得之。粹然無疵瑕，豈復須人為！陸放翁指出天地間最高妙之文章大作本由天地自然之化機孕育而成，卓越的詩人偶逢神會，靈犀觸動，信手拈來而成絕唱。", "quote": "文章本天成，妙手偶得之。粹然無疵瑕，豈復須人為！", "desc": "比喻技藝高超的大師在靈感忽至之際，出其不意創作出神來妙作。", "yin": "miào shǒu ǒu dé"}, {"rank": 147, "idiom": "筆走龍蛇", "pinyin": "bǐ zǒu lóng shé", "origin": "唐·李白《草書歌行》", "story": "少年上人號懷素，草書天下稱獨步。墨池飛出北溟魚，筆鋒殺盡中山兔。時時只見龍蛇走，左盤右蹙旭驚電！李白觀賞懷素草書運筆疾如閃電，墨痕蜿蜒起伏若神龍矯蛇飛騰騰躍。", "quote": "時時只見龍蛇走，左盤右蹙旭驚電。", "desc": "形容書法用筆生動流暢、氣勢磅礴宛若飛龍靈蛇奔走。", "yin": "bǐ zǒu lóng shé"}, {"rank": 146, "idiom": "鐵畫銀鉤", "pinyin": "tiě huà yín gōu", "origin": "唐·張懷瓘《書斷·王廙》", "story": "張懷瓘品評東晉書法名家王廙草書曰：『王廙右軍之叔，少有重名。其點畫遒勁，有鐵畫銀鉤之勢，冠絕江南。』形容其點畫遒勁宛如生鐵鑄造，轉折提鉤精妙若銀條屈曲，兼具骨力與柔美。", "quote": "王廙少有重名，書有鐵畫銀鉤之勢，冠絕江左。", "desc": "形容書法筆鋒遒勁剛健而又圓潤精巧，骨肉停勻。", "yin": "tiě huà yín gōu"}, {"rank": 145, "idiom": "力透紙背", "pinyin": "lì tòu zhǐ bèi", "origin": "唐·顏真卿《述張長史筆法十二意》/清·趙翼《甌北詩話》", "story": "顏真卿從張旭學草書，悟得用筆屋漏痕之法，筆鋒沈著剛健，入紙極深。清代趙翼亦稱優秀詩作文字沉雄渾厚，『如魯公作書，力透紙背』，令人讀之骨聳。", "quote": "筆力沉雄，頓挫沈鬱，真所謂力透紙背者也。", "desc": "形容書法運筆遒勁有力，墨汁穿透紙背，亦比喻文章議論深刻入骨。", "yin": "lì tòu zhǐ bèi"}, {"rank": 144, "idiom": "顏筋柳骨", "pinyin": "yán jīn liǔ gǔ", "origin": "宋·范仲淹《祭石學士文》", "story": "唐楷鼎立兩大宗師：顏真卿楷書沉雄寬博、筋腱豐滿內蘊醇厚，世稱顏筋；柳公權楷書瘦硬挺拔、骨力遒健稜角分明，世稱柳骨。范仲淹讚石曼卿書法兼融二人之長，『曼卿之書，顏筋柳骨，冠絕一時』。", "quote": "曼卿之書，顏筋柳骨，冠絕一時。", "desc": "指顏真卿書法的豐滿渾厚筋力與柳公權書法的遒勁清拔骨力，書法典範。", "yin": "yán jīn liǔ gǔ"}, {"rank": 143, "idiom": "龍飛鳳舞", "pinyin": "lóng fēi fèng wǔ", "origin": "宋·蘇軾《表忠觀碑》", "story": "熙寧十年蘇軾撰書《表忠觀碑》，記吳越錢氏三世保境安民歸宋之盛德。其碑字大如拳，氣象磅礴，蘇子自謂『生平得意之書，如龍飛鳳舞，翔動凌厲於石碑之上』。", "quote": "瞻望殿宇，蟠龍飛鳳舞之勢，山川改色。", "desc": "形容書法用筆氣勢奔放舒展、豪邁生動，亦形容山川形勢蜿蜒壯美。", "yin": "lóng fēi fèng wǔ"}, {"rank": 142, "idiom": "畫龍點睛", "pinyin": "huà lóng diǎn jīng", "origin": "唐·張彥遠《歷代名畫記·張僧繇》", "story": "梁張僧繇於金陵安樂寺壁畫四白龍，不點眼睛。每曰：『點之即飛去！』人以為誕，固請點之。僧繇當即點其二龍之目。須臾，雷電破壁，二龍乘雲騰空飛天而去；未點睛者二龍見在。", "quote": "僧繇潤色點睛，須臾雷電交加，二龍騰雲飛天而去。", "desc": "比喻在寫作文章或講話的最要害關鍵處加上精彩關鍵一筆，使整體瞬間生動傳神。", "yin": "huà lóng diǎn jīng"}, {"rank": 141, "idiom": "神來之筆", "pinyin": "shén lái zhī bǐ", "origin": "清·李汝珍《鏡花緣》/清·馮班《鈍吟書要》", "story": "馮班論書法文章靈感至境，謂佳作每在物我兩忘超然神馳之際突然湧現：『不假人工安排，宛如神人相助，真可謂神來之筆！』揮毫之處如天籟自然發響。", "quote": "此處行文，如神來之筆，令人拍案叫絕。", "desc": "形容詩文、書畫或構想極其神奇絕妙，出神入化如同神明所賦予。", "yin": "shén lái zhī bǐ"}, {"rank": 140, "idiom": "惟妙惟肖", "pinyin": "wéi miào wéi xiào", "origin": "宋·岳珂《桯史·連署本紀》", "story": "岳珂評仿造古書名人墨寶之逼真絕技，稱臨摹名手技法通神，一筆一墨、起承轉合，『字畫神韻，惟妙惟肖，雖米芾亦莫能辨其真偽』。逼真神態宛如原本再現。", "quote": "刻劃入微，惟妙惟肖，令人幾莫能辨真偽。", "desc": "形容描摹、表演或雕刻得非常逼真生動，與原型毫無二致。", "yin": "wéi miào wéi xiào"}, {"rank": 139, "idiom": "栩栩如生", "pinyin": "xǔ xǔ rú shēng", "origin": "《莊子·齊物論》引申/清·吳趼人《二十年目睹之怪現狀》", "story": "《莊子》曰：昔者莊周夢為胡蝶，栩栩然胡蝶也。栩栩，展翅輕快飛翔之貌。後世因形容畫家筆下人物草木禽鳥生動逼真，如同真有生命一般在眼前鮮活活動。", "quote": "畫工精絕，描摹人物栩栩如生，如欲從壁上走下。", "desc": "形容藝術形象、人物肖像生動逼真，如同活人活物一樣。", "yin": "xǔ xǔ rú shēng"}, {"rank": 138, "idiom": "活靈活現", "pinyin": "huó líng huó xiàn", "origin": "明·馮夢龍《警世通言·卷五》", "story": "馮夢龍小說敘述市井故事人物言語，神態畢露情致生動：『說起那日情景，手舞足蹈，活靈活現，正如在人眼前一般！』如同仙靈幻化顯現，真實親切。", "quote": "描摹神態，活靈活現，令人如歷其境。", "desc": "形容描述或扮演得極其逼真逼真，如同真實景物呈現在眼前。", "yin": "huó líng huó xiàn"}, {"rank": 137, "idiom": "呼之欲出", "pinyin": "hū zhī yù chū", "origin": "宋·蘇軾《王維吳道子畫》", "story": "蘇軾詩評唐代畫聖吳道子與大詩人王維壁畫人物曰：『道子畫人物，如翻水成浪，初不費力；摩詰畫詩意，清空淡雅。二公筆墨，人物眉宇顧盼，宛然呼之欲出！』彷彿只要開口一喊，畫中之人就會走出來。", "quote": "賦詩寫景，人物神情呼之欲出，妙絕古今。", "desc": "形容畫像或小說人物刻畫極其生動傳神，彷彿一叫就會走出來一樣。", "yin": "hū zhī yù chū"}, {"rank": 136, "idiom": "躍然紙上", "pinyin": "yuè rán zhǐ shàng", "origin": "清·薛雪《一瓢詩話》", "story": "薛雪論詩品之神采，稱絕頂好詩無需冗繁贅述，往往片言隻語即能將物性人情寫透，『喜怒哀樂，躍然紙上，神采照人』。活脫生動之神韻如同在紙面上騰躍而起。", "quote": "詩篇情致纏綿，幽怨感慨，躍然紙上。", "desc": "形容刻畫描摹生動活潑，生動的情態氣質鮮活地顯現於紙墨之間。", "yin": "yuè rán zhǐ shàng"}, {"rank": 135, "idiom": "意味深長", "pinyin": "yì wèi shēn zhǎng", "origin": "宋·程頤《二程全書》", "story": "宋代大儒程頤講論《論語》《中庸》聖人微言，教導門人細細咀嚼：『聖人之言，平實淡雅，而逐層體會，意味深長，終身受用不盡也！』言有盡而意無窮。", "quote": "讀聖賢之書，玩索其言，意味深長。", "desc": "形容言語文字所包含的內在意義意旨極其深刻，值得長久尋味體會。", "yin": "yì wèi shēn zhǎng"}, {"rank": 134, "idiom": "回味無窮", "pinyin": "huí wèi wú qióng", "origin": "宋·蘇軾《答武公玉書》", "story": "蘇軾在與友人論文章飲食之書簡中借品茗為喻：好的好茶或千古佳構，初嘗清淡沖融，咽後齒頰留香，『甘美微苦，回味無窮，令人久久不能忘懷』。", "quote": "佳作如品名茗，清香滿溢，回味無窮。", "desc": "比喻事物、講話或藝術佳作給人留下的美好感受深刻久遠，越回想越有味道。", "yin": "huí wèi wú qióng"}, {"rank": 133, "idiom": "耐人尋味", "pinyin": "nài rén xún wèi", "origin": "清·無名氏《杜詩言志》", "story": "清人評杜工部律詩，稱其晚年夔州諸作，格律沉雄，字字千錘百煉，『蒼涼沉鬱，耐人尋味，讀之千遍而不厭倦』。經得起讀者反覆探索品評回味。", "quote": "杜陵晚年詩筆，深厚沉雄，耐人尋味。", "desc": "形容事物或言語意味深長，引人仔細揣摩回味思考。", "yin": "nài rén xún wèi"}, {"rank": 132, "idiom": "語重心長", "pinyin": "yǔ zhòng xīn cháng", "origin": "清·洛陽湮沒妹《臨證指南醫案》/清代尺牘", "story": "前輩長者訓示子弟晚輩，往往心懷真誠關愛，談及治學立身之大道，辭句誠懇切實，分量沉重而寄望深遠，諄諄教誨引導後生走上正道。", "quote": "長者之教，語重心長，子弟當銘刻肺腑。", "desc": "形容言語懇切沉著，感情深厚，寄託著深遠的期望與關愛。", "yin": "yǔ zhòng xīn cháng"}, {"rank": 131, "idiom": "微言大義", "pinyin": "wēi yán dà yì", "origin": "漢·劉歆《移讓太常博士書》", "story": "劉歆力主列《左傳》於學官，移書太常博士曰：『昔孔子歿而微言絕，七十子卒而大義乖。重尋聖賢筆墨，以發皇幽隱，正此時矣！』精微精妙之微言片語之中，蘊含著推動天地治平之宏偉大義。", "quote": "昔孔子歿而微言絕，七十子卒而大義乖。", "desc": "指精微簡練的語言中包含著深奧博大的道理與義理。", "yin": "wēi yán dà yì"}, {"rank": 130, "idiom": "言簡意賅", "pinyin": "yán jiǎn yì gāi", "origin": "宋·張載《張子語錄》", "story": "張載論橫渠四句及治學要訣，稱真正的至道名言，文字篇幅必定簡約凝練，而其所包含的意旨哲理卻極其完備包羅萬象，不尚繁複枝蔓。", "quote": "聖人立言，言簡而意賅，無一字虛設。", "desc": "形容說話或寫文章言語非常簡練，而意思卻極其完備透徹。", "yin": "yán jiǎn yì gāi"}, {"rank": 129, "idiom": "開門見山", "pinyin": "kāi mén jiàn shān", "origin": "唐·嚴羽《滄浪詩話·詩評》", "story": "嚴羽論作詩起句之法曰：『太白發句，常如開門見山，一覽無餘，豪氣逼人！』如同推開大門迎面便見崇山峻嶺，下筆便直奔主題，絕不拖泥帶水迂迴繞圈。", "quote": "太白發句，常如開門見山，氣象萬千。", "desc": "比喻說話或寫作文章開頭就直截了當切入主題，不拐彎抹角。", "yin": "kāi mén jiàn shān"}, {"rank": 128, "idiom": "一針見血", "pinyin": "yī zhēn jiàn xuè", "origin": "《後漢書·郭玉傳》引申/晉代針灸名言", "story": "郭玉為漢代神醫，善針灸之術，察其脈絡穴位，引針刺之，一針見血而頑疾立除。後世因以比喻議論針砭時弊，一語道中癥結核心，直指問題最本質處。", "quote": "醫者針穴，一針見血；文者立論，切中癥結。", "desc": "比喻說話、寫作或批評極其簡練切中要害，一語道破根本本質。", "yin": "yī zhēn jiàn xuè"}, {"rank": 127, "idiom": "切中要害", "pinyin": "qiè zhòng yào hài", "origin": "《漢書·賈誼傳》", "story": "賈誼上《治安策》，痛陳大漢景帝時諸侯王尾大不掉、逾制僭越之患，力主『眾建諸侯而少其力』。其剖析天下危如累卵之大勢，句句切中王朝根本要害，文帝讀之深思動容。", "quote": "賈誼論天下形勢，條分縷析，切中要害。", "desc": "指言論批判或分析正中問題的致命關鍵與核心要害處。", "yin": "qiè zhòng yào hài"}, {"rank": 126, "idiom": "一語破的", "pinyin": "yī yǔ pò de", "origin": "唐·杜牧《樊川文集·論長安書》", "story": "的者，射箭所對準之靶心紅心也。杜牧議論政治得失，指出賢者進言當如善射者引滿發矢，利箭正中靶心紅的，毫無偏斜拖沓。", "quote": "君子論事，一語破的，發聾振聵。", "desc": "形容一句話就說中問題的最關鍵核心，如同利箭一箭射中箭靶中心。", "yin": "yī yǔ pò de"}, {"rank": 125, "idiom": "一語道破", "pinyin": "yī yǔ dào pò", "origin": "宋·釋道原《景德傳燈錄》", "story": "禪宗大師接引學僧，往往在學僧百思不得其解、迷茫徘徊之際，當頭棒喝或以一言揭示本心：『一語道破本來面目，令其當下桶底脫落，大徹大悟！』", "quote": "大師機鋒妙辨，一語道破天機。", "desc": "指一句話就揭穿了事情的真相底細或秘密關竅。", "yin": "yī yǔ dào pò"}, {"rank": 124, "idiom": "談笑風生", "pinyin": "tán xiào fēng shēng", "origin": "宋·辛棄疾《念奴嬌·賦梅》", "story": "辛棄疾詞贊英雄豪傑之瀟灑氣度：『追昔英雄，談笑風生，草木皆染春色！』臨大事大戰，談笑自若，風趣橫生，言談之間自然生出如沐春風般動人神采。", "quote": "席間高朋滿座，談笑風生，逸興遄飛。", "desc": "形容言談之間充滿歡聲笑語，風趣生動興致盎然。", "yin": "tán xiào fēng shēng"}, {"rank": 123, "idiom": "娓娓動聽", "pinyin": "wěi wěi dòng tīng", "origin": "清·曾國藩《曾國藩家書》", "story": "曾國藩在家書中告誡子弟待人接物說話之法，當言辭溫雅謙和，循序漸進陳說情理：『出言溫婉，娓娓動聽，使聽者心悅誠服，自無傲慢乖戾之氣。』", "quote": "講論故事，口角春風，娓娓動聽。", "desc": "形容說話談論生動流暢，辭趣動人，讓人聽了非常喜歡愉快。", "yin": "wěi wěi dòng tīng"}, {"rank": 122, "idiom": "舌戰群儒", "pinyin": "shé zhàn qún rú", "origin": "明·羅貫中《三國演義》第四十三回", "story": "曹操引百萬之眾南下，江東文臣皆主張降曹。諸葛亮奉劉備命使吳，於柴桑謁孫權。張昭、虞翻、步騭、薛綜、陸績、嚴畯、程德樞諸人引經據典詰難孔明。孔明從容抗辯，引春秋大義，條條駁斥其怯懦賣主之言，群儒面如土色，無言以對，終成孫劉抗曹赤壁之盟。", "quote": "孔明在柴桑舌戰群儒，名震江東。", "desc": "比喻一個人憑藉雄辯之口才與淵博學識，同眾多人進行激烈辯論並取得勝利。", "yin": "shé zhàn qún rú"}, {"rank": 121, "idiom": "妙語連珠", "pinyin": "miào yǔ lián zhū", "origin": "漢·司馬遷《史記·滑稽列傳》引申", "story": "東方朔、淳于髡等滑稽辯才，每遇君王詰難，談笑間巧譬善喻，妙語如珠串聯不絕，辭意兼備，既能匡正君非，又令滿堂皆歡。連珠者，如穿線之明珠歷歷落下。", "quote": "談論風生，妙語連珠，座中賓客皆傾倒傾服。", "desc": "形容巧妙風趣、精彩絕倫的話一句接著一句，滔滔不絕。", "yin": "miào yǔ lián zhū"}, {"rank": 120, "idiom": "口若懸河", "pinyin": "kǒu ruò xuán hé", "origin": "《晉書·郭象傳》", "story": "郭象字子玄，少有才理，好《莊》《老》，善清談。太尉王衍每歎服其才學辨悟曰：『聽象語，如懸河瀉水，注而不竭！』言語如高山瀑布傾瀉奔流，滔滔滾滾流暢無窮。", "quote": "王衍歎曰：聽郭子玄語，如懸河瀉水，注而不竭。", "desc": "形容能言善辯，說起話來像瀑布奔流一樣滔滔不絕、流利暢達。", "yin": "kǒu ruò xuán hé"}, {"rank": 119, "idiom": "滔滔不絕", "pinyin": "tāo tāo bù jué", "origin": "五代·王仁裕《開元天寶遺事·走馬引泉》", "story": "唐張九齡善談論，每與賓客辨析經史大義，才思如江海泉源噴薄而出：『議論滔滔，如江河水注，終日不絕。』極言其口才辨思雄健無礙。", "quote": "議論風發，滔滔不絕，滿座傾聽。", "desc": "形容話很多，說起話來如同波濤滾滾連續不斷。", "yin": "tāo tāo bù jué"}, {"rank": 118, "idiom": "娓娓而談", "pinyin": "wěi wěi ér tán", "origin": "宋·朱熹《朱子語類》／明清筆記引申", "story": "古今文士相聚夜話，談起平生行跡見聞，心態從容舒展，語氣親切溫和，娓娓道來長談不休，令人心曠神怡忘卻俗世塵憂。", "quote": "長夜圍爐，娓娓而談，意趣盎然。", "desc": "形容連續不倦、從容舒緩且生動地談論事情。", "yin": "wěi wěi ér tán"}, {"rank": 117, "idiom": "侃侃而談", "pinyin": "kǎn kǎn ér tán", "origin": "《論語·鄉黨》", "story": "朝，與下大夫言，侃侃如也；與上大夫言，誾誾如也。君在，踧踖如也，與與如也。孔子在朝廷議政，與同級大夫談論，剛直而從容不迫，神色安詳舒泰，盡顯君子風範。", "quote": "朝與下大夫言，侃侃如也；與上大夫言，誾誾如也。", "desc": "形容說話理直氣壯、從容不迫、神色自若之談論神態。", "yin": "kǎn kǎn ér tán"}, {"rank": 116, "idiom": "理直氣壯", "pinyin": "lǐ zhí qì zhuàng", "origin": "明·馮夢龍《醒世恆言·卷三十五》", "story": "馮夢龍小說論公道民心曰：『為人只要行得正、立得直，事事順天理合國法，臨事自然理直而氣壯，何懼小人流言蜚語！』理由正當充分，底氣精神自然無比強大。", "quote": "自古公道在人心，理直則氣壯，何所忌憚！", "desc": "指理由充分正當，說話做事充滿底氣、剛正有力。", "yin": "lǐ zhí qì zhuàng"}, {"rank": 115, "idiom": "慷慨陳詞", "pinyin": "kāng kǎi chén cí", "origin": "漢·司馬遷《史記·平原君虞卿列傳》引申", "story": "毛遂按劍登階，當面指斥楚王利害關係，歷數楚國歃血大恥，聲音豪邁激越：『白起小豎子耳，拔郢燒夷陵，楚人之百世之仇也！今合從為楚，非為趙也！』慷慨激烈，楚王汗流浹背，立受合從誓約。", "quote": "毛遂按劍登殿，慷慨陳詞，楚王乃定合從之盟。", "desc": "形容情緒激動悲壯、意氣昂揚地陳述觀點意見或發表演說。", "yin": "kāng kǎi chén cí"}, {"rank": 114, "idiom": "據理力爭", "pinyin": "jù lǐ lì zhēng", "origin": "《明史·宋濂傳》", "story": "宋濂為明代開國文臣之首，太祖朱元璋性猜暴多誅戮大臣，宋濂每侍側，見冤枉無辜之人，必依據國法綱紀與天理良知，竭力在御前辯爭力諫，救全善士甚多。", "quote": "宋濂性淳良，臨事據理力爭，帝雖怒，終多優容從之。", "desc": "指依據正確正當的道理理由，竭盡全力進行爭辯反駁以爭取公正。", "yin": "jù lǐ lì zhēng"}, {"rank": 113, "idiom": "各抒己見", "pinyin": "gè shū jǐ jiàn", "origin": "唐·韓愈《進學解》引申", "story": "士人研討學術與國家大計，不應苟同逢迎，當使朝野博學通達之人，人人各展胸懷抱負，各自充分發表表達自己的獨立見解與觀點。", "quote": "群賢畢集，各抒己見，暢論天下大治之策。", "desc": "指每個人都充分發表表達出自己的意見與獨立看法。", "yin": "gè shū jǐ jiàn"}, {"rank": 112, "idiom": "暢所欲言", "pinyin": "chàng suǒ yù yán", "origin": "清·李寶嘉《官場現形記》", "story": "會議政務商略之際，主持長官開誠布公，解嚴防疑，鼓勵與會僚屬拋開一切顧忌憂慮，毫無保留地將心中所想徹底全部表達陳述出來。", "quote": "今日集議，諸君但請暢所欲言，切勿隱諱。", "desc": "指痛痛快快、毫無保留顧忌地把心裡想說的話全都說出來。", "yin": "chàng suǒ yù yán"}, {"rank": 111, "idiom": "智圓行方", "pinyin": "zhì yuán xíng fāng", "origin": "《淮南子·主術訓》", "story": "智圓者，通權達變智慮圓通如天也；行方者，立身方正恪守操守如地也。《淮南子》論人主與君子之德曰：『何謂智圓行方？智圓者無不知也，行方者有不為也。』思想通達圓活，行為端正守節。", "quote": "智圓者無不知也，行方者有不為也。智圓行方，聖人之治也。", "desc": "形容知識智慧圓通靈活、融會貫通，行為操守端正方直、恪守原則。", "yin": "zhì yuán xíng fāng"}, {"rank": 110, "idiom": "剛柔並濟", "pinyin": "gāng róu bìng jì", "origin": "《周易·繫辭上》", "story": "《易》曰：『剛柔相摩，八卦相盪。一陰一陽之謂道。』立天之道曰陰與陽，立地之道曰柔與剛，立人之道曰仁與義。治國掌兵修身，既有剛強決斷之骨氣，又兼備溫厚包容之仁和，方稱完備大德。", "quote": "剛柔相摩，相濟為用，此乾坤大德也。", "desc": "指剛強與柔和相互配合補充、折衝兼備以取得最佳平衡效果。", "yin": "gāng róu bìng jì"}, {"rank": 109, "idiom": "外圓內方", "pinyin": "wài yuán nèi fāng", "origin": "《後漢書·郅惲傳》", "story": "郅惲論漢初張良之大智大勇曰：『子房處衰漢之世，內懷忠方之志，外順圓通之機，故能身退而令名全也。』外表隨和圓通順應世事，內心則始終堅定剛正方方正正、嚴守原則底線。", "quote": "內懷忠方之節，外示圓通之容，外圓內方，保身成名。", "desc": "形容為人處事表面隨和圓滑通融，內心卻極有原則、方正剛毅。", "yin": "wài yuán nèi fāng"}, {"rank": 108, "idiom": "虛懷若谷", "pinyin": "xū huái ruò gǔ", "origin": "《老子·第十五章》", "story": "古之善為道者，微妙玄通，深不可識。豫焉若冬涉川，猶焉若畏四鄰，儼焉其若客，渙焉其若冰之將釋，敦兮其若樸，曠兮其若谷，混兮其若濁。老子以此盛讚君子胸懷極端謙遜空闊，如同深邃山谷般接納萬物。", "quote": "敦兮其若樸，曠兮其若谷。", "desc": "形容心胸無比謙遜寬廣，像深山幽谷一樣虛空博大、能容納一切善言批評。", "yin": "xū huái ruò gǔ"}, {"rank": 107, "idiom": "戒驕戒躁", "pinyin": "jiè jiāo jiè zào", "origin": "《尚書·大禹謨》引申", "story": "大禹訓誡后稷、皋陶曰：『汝惟不矜，天下莫與汝爭能；汝惟不伐，天下莫與汝爭功。』君子立於盛名大功之巔，最忌驕縱自傲急躁妄動，必當時刻警惕戒慎，自抑驕矜躁進之心。", "quote": "克勤克儉，戒驕戒躁，虛懷保和，長亨遐福。", "desc": "警惕戒除傲慢驕矜的自滿情緒與急躁冒進的不良毛病。", "yin": "jiè jiāo jiè zào"}, {"rank": 106, "idiom": "謙虛謹慎", "pinyin": "qiān xū jǐn shèn", "origin": "《周易·謙卦》引申", "story": "謙尊而光，卑而不可踰，君子之終也。《周易》六十四卦中唯謙卦六爻皆吉。天地鬼神皆虧盈而益謙，為人處世唯有時刻保持謙遜虛懷、戒慎恐懼，始能安享終生吉福。", "quote": "謙謙君子，尊而光輝。虛以待物，慎終如始。", "desc": "形容虛心謙退、處事周全慎重，毫不驕傲自滿狂妄自大。", "yin": "qiān xū jǐn shèn"}, {"rank": 105, "idiom": "謙謙君子", "pinyin": "qiān qiān jūn zǐ", "origin": "《周易·謙卦·初六》", "story": "初六：謙謙君子，用涉大川，吉。象曰：謙謙君子，卑以自牧也。真正品行高潔之君子，自處卑下以謙遜自我約束陶冶，以退為進，縱使涉歷天下滔滔大川巨浪，亦能逢凶化吉化險為夷。", "quote": "初六：謙謙君子，用涉大川，吉。象曰：謙謙君子，卑以自牧也。", "desc": "指謙虛謹慎、品德端正、舉止溫文儒雅的高尚之人。", "yin": "qiān qiān jūn zǐ"}, {"rank": 104, "idiom": "溫潤如玉", "pinyin": "wēn rùn rú yù", "origin": "《禮記·聘義》", "story": "子貢問於孔子曰：『敢問君子貴玉而賤玟者何也？為其少而玟者多與？』孔子曰：『非為玟之多故賤之也、玉之寡故貴之也。夫昔者君子比德於玉焉：溫潤而澤，仁也；縝密以慄，知也；廉而不噦，義也。』玉石溫和柔潤而有光澤，象徵君子溫仁之無上德行。", "quote": "夫昔者君子比德於玉焉：溫潤而澤，仁也。", "desc": "形容人的性情溫和敦厚、姿態文雅美好，如同光澤滋潤的美玉一般。", "yin": "wēn rùn rú yù"}, {"rank": 103, "idiom": "冰清玉潔", "pinyin": "bīng qīng yù jié", "origin": "漢·司馬遷《與摯伯陵書》", "story": "司馬遷在書簡中稱讚友人伯陵之操守德性：『僕聞君子行己立身，處亂世而抱孤節，冰清玉潔，未嘗染世俗一絲纖塵！』如純潔寒冰般晶瑩透徹，如高尚白玉般純潔無瑕。", "quote": "先生抗節幽棲，冰清玉潔，海內景行。", "desc": "形容品行極其純潔高尚，操守光明磊落毫不受外界染汙。", "yin": "bīng qīng yù jié"}, {"rank": 102, "idiom": "潔身自好", "pinyin": "jié shēn zì hǎo", "origin": "《孟子·萬章上》", "story": "萬章問曰：『伊尹以割烹要湯，有諸？』孟子曰：『否，不然！伊尹耕於有莘之野，而樂堯舜之道焉。湯三使往聘之，既而幡然改曰：與其使吾身為堯舜之民，何若使吾君為堯舜之君！歸潔其身，非其道也，非其義也，一介不以與人，一介不以取諸人。』君子保持自身純潔高尚，絕不與不義之流同流合汙。", "quote": "湯三使往聘之，伊尹乃起。歸潔其身，不與非義同汙。", "desc": "指保持自身的純潔清白，愛惜自身的名譽，不與世俗惡勢力同流合汙。", "yin": "jié shēn zì hǎo"}, {"rank": 101, "idiom": "克己復禮", "pinyin": "kè jǐ fù lǐ", "origin": "《論語·顏淵》", "story": "顏淵問仁。子曰：『克己復禮為仁。一日克己復禮，天下歸仁焉。為仁由己，而由人乎哉？』顏淵曰：『請問其目。』子曰：『非禮勿視，非禮勿聽，非禮勿言，非禮勿動。』剋制自身的私慾偏狹，使言語行動全面回歸天理規範制度，乃成就仁德王道之最高樞紐。", "quote": "子曰：克己復禮為仁。一日克己復禮，天下歸仁焉。", "desc": "約束剋制自己的私心私慾，使言行舉止完全符合道德禮制規範。", "yin": "kè jǐ fù lǐ"}, {"rank": 100, "idiom": "天下為公", "pinyin": "tiān xià wèi gōng", "origin": "《禮記·禮運》", "story": "大道之行也，天下為公。選賢與能，講信修睦。故人不獨親其親，不獨子其子，使老有所終，壯有所用，幼有所長，矜寡孤獨廢疾者皆有所養。孔子描繪天下大同之極致理想，天下社稷非一家一姓之私產，乃普天下億萬萬百姓共享之天下。", "quote": "大道之行也，天下為公。選賢與能，講信修睦。", "desc": "指天下政權與社稷乃天下百姓所共有公治，非一人一家之私物私利。", "yin": "tiān xià wèi gōng"}, {"rank": 99, "idiom": "兼愛非攻", "pinyin": "jiān ài fēi gōng", "origin": "《墨子·兼愛》《墨子·非攻》", "story": "墨子論天下大亂之源在於不相愛：『諸侯不相愛則必野戰，家主不相愛則必相篡，人與人不相愛則必相賊。故視人之國若視其國，視人之家若視其家，視人之身若視其身。兼相愛，交相利，天下自安。』力斥諸侯不義兼併之攻戰，主張平等博愛與制止侵略。", "quote": "天下兼相愛則治，交相惡則亂。兼愛非攻，墨子之至教也。", "desc": "墨家核心思想，主張博愛天下所有人，反對一切不義的掠奪攻伐侵略戰爭。", "yin": "jiān ài fēi gōng"}, {"rank": 98, "idiom": "民貴君輕", "pinyin": "mín guì jūn qīng", "origin": "《孟子·盡心下》", "story": "孟子曰：『民為貴，社稷次之，君為輕。是故得乎丘民而為天子，得乎天子為諸侯，得乎諸侯為大夫。諸侯危社稷，則變置；犧牲既成，粢盛既潔，祭祀以時，然而旱乾水溢，則變置社稷。』孟子提出石破天驚之民本思想，以萬民福祉為天下最高主體。", "quote": "民為貴，社稷次之，君為輕。", "desc": "孟子核心民本政治哲學，指出百姓利益最為尊貴，江山社稷次之，君主個人最輕。", "yin": "mín guì jūn qīng"}, {"rank": 97, "idiom": "仁民愛物", "pinyin": "rén mín ài wù", "origin": "《孟子·盡心上》", "story": "孟子曰：『君子之於物也，愛之而弗仁；於民也，仁之而弗親。親親而仁民，仁民而愛物。』儒家推己及人之仁愛由近及遠：先孝悌親愛家庭父母，次則仁厚慈愛四海黎庶百姓，進而泛愛天地間山林川澤禽鳥草木一切生靈。", "quote": "親親而仁民，仁民而愛物。", "desc": "指對黎民百姓施以仁德愛護，對天地萬物自然生靈充滿憐惜珍愛。", "yin": "rén mín ài wù"}, {"rank": 96, "idiom": "經世致用", "pinyin": "jīng shì zhì yòng", "origin": "清·顧炎武《亭林文集》/明清經學實學", "story": "明末清初顧炎武、黃宗羲痛感晚明士人空談心性王學以致神州陸沉之痛，力倡實學：『君子之為學也，非以誇多鬥靡，必有關於民生利病、天下安危之實，此之謂經世致用！』讀書論學務求切合治理世道、經緯天地之實用實效。", "quote": "君子之為學，凡以經世致用，利國安民而已。", "desc": "指學問必須切合治理天下國家、造福社會民生的實際需要，反對空談空論。", "yin": "jīng shì zhì yòng"}, {"rank": 95, "idiom": "修身齊家", "pinyin": "xiū shēn qí jiā", "origin": "《禮記·大學》", "story": "古之慾明明德於天下者，先治其國；欲治其國者，先齊其家；欲齊其家者，先修其身。身修而後家齊，家齊而後國治，國治而後天下平。自天子以至於庶人，壹是皆以修身為本。", "quote": "身修而後家齊，家齊而後國治，國治而後天下平。", "desc": "儒家實踐路徑，指首先提升端正個人品德修養，進而整頓管理好家庭宗族。", "yin": "xiū shēn qí jiā"}, {"rank": 94, "idiom": "格物致知", "pinyin": "gé wù zhì zhī", "origin": "《禮記·大學》", "story": "《大學》曰：『欲誠其意者，先致其知；致知在格物。物格而後知至。』格者，窮究推究也；物者，天地萬事萬物之理也。窮究客觀事物之深刻規律本質，使自心真知豁然貫通至極。", "quote": "致知在格物，物格而後知至，知至而後意誠。", "desc": "指窮究推究客觀事物的規律道理，從而全面獲得深厚廣大的真知灼見。", "yin": "gé wù zhì zhī"}, {"rank": 93, "idiom": "慎終追遠", "pinyin": "shèn zhōng zhuī yuǎn", "origin": "《論語·學而》", "story": "曾子曰：『慎終追遠，民德歸厚矣。』慎終者，對長輩之喪葬終事以至誠至禮慎重辦理也；追遠者，對遠代祖先與歷代聖賢定期虔誠追思祭祀也。上行下效，世俗百姓之道德風尚自然回歸淳厚篤實。", "quote": "曾子曰：慎終追遠，民德歸厚矣。", "desc": "指慎重辦理長輩喪事，虔誠緬懷追思遠祖先哲，使民風道德淳厚純良。", "yin": "shèn zhōng zhuī yuǎn"}, {"rank": 92, "idiom": "殫精竭慮", "pinyin": "dān jīng jié lǜ", "origin": "唐·白居易《策林一·策頭》", "story": "白居易為諫官，作《策林》七十五篇獻於憲宗，自述撰策之苦心曰：『殫精竭慮，討尋源委，思有以匡輔聖朝，補察袞職！』竭盡全部精神氣力，窮盡所有思慮思維，誓為天下民生竭誠效命。", "quote": "殫精竭慮，旁求博訪，以求天下之大治。", "desc": "形容用盡所有精力和思慮，竭盡全力思考與工作。", "yin": "dān jīng jié lǜ"}, {"rank": 91, "idiom": "夙夜匪懈", "pinyin": "sù yè fěi xiè", "origin": "《詩經·大雅·烝民》", "story": "天生烝民，有物有則。民之秉彝，好是懿德。仲山甫徂齊，式遄其行。肅肅王命，仲山甫將之。邦國若否，仲山甫明之。既明且哲，以保其身。夙夜匪懈，以事一人！周室賢相輔弼天子，自清晨至深夜從不懈怠怠惰。", "quote": "既明且哲，以保其身。夙夜匪懈，以事一人。", "desc": "形容從早到晚勤奮工作，毫不懈怠偷懶。", "yin": "sù yè fěi xiè"}, {"rank": 90, "idiom": "宵衣旰食", "pinyin": "xiāo yī gàn shí", "origin": "《南齊書·高帝紀下》", "story": "南齊高帝蕭道成即位，躬勤庶政。詔書曰：『日理萬機，宵衣旰食，深念天下之未寧，萬姓之未泰！』天未破曉便穿衣起床視朝，天已昏黑夜深尚未顧得吃晚飯，極言帝王賢相勤政為民之操勞。", "quote": "日理萬幾，宵衣旰食，勤恤民隱。", "desc": "形容為國家政務或事業極其勤勉勞苦，早起晚睡勤於公事。", "yin": "xiāo yī gàn shí"}, {"rank": 89, "idiom": "死而後已", "pinyin": "sǐ ér hòu yǐ", "origin": "《論語·泰伯》/三國蜀·諸葛亮《後出師表》", "story": "曾子曰：仁以為己任，不亦重乎？死而後已，不亦遠乎！孔明更在《後出師表》中立誓：臣鞠躬盡瘁，死而後已！為道義職守拼搏奮戰至生命完全熄滅停止方告終結，浩氣凜然。", "quote": "鞠躬盡瘁，死而後已。至於成敗利鈍，非臣之明所能逆睹也。", "desc": "形容為崇高事業或職責奮鬥努力，一直堅持到底，直到生命的終結。", "yin": "sǐ ér hòu yǐ"}, {"rank": 88, "idiom": "大公無私", "pinyin": "dà gōng wú sī", "origin": "《管子·形勢解》", "story": "風雨無私，故能普潤天地；霜雪無偏，故能齊正萬物。《管子》論人主治理天下曰：『天公平而無私，故美惡莫不覆；地公平而無私，故小大莫不載。大公無私者，天下之表範也。』唯有秉持至大至公，毫無半點偏袒私心，始得萬民臣服。", "quote": "風雨無私，故能普潤萬物；大公無私，故能平治天下。", "desc": "形容秉持至公純粹之大道，毫無半點私心偏袒與自私考量。", "yin": "dà gōng wú sī"}, {"rank": 87, "idiom": "鐵面無私", "pinyin": "tiě miàn wú sī", "origin": "清·石玉昆《三俠五義·包公》/元代戲曲", "story": "宋代龍圖閣直學士包拯知開封府，為官嚴毅剛正，關節不到，童稚婦孺皆知包青天之名。面對皇親國戚、權臣豪右犯法，一律依大宋律例鐵面按勘，絕不徇半點私情，世稱鐵面無私包龍圖。", "quote": "包公立朝剛毅，鐵面無私，雖貴戚宦官，莫不震懾。", "desc": "形容公正嚴明，不畏強暴權貴，絲毫不講私情偏袒。", "yin": "tiě miàn wú sī"}, {"rank": 86, "idiom": "廉潔奉公", "pinyin": "lián jié fèng gōng", "origin": "《晏子春秋·問下》", "story": "景公問晏子曰：『廉政而長久，其行何先？』晏子對曰：『其行莫先於廉潔。廉者，政之本也。潔者，行之表也。廉潔以飭身，公道以奉職，則臣下肅服而天下泰平矣。』為官廉潔乾淨，恪奉公道法令。", "quote": "廉潔以飭身，公道以行職，廉潔奉公，治道之綱維也。", "desc": "指為人做官清正廉潔，一心一意克己奉公，不貪圖私利。", "yin": "lián jié fèng gōng"}, {"rank": 85, "idiom": "兩袖清風", "pinyin": "liǎng xiù qīng fēng", "origin": "明·于謙《入京詩》", "story": "明於謙為巡撫，回京入朝奏事，僚屬勸其攜帶江南絹帕、香菇、名茶等土產饋送朝中權貴王振。于謙朗聲大笑，作詩以示眾人：『絹帕蘑菇與線香，本資民用反為殃。清風兩袖朝天去，免得閭閻話短長！』除兩袖清風外別無長物，光明磊落入朝。", "quote": "清風兩袖朝天去，免得閭閻話短長！", "desc": "比喻做官清廉正直，居官一塵不染，除兩隻衣袖滿裝清風外毫無私財。", "yin": "liǎng xiù qīng fēng"}, {"rank": 84, "idiom": "冰壺秋月", "pinyin": "bīng hú qiū yuè", "origin": "宋·蘇軾《贈潘谷》/唐·鮑溶《暮春即事》", "story": "盛唐鮑溶詩讚高士心志：『清凝冰壺滿，朗朗秋月明。』蘇軾亦贊製墨名家潘谷人品：『布衣草屨，神情皎然如冰壺秋月。』冰盛玉壺晶瑩無瑕，中秋明月高懸長空朗照乾坤，極言人格道德之無瑕純潔。", "quote": "其神情瀟灑，襟懷坦白，如冰壺秋月，無一絲塵俗之累。", "desc": "比喻品德冰清玉潔、高尚純潔，心胸品格如秋月般光明磊落。", "yin": "bīng hú qiū yuè"}, {"rank": 83, "idiom": "光風霽月", "pinyin": "guāng fēng jì yuè", "origin": "宋·黃庭堅《豫章黃先生文集·濂溪詩序》", "story": "黃庭堅盛讚宋代理學開山宗師周敦頤的人品德操曰：『舂陵周茂叔，人品甚高，胸懷灑落，如光風霽月。短於薄利，長於治民，卓然成一代宗師！』雨過天晴後的和煦陽光與清風明月，象徵心地開朗光明無比。", "quote": "舂陵周茂叔，人品甚高，胸懷灑落，如光風霽月。", "desc": "比喻雨過天晴時的和風明月，形容人品格崇高高尚、胸懷灑落坦白。", "yin": "guāng fēng jì yuè"}, {"rank": 82, "idiom": "浩然之氣", "pinyin": "hào rán zhī qì", "origin": "《孟子·公孫醜上》", "story": "公孫醜問孟子曰：『敢問夫子惡乎長？』孟子曰：『我知言，我善養吾浩然之氣。』醜問：『敢問何謂浩然之氣？』曰：『難言也。其為氣也，至大至剛，以直養而無害，則塞於天地之間。其為氣也，配義與道；無是，餒也。是集義所生者，非義襲而取之也。』充塞天地剛正不屈之正氣。", "quote": "其為氣也，至大至剛，以直養而無害，則塞於天地之間。", "desc": "指充塞天地之間正大剛直的崇高精神正氣與人格力量。", "yin": "hào rán zhī qì"}, {"rank": 81, "idiom": "富貴不淫", "pinyin": "fù guì bù yín", "origin": "《孟子·滕文公下》", "story": "景春曰：『公孫衍、張儀豈不誠大丈夫哉？一怒而諸侯懼，安居而天下熄。』孟子駁之曰：『是焉得為大丈夫乎！居天下之廣居，立天下之正位，行天下之大道。得志，與民由之；不得志，獨行其道。富貴不能淫，貧賤不能移，威武不能屈，此之謂大丈夫！』身處富貴之中而意志純粹不被迷亂放蕩。", "quote": "富貴不能淫，貧賤不能移，威武不能屈，此之謂大丈夫！", "desc": "指身居富貴高位，品行意志絕不被金錢榮華所迷亂放蕩。", "yin": "fù guì bù yín"}, {"rank": 80, "idiom": "貧賤不移", "pinyin": "pín jiàn bù yí", "origin": "《孟子·滕文公下》", "story": "孟子論頂天立地大丈夫人格，強調君子身處社會底層貧困艱難之境遇，衣不蔽體食不果腹，守道安貧之崇高志節與浩然操守終生絕不絲毫動搖改變。", "quote": "富貴不能淫，貧賤不能移，威武不能屈。", "desc": "指在貧困卑賤的極端困厄環境中，堅定的道德志節與信念絕不發生絲毫動搖。", "yin": "pín jiàn bù yí"}, {"rank": 79, "idiom": "威武不屈", "pinyin": "wēi wǔ bù qū", "origin": "《孟子·滕文公下》", "story": "大丈夫處世，面對強權暴君之屠刀利劍、權威武力之殘酷威逼恫嚇，昂首挺立視死如歸，浩然正氣直衝鬥牛，絕不低頭折節屈服臣服。", "quote": "富貴不能淫，貧賤不能移，威武不能屈，此之謂大丈夫！", "desc": "在強大的威勢、暴力威脅和生死恐嚇面前，堅決不屈服、不低頭。", "yin": "wēi wǔ bù qū"}, {"rank": 78, "idiom": "捨生取義", "pinyin": "shě shēng qǔ yì", "origin": "《孟子·告子上》", "story": "孟子曰：『魚，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍魚而取熊掌者也。生，亦我所欲也；義，亦我所欲也。二者不可得兼，捨生而取義者也。生亦我所欲，所欲有甚於生者，故不為苟得也；死亦我所惡，所惡有甚於死者，故患有所不闢也。』在肉體生命與天地正義衝突時，毅然捨棄生命保全正義。", "quote": "生，亦我所欲也；義，亦我所欲也。二者不可得兼，捨生而取義者也。", "desc": "指為捍衛真理、正義或國家人民利益，甘願犧牲自己的寶貴生命。", "yin": "shě shēng qǔ yì"}, {"rank": 77, "idiom": "視死如歸", "pinyin": "shì sǐ rú guī", "origin": "《韓非子·外儲說左下》/《呂氏春秋》", "story": "韓非子記戰陣勇士之死節：烈士明於大義，臨難赴水火，白刃交於前而視死若歸。歸者，回家安息也。以身殉道殉國，視獻出生命如踏上歸鄉之路一般從容無畏坦然平和。", "quote": "殺身有成，以義為準，臨難視死如歸，真壯士也。", "desc": "形容把死亡看得像回家一樣坦然，毫不畏懼死亡與犧牲。", "yin": "shì sǐ rú guī"}, {"rank": 76, "idiom": "臨危不懼", "pinyin": "lín wēi bù jù", "origin": "《莊子·秋水》", "story": "子路問夫子臨難之勇。孔子曰：『水行不避蛟龍者，漁父之勇也；陸行不避兕虎者，獵夫之勇也；白刃交於前，視死若生者，烈士之勇也；知窮之有命，知通之有時，臨大難而不懼者，聖人之勇也。』聖賢明悟天命，面臨滅頂之災難心態平靜安然，毫無恐懼畏怯。", "quote": "知窮之有命，知通之有時，臨大難而不懼者，聖人之勇也。", "desc": "形容面臨生死存亡的危急關頭，神態自若，毫無畏縮恐懼之色。", "yin": "lín wēi bù jù"}, {"rank": 75, "idiom": "義無反顧", "pinyin": "yì wú fǎn gù", "origin": "漢·司馬相如《喻巴蜀檄》", "story": "漢武帝遣司馬相如出撫西南夷，相如作檄告諭巴蜀軍民：『夫當道仁義，明是非，臨戰陣而忘其身，顧大義而拔其足。士卒赴節死義，義無反顧，雖赴湯蹈火，豈有回頭瞻望之理哉！』為了正義公理，毅然勇往直前絕不回頭顧望。", "quote": "士赴節死義，義無反顧，身雖隕歿，名垂竹帛。", "desc": "指在道義正義的指引下，勇往直前、堅定不移，決不回頭退縮。", "yin": "yì wú fǎn gù"}, {"rank": 74, "idiom": "勇往直前", "pinyin": "yǒng wǎng zhí qián", "origin": "宋·朱熹《朱子全書·道統》", "story": "朱子勉勵學者求索道德真理之功夫，當立定腳跟，破除疑懼：『既然明得此理真純，即當挺身擔當，勇往直前，拔山倒海，何事不可成！』毫無畏懼地一直向前奮進奮鬥。", "quote": "立志既定，當勇往直前，遇險不撓，終成弘毅之德。", "desc": "形容勇敢勇敢地一直向前邁進，不畏艱險，毫不畏縮顧慮。", "yin": "yǒng wǎng zhí qián"}, {"rank": 73, "idiom": "披荊斬棘", "pinyin": "pī jīng zhǎn jí", "origin": "《後漢書·馮異傳》", "story": "光武帝劉秀平定天下即位，引群臣論開國功勳。璽書勞大司馬馮異曰：『將軍為吾披荊棘，定關中，創業維艱，功冠諸將！』斬除密佈之野草荊棘，開拓出通衢大道，極言開闢事業之艱辛苦難。", "quote": "帝敕馮異曰：為吾披荊棘，定關中，歲月崢嶸，功不可沒。", "desc": "比喻掃除前進道路上的重重障礙與艱難險阻，奮勇開拓新局。", "yin": "pī jīng zhǎn jí"}, {"rank": 72, "idiom": "勇冠三軍", "pinyin": "yǒng guān sān jūn", "origin": "漢·司馬遷《史記·李將軍列傳》", "story": "太史公傳李廣之勇略，贊其騎射如神，引滿發石，度不中不發。臨戰衝鋒陷陣，萬馬叢中取敵首級，氣魄膽識冠絕全軍全師，匈奴望其旌旗避匿，號為漢之飛將軍。", "quote": "李廣才氣，天下無雙，勇冠三軍，威震漠北。", "desc": "形容英勇無敵，勇氣武藝在整個軍隊中高居第一位。", "yin": "yǒng guān sān jūn"}, {"rank": 71, "idiom": "志存高遠", "pinyin": "zhì cún gāo yuǎn", "origin": "晉·諸葛恪《誡子書》/蜀漢·諸葛亮《誡外甥書》", "story": "諸葛武侯《誡外甥書》開篇垂訓：『夫志當存高遠，慕先賢，絕情慾，棄凝滯，使庶幾之志揭然有所存，惻然有所感。』告誡後生晚輩立志必須超拔崇高宏大，以聖賢天下為己任，切勿沉湎凡俗凡庸小利。", "quote": "夫志當存高遠，慕先賢，絕情慾，棄凝滯。", "desc": "指立定崇高、遠大的抱負志向與理想追求。", "yin": "zhì cún gāo yuǎn"}, {"rank": 70, "idiom": "壯志凌雲", "pinyin": "zhuàng zhì líng yún", "origin": "《漢書·司馬相如傳上》", "story": "司馬相如作《大人賦》，武帝讀之飄飄有凌雲之氣，似有羽化登仙遊行四海之神意。班固贊才人豪士胸中抱負浩瀚，『壯志凌雲，籠蓋宇宙，氣吞八荒』。宏偉壯志高入雲霄霄漢。", "quote": "飄飄有凌雲之氣，似引八極而超眾類。", "desc": "形容宏偉崇高的志向直上雲霄，抱負無比遠大高尚。", "yin": "zhuàng zhì líng yún"}, {"rank": 69, "idiom": "氣吞山河", "pinyin": "qì tūn shān hé", "origin": "唐·張說《鄴都引》/宋·辛棄疾", "story": "張說詩詠魏武曹操之雄才大略：『君不見魏武草創爭天祿，氣吞山河鼓角震！』英雄豪傑拔劍四顧，吞吐宇宙，氣魄宏偉至極，足可席捲山川巨浪，震撼乾坤天下。", "quote": "君不見魏武草創爭天祿，氣吞山河四海肅！", "desc": "形容氣魄精神極其豪邁宏偉，氣勢足以吞沒山嶽江河。", "yin": "qì tūn shān hé"}, {"rank": 68, "idiom": "頂天立地", "pinyin": "dǐng tiān lì dì", "origin": "宋·釋普濟《五燈會元·卷五十六》", "story": "禪宗大德點撥學僧立身行道之骨氣：『堂堂大丈夫，當頂天立地，截斷凡聖名相，豈能隨人腳後轉！』頭頂蒼天，腳踏堅地，獨立不移，展現至剛至陽無愧天地之偉岸形象。", "quote": "堂堂男子，頂天立地，自當扶危濟困，力柱乾坤。", "desc": "形容形象高大雄偉、氣概豪邁剛直，有擔當作為的大英雄大豪傑。", "yin": "dǐng tiān lì dì"}, {"rank": 67, "idiom": "昂首闊步", "pinyin": "áng shǒu kuò bù", "origin": "唐·韓愈《祭鱷魚文》引申/清代小說", "story": "大丈夫心胸光明磊落，行得正坐得端，走起路來高高抬起頭顱，邁開豪邁大步向前邁進，神采飛揚，充滿自信與自尊之豪邁氣魄。", "quote": "抬頭挺胸，昂首闊步，豪情滿懷奔向坦途。", "desc": "抬起頭大步跨步向前走，形容精神抖擻、意氣風發、信心百倍的神采。", "yin": "áng shǒu kuò bù"}, {"rank": 66, "idiom": "意氣風發", "pinyin": "yì qì fēng fā", "origin": "宋·蘇軾《密州出獵》引申", "story": "老夫聊發少年狂，左牽黃，右擎蒼，錦帽貂裘，千騎卷平岡！蘇東坡密州射虎出獵，胸中豪情意氣如長風噴發奔湧而出，神采飛動，充滿青春豪放生命活力。", "quote": "意氣風發，少年豪傑，策馬笑傲江山。", "desc": "形容精神振奮，氣概豪邁，神采飛揚充滿幹勁與熱情。", "yin": "yì qì fēng fā"}, {"rank": 65, "idiom": "神采奕奕", "pinyin": "shén cǎi yì yì", "origin": "明·沈德符《野獲編·補遺》", "story": "沈德符記名臣大儒容貌儀態：『年雖古稀，而目光炯炯照人，面帶潤澤，神采奕奕，如神仙中人！』奕奕，光彩煥發生輝之貌，極言精神充沛、儀態非凡。", "quote": "面如冠玉，目光如電，神采奕奕，照映坐隅。", "desc": "形容精神旺盛飽滿，神情容貌煥發著燦爛容光光采。", "yin": "shén cǎi yì yì"}, {"rank": 64, "idiom": "精神抖擻", "pinyin": "jīng shén dǒu sǒu", "origin": "宋·釋道原《景德傳燈錄·卷十》", "story": "禪宗祖師登座說法，警醒昏沉大眾：『抖擻塵垢，振作精神，直下承當，更待何時！』抖擻者，甩掉疲倦振作精神奮起之謂也。振作抖擻，百倍精力投入修持奮戰。", "quote": "一聲號令，三軍將士精神抖擻，銳氣幹雲。", "desc": "形容精神振作充沛，充滿飽滿活力與旺盛生機。", "yin": "jīng shén dǒu sǒu"}, {"rank": 63, "idiom": "生龍活虎", "pinyin": "shēng lóng huó hǔ", "origin": "宋·朱熹《朱子語類·卷九十五》", "story": "朱熹品評孔門高足神態氣象曰：『子路子貢輩，精神充沛，見識敏銳，生龍活虎相似，毫無半分腐儒枯木死灰之態！』宛如活潑生動之神龍與猛虎，生氣勃發。", "quote": "青年英銳，生龍活虎，朝氣蓬勃，前途不可限量。", "desc": "形容生氣勃勃，活潑矯健，充滿無窮無盡的青春活力與生機。", "yin": "shēng lóng huó hǔ"}, {"rank": 62, "idiom": "生機勃勃", "pinyin": "shēng jī bó bó", "origin": "宋·周敦頤《太極圖說》引申", "story": "周濂溪茂叔觀窗前草色青青不除，問其故，曰：『與自家意思一般。』天地陰陽交泰，萬物萌發滋長，生意盎然充滿無限蓬勃旺盛之生命力氣象。", "quote": "大地春回，群卉競秀，山川原野一片生機勃勃。", "desc": "形容生命力極其旺盛，充滿活力熱情與蓬勃朝氣。", "yin": "shēng jī bó bó"}, {"rank": 61, "idiom": "欣欣向榮", "pinyin": "xīn xīn xiàng róng", "origin": "晉·陶淵明《歸去來兮辭》", "story": "陶潛辭官歸隱田園，春日漫步山林，舒展性靈：『木欣欣以向榮，泉涓涓而始流。善萬物之得時，感吾生之行休！』春木草樹欣喜逢時，迎著陽光爭相繁茂茂盛生長，大地一片繁榮景象。", "quote": "木欣欣以向榮，泉涓涓而始流。", "desc": "形容草木繁盛美麗，亦比喻事業蓬勃發展、繁榮興旺之朝氣景象。", "yin": "xīn xīn xiàng róng"}, {"rank": 60, "idiom": "蒸蒸日上", "pinyin": "zhēng zhēng rì shàng", "origin": "清·李寶嘉《官場現形記》", "story": "蒸蒸者，熱氣如水氣騰騰向上蒸騰上升也。比喻社會事業、經濟文化或學問進步，一天比一天繁榮興盛，節節拔高如旭日初昇。", "quote": "國運亨通，工商利達，社會民生蒸蒸日上。", "desc": "形容事業、生活或景況天天都在向上蓬勃發展進步。", "yin": "zhēng zhēng rì shàng"}, {"rank": 59, "idiom": "日新月異", "pinyin": "rì xīn yuè yì", "origin": "《禮記·大學》引申", "story": "湯之《盤銘》曰：『苟日新，日日新，又日新。』天道運行永不停息，君子德業日日更新、月月煥發異彩，文明演化突飛猛進，不斷湧現推陳出新之全新成果。", "quote": "苟日新，日日新，又日新。日新月異，與時俱進。", "desc": "形容進步發展極其迅速，每天每月都在發生深刻新奇的巨大變化。", "yin": "rì xīn yuè yì"}, {"rank": 58, "idiom": "萬象更新", "pinyin": "wàn xiàng gēng xīn", "origin": "清·曹雪芹《紅樓夢》/宋代新春賀辭", "story": "歲除迎春，大地解凍，冰雪消融。宇宙間一切事物景緻悉皆換上全新容顏面貌。家家戶戶貼春聯燃爆竹，乾坤氣象一新，萬物欣欣向榮展現新氣象。", "quote": "一元復始，萬象更新，大地回春，民康物阜。", "desc": "指天地宇宙間的一切事物、景象都改變了面貌，呈現出一番欣欣向榮的新氣象。", "yin": "wàn xiàng gēng xīn"}, {"rank": 57, "idiom": "百廢俱興", "pinyin": "bǎi fèi jù xìng", "origin": "宋·范仲淹《嶽陽樓記》", "story": "慶曆四年春，滕子京謫守巴陵郡。越明年，政通人和，百廢具興。乃重修嶽陽樓，增其舊制，刻唐賢今人詩賦於其上。原本荒廢廢置的一切社會公用事業與典章制度，在賢明長官治理下全面重新興辦振興。", "quote": "越明年，政通人和，百廢具興，乃重修嶽陽樓。", "desc": "指許多被廢置、荒廢已久的重大公私事業全部重新興辦振興起來。", "yin": "bǎi fèi jù xìng"}, {"rank": 56, "idiom": "太平盛世", "pinyin": "tài píng shèng shì", "origin": "《史記·平準書》引申/漢書", "story": "漢武帝盛世，文景之後天下殷富，京師之錢累巨萬，貫朽而不可校；太倉之粟陳陳相因，充溢露積於外。天下海晏河清，四境無徵戰流血之憂，百姓豐足安享昇平盛世。", "quote": "民安其業，海內昇平，稱天下為太平盛世。", "desc": "形容天下安定太平、繁榮富裕、國泰民安的繁榮昌盛時代。", "yin": "tài píng shèng shì"}, {"rank": 55, "idiom": "風調雨順", "pinyin": "fēng diào yǔ shùn", "origin": "《六韜·文韜》", "story": "太公望論政道之極致，稱至德聖明人主撫綏天下，順應陰陽五行之道，天人感應：『甘露時降，時風應律，風調雨順，五穀豐登，社稷大安！』風雨如期按節氣順適調和，滋潤良田。", "quote": "歲稔年豐，風調雨順，天下無飢餒之民。", "desc": "形容風雨及時順應節氣，氣候良好，有利於農作物繁茂生長與收成。", "yin": "fēng diào yǔ shùn"}, {"rank": 54, "idiom": "國泰民安", "pinyin": "guó tài mín ān", "origin": "《漢書·景帝紀贊》引申/宋代祥瑞讚文", "story": "國家政治清明，邊境安寧，府庫充盈，天下泰平穩固；萬民百姓安分守己，安居樂業衣食無憂，無賦役兵戈殘害之苦，此乃天下大治之最高象徵。", "quote": "四海昇平，國泰民安，政通人和，休養生息。", "desc": "國家安定泰平繁榮，人民安居樂業生活幸福祥和。", "yin": "guó tài mín ān"}, {"rank": 53, "idiom": "安居樂業", "pinyin": "ān jū lè yè", "origin": "《漢書·貨殖傳》/《老子·第八十章》", "story": "老子描繪小國寡民安適樂土：『甘其食，美其服，安其居，樂其俗。鄰國相望，雞犬之聲相聞，民至老死不相往來。』班固亦讚漢興六十載，百姓安享家園居室，樂於從事本業生產，家給人足。", "quote": "各安其居，各樂其業，海內宴然，民無疾苦。", "desc": "形容生活安定平靜，愉快歡喜地從事自己的職業與工作。", "yin": "ān jū lè yè"}, {"rank": 52, "idiom": "人壽年豐", "pinyin": "rén shòu nián fēng", "origin": "南朝梁·蕭統《文選序》", "story": "昭明太子蕭統序文選，追溯古先聖王大治之世：天降甘露，地出醴泉，四海歌詠，人倫康樂，『人獲享其遐壽，歲時慶其年豐，德澤潤被於海內蒼生』。人民健康長壽，歲月五穀大豐收。", "quote": "海晏河清，人壽年豐，共享昇平大業。", "desc": "形容社會安定，人民健康長壽，莊稼五穀豐收，生活極其富裕美滿。", "yin": "rén shòu nián fēng"}, {"rank": 51, "idiom": "豐衣足食", "pinyin": "fēng yī zú shí", "origin": "唐·白居易《贈友五首》", "story": "白居易關切農民生計，作詩詠田家至樂：『男勤耕於野，女勤織於室。歲暮倉箱盈，豐衣足食飽！』穿戴衣履豐厚溫暖，飲食糧食富足充足，擺脫飢寒困餒之苦，生活美滿。", "quote": "倉廩實而知禮節，衣食足而知榮辱。豐衣足食，萬民之大幸也。", "desc": "形容生活富裕充足，穿的吃的都十分豐富富足，毫無匱乏。", "yin": "fēng yī zú shí"}, {"rank": 50, "idiom": "康莊大道", "pinyin": "kāng zhuāng dà dào", "origin": "《史記·孟子荀卿列傳》", "story": "齊宣王盛開稷下學宮，喜文學遊說之士，自鄒衍、淳于髡、田駢、接予、慎到、環淵之徒七十六人，皆賜列第，為開第康莊之衢，高門大第，尊寵備至，開天下學者自由講論之廣闊大道。", "quote": "皆賜列第，為開第康莊之衢，高門大第，尊寵備至。", "desc": "比喻寬闊平坦的坦途大路，亦比喻光明美好、前途廣闊的事業方向。", "yin": "kāng zhuāng dà dào"}, {"rank": 49, "idiom": "海晏河清", "pinyin": "hǎi yàn hé qīng", "origin": "唐·鄭錫《日中有王字賦》", "story": "唐賦讚盛世祥瑞道化天下曰：『滄海無狂瀾之驚，黃河無濁浪之淤。海晏河清，四方賓服，象徵天下大治，風調雨順萬民康樂。』大海平靜波濤安息，黃河之水澄澈清純，千載盛世之瑞徵。", "quote": "海晏河清，天下太平，四方入貢，民康物阜。", "desc": "黃河水清、大海平靜，比喻天下昇平、國泰民安的清明時代。", "yin": "hǎi yàn hé qīng"}, {"rank": 48, "idiom": "歌舞昇平", "pinyin": "gē wǔ shēng píng", "origin": "宋·陸遊《歲暮感懷》", "story": "陸放翁撫古思今，作詩詠昇平盛世之景：『四海無徵戰之塵，萬家樂耕桑之業。月下聞笛，市井歌舞昇平，老人含哺而嬉。』到處笙歌嘹亮燕舞鶯歌，呈現一派太平祥和之景象。", "quote": "四海昇平，簫鼓喧天，萬家歌舞昇平。", "desc": "形容熱鬧歡樂、歌舞慶祝的昇平太平繁華景象。", "yin": "gē wǔ shēng píng"}, {"rank": 47, "idiom": "繁榮昌盛", "pinyin": "fán róng chāng shèng", "origin": "清·陳康祺《郎潛紀聞》", "story": "清人記康乾盛世景象：朝廷修典整飭百廢，海內民阜商盛，市肆百貨如山，農桑樂業。史臣贊其『國家繁榮昌盛，歷三朝百餘年之休養生息，氣象萬千』。", "quote": "政通人和，工商輻輳，國家繁榮昌盛，四方瞻仰。", "desc": "指國家或社會各項事業蒸蒸日上、極其繁榮興旺強盛。", "yin": "fán róng chāng shèng"}, {"rank": 46, "idiom": "萬古流芳", "pinyin": "wàn gǔ liú fāng", "origin": "《三國志·魏書·文帝紀》裴松之注引《魏略》", "story": "自古帝王忠臣義士立功立德立言於天下，其芳名美德如同芬芳芝蘭之馨香，歷經千萬年之滄桑風雨，依然在史冊青史中芬芳流傳，為百世萬代所崇敬瞻仰。", "quote": "殺身成仁，捨生取義，忠魂英烈，萬古流芳。", "desc": "形容高尚的美德品行、卓越的功績長久流傳於後世，永遠為人傳頌紀念。", "yin": "wàn gǔ liú fāng"}, {"rank": 45, "idiom": "名垂青史", "pinyin": "míng chuí qīng shǐ", "origin": "《三國志·蜀書·諸葛亮傳》引申", "story": "古者以竹簡編聯書寫史冊，以火炙烤青竹竹皮出汗去青，謂之殺青，故史書稱青史。忠臣烈士立不世之奇功，德澤庇蔭萬民，其英名刻寫於竹帛青簡之中，萬古留存不滅。", "quote": "立功立德，功冠天下，英名卓著，名垂青史。", "desc": "指傑出的功業功績與高尚名字永遠銘刻在歷史史冊之中，流芳千古。", "yin": "míng chuí qīng shǐ"}, {"rank": 44, "idiom": "彪炳史冊", "pinyin": "biāo bǐng shǐ cè", "origin": "唐·杜甫《蜀相》引申/《後漢書》", "story": "三顧頻煩天下計，兩朝開濟老臣心。諸葛孔明一死忠君復漢，英風烈烈，其耿耿精忠與隆中偉略光彩奪目、燦若星斗，永遠彪炳照耀於千載史冊之中。", "quote": "功業赫赫，光耀乾坤，彪炳史冊，萬古不磨。", "desc": "形容偉大的業績、卓越的貢獻燦爛耀眼，如日月星辰般光照史冊。", "yin": "biāo bǐng shǐ cè"}, {"rank": 43, "idiom": "永垂不朽", "pinyin": "yǒng chuí bù xiǔ", "origin": "《左傳·襄公二十四年》", "story": "穆叔如晉，範宣子問曰：『古人有言曰：死而不朽，何謂也？』穆叔對曰：『大上有立德，其次有立功，其次有立言。雖久不廢，此之謂不朽！』真正的偉大在於確立崇高品德、建立不朽功勳、創立永恆真理之言論，歷經萬劫永不腐朽。", "quote": "太上有立德，其次有立功，其次有立言。雖久不廢，此之謂不朽。", "desc": "指崇高光輝的事業、偉大思想或英烈人格永遠流傳在人間，永不磨滅。", "yin": "yǒng chuí bù xiǔ"}, {"rank": 42, "idiom": "歷久彌新", "pinyin": "lì jiǔ mí xīn", "origin": "《禮記·中庸》引申", "story": "《中庸》論大德大道之化機曰：『溫故而知新，敦厚以崇禮。動而世為天下道，行而世為天下法，言而世為天下則。』經典原典之真理，歷經千萬年歲月之淘洗考驗，不但未顯陳舊衰老，反而越發煥發出全新燦爛之生機與光彩。", "quote": "至理名言，經千年之洗禮，歷久彌新，光芒萬丈。", "desc": "指經歷長久時間的磨礪與考驗，反而越發顯得新穎精深、充滿活力。", "yin": "lì jiǔ mí xīn"}, {"rank": 41, "idiom": "經久不衰", "pinyin": "jīng jiǔ bù shuāi", "origin": "漢·班固《漢書·藝文志》", "story": "班固總攬六藝諸子百家書籍源流，稱孔孟六經之道貫通天人、切合倫常綱維，『放之四海而皆準，俟百世以俟聖人而不惑，經久而不衰矣』。歷經悠悠漫長歲月依然蓬勃興盛毫不衰落。", "quote": "先聖之典冊，立極天下，經久不衰，萬世宗仰。", "desc": "形容經歷長久的時間考驗，始終保持強大旺盛的生命力，毫不衰退敗落。", "yin": "jīng jiǔ bù shuāi"}, {"rank": 40, "idiom": "源遠流長", "pinyin": "yuán yuǎn liú zhǎng", "origin": "《荀子·富國》", "story": "荀子論富國足民之道曰：『源泉深者流長，根核固者條茂。明主必蓄積府庫，藏富於萬民，因以固其根基。』水源深遠充沛，水流自能滔滔奔流萬裡而不竭，比喻文化歷史根基極端深厚久遠。", "quote": "源泉深者其流長，根柢深者其條茂。源遠流長，沛莫能禦。", "desc": "形容源頭水源遙遠深厚，水流極長，比喻歷史文化、學統傳統極為悠久淵源深厚。", "yin": "yuán yuǎn liú zhǎng"}, {"rank": 39, "idiom": "博大精深", "pinyin": "bó dà jīng shēn", "origin": "《荀子·儒效》", "story": "荀子論先王之德道與大儒之學問曰：『聖人也者，道之管也。天下一眾也，莫不蒙其惠。夫道博大而精微，兼備天下萬物之理，深奧廣博不可窮盡也。』", "quote": "聖人之道，博大精微，兼備無外，精深莫測。", "desc": "形容思想理論、學術體系或文化藝術廣博宏大，內涵精奧精深。", "yin": "bó dà jīng shēn"}, {"rank": 38, "idiom": "汗牛充棟", "pinyin": "hàn niú chōng dòng", "origin": "唐·柳宗元《陸文通先生墓表》", "story": "柳宗元贊陸淳博通《春秋》之學，論歷代傳注之多曰：『自孔子歿，春秋之傳以百數。其為書也，處則充塞棟宇，出則牛馬汗流！』書籍浩瀚至極，藏於室內堆滿棟樑房梁，裝車運送累得耕牛大汗淋漓。", "quote": "其為書也，處則充塞棟宇，出則牛馬汗流。", "desc": "形容書籍宏富眾多，藏書極其豐富。", "yin": "hàn niú chōng dòng"}, {"rank": 37, "idiom": "浩如煙海", "pinyin": "hào rú yān hǎi", "origin": "宋·司馬光《資治通鑑·進書表》", "story": "司馬光歷時十九年編撰《資治通鑑》，上表奏稱自戰國迄五代凡一千三百六十二年間歷代正史野史雜傳筆記，『載籍浩如煙海，博奧難究。臣網羅研求，刪繁就簡，纂為通鑑』。書籍典冊浩渺如茫茫煙雲大海不可計數。", "quote": "古籍記載，浩如煙海，博索難終。", "desc": "形容典籍、文獻、資料極其廣博繁多，如煙雲大海般茫茫無際。", "yin": "hào rú yān hǎi"}, {"rank": 36, "idiom": "經天緯地", "pinyin": "jīng tiān wěi dì", "origin": "《左傳·昭公二十八年》", "story": "晉大夫魏舒掌國政，析論諡法曰：『經緯天地曰文，慈惠愛民曰元，柔克有德曰懿。』以天為經，以地為緯，經緯交織成天下乾坤法度，極言擘畫宇宙社稷之經綸大才。", "quote": "經緯天地曰文，經天緯地，定四海之宏規。", "desc": "形容人具有經綸天下、治理規劃整個國家世界的卓越雄才大略。", "yin": "jīng tiān wěi dì"}, {"rank": 35, "idiom": "棟樑之材", "pinyin": "dòng liáng zhī cái", "origin": "南朝宋·劉義慶《世說新語·賞譽》", "story": "晉庾亮評太傅諸葛恢、丞相王導等曰：『大廈將傾，非一木所能支，必得棟樑之材以共濟世變！』房屋最粗壯堅固承重之正樑與大柱，比喻能承擔國家天下重任的骨幹英才。", "quote": "棟樑之材，濟世之器，社稷之所依賴也。", "desc": "比喻能擔當國家重任或事業中流砥柱的傑出人才。", "yin": "dòng liáng zhī cái"}, {"rank": 34, "idiom": "風華正茂", "pinyin": "fēng huá zhèng mào", "origin": "《南齊書·謝朓傳》「風華」與唐·杜甫《飲中八仙歌》引申", "story": "南朝名士以「風華」譽才俊神采，後世合言「風華正茂」，形容青年英才正值青春鼎盛、風采才學如花繁茂之壯年時期。", "quote": "諸生皆一時俊彥，風華正茂，志行俱佳。", "desc": "形容青年人朝氣蓬勃、風采才華正值最為旺盛茂盛的時期。", "yin": "fēng huá zhèng mào"}, {"rank": 33, "idiom": "後生可畏", "pinyin": "hòu shēng kě wèi", "origin": "《論語·子罕》", "story": "子曰：『後生可畏，焉知來者之不如今也？四十、五十而無聞焉，斯亦不足畏也已。』孔子告誡世人不可輕視青年後進晚輩，年輕一代充滿無限成長潛力與創造力，未來成就往往超越前輩。", "quote": "子曰：後生可畏，焉知來者之不如今也？", "desc": "讚揚年輕一代潛力無窮，令人敬畏，將來成就極有可能超越前人。", "yin": "hòu shēng kě wèi"}, {"rank": 32, "idiom": "後起之秀", "pinyin": "hòu qǐ zhī xiù", "origin": "南朝宋·劉義慶《世說新語·賞譽》", "story": "王忱字元達，少有美譽。太原王恭盛稱讚王忱風神爽拔、才學卓越曰：『元達才地秀發，實後生之後起之秀也！』後輩中嶄露頭角、風華出眾的卓越英才。", "quote": "王恭稱王元達曰：自是後起之秀，才調超邁。", "desc": "指後來出現的、才華優異傑出的後輩年輕人才。", "yin": "hòu qǐ zhī xiù"}, {"rank": 31, "idiom": "伯樂相馬", "pinyin": "bó lè xiàng mǎ", "origin": "《韓非子·說林下》/《莊子·馬蹄》", "story": "孫陽號伯樂，精於識辨天下良馬。見鹽車之驥，骨瘦如柴，伏櫪哀鳴，伯樂撫其鬃而泣，解衣覆之，良馬長嘶昂首，直上九霄。韓非以伯樂相馬喻明君之善於審察識拔真正英才。", "quote": "伯樂善相馬，遇千里之足於市井槽櫪之中。", "desc": "比喻善於發現、識別並選拔各類隱沒的優秀人才。", "yin": "bó lè xiàng mǎ"}, {"rank": 30, "idiom": "班門弄斧", "pinyin": "bān mén nòng fǔ", "origin": "唐·柳宗元《王氏伯仲唱和詩序》/明·梅之渙《題李白墓》", "story": "公輸班（魯班）為天下第一巧匠木工祖師。採石磯李白墓前，遊人爭相留題劣詩，明梅之渙題詩笑之曰：『採石江邊一堆土，李白之名高千古。來來往往一首詩，魯班門前弄大斧！』在行家大宗師門前賣弄小本事。", "quote": "採石江邊一堆土，李白之名高千古。來來往往一首詩，魯班門前弄大斧！", "desc": "比喻在技藝精湛的行家面前盲目賣弄微不足道之拙劣技能，不自量力。", "yin": "bān mén nòng fǔ"}, {"rank": 29, "idiom": "樑上君子", "pinyin": "liáng shàng jūn zǐ", "origin": "《後漢書·陳寔傳》", "story": "陳寔在鄉閭，德高望重。歲荒，有盜夜入其室，止於樑上。寔陰見，乃呼子孫訓之曰：『夫人不可不自勉。不善之人未必本惡，習以成性，遂至於此，樑上君子者是矣！』盜大驚跳下叩頭請罪。寔贈之絹二匹，自此一縣無盜。", "quote": "寔呼子孫訓之曰：不善之人未必本惡，樑上君子是也。盜叩頭請死。", "desc": "原為陳寔委婉藉以教育盜賊之代名詞，後多作為竊賊、小偷的幽默雅稱。", "yin": "liáng shàng jūn zǐ"}, {"rank": 28, "idiom": "旁觀者清", "pinyin": "páng guān zhě qīng", "origin": "《舊唐書·元行沖傳》", "story": "唐元行沖撰《魏書》，為名儒類三史所非難。行沖作《釋疑》以自廣，引俗諺辨曰：『當局者迷，旁觀者清！棋客自矜其步，而席外觀者往往看得更明澈透底。』處在事件局外之人，心無私慾掛礙，看問題更清醒全面客觀。", "quote": "當局者迷，旁觀者清。席外觀棋，心無偏蔽，自審虛實。", "desc": "比喻身處局外不牽涉切身利益的人，對局勢是非往往比當事人看得更清楚客觀。", "yin": "páng guān zhě qīng"}, {"rank": 27, "idiom": "醉生夢死", "pinyin": "zuì shēng mèng sǐ", "origin": "宋·程顥《秋日偶成》", "story": "二程夫子論凡夫世俗不悟大道之態：『生不知其所自來，死不知其所自去。終日昏昏沉沉，如醉如夢，醉生夢死，豈不哀哉！』如醉酒昏沉般糊塗活著，像做夢一般恍惚死去。", "quote": "世人不知性命之本，終日狂馳，醉生夢死而已矣。", "desc": "形容像醉酒做夢一樣昏昏沉沉、渾渾噩噩地糊塗生活，無所追求目標。", "yin": "zuì shēng mèng sǐ"}, {"rank": 26, "idiom": "居高臨下", "pinyin": "jū gāo lín xià", "origin": "《淮南子·原道訓》", "story": "原道者，居高以臨下，因勢而順流。《淮南子》論天地萬物運轉之勢，處於崇山峻嶺險要高處，俯瞰掌控低平窪地，地勢佔據絕對制高點，其下衝之勢無堅不摧。", "quote": "居高臨下，勢如破竹，控引全局，莫敢攖其鋒。", "desc": "處在高處向下俯視俯瞰，比喻佔據了極其有利的優勢地位或形勢。", "yin": "jū gāo lín xià"}, {"rank": 25, "idiom": "撲朔迷離", "pinyin": "pū shuò mí lí", "origin": "北朝民歌《木蘭詩》", "story": "雄兔腳撲朔，雌兔眼迷離；雙兔傍地走，安能辨我是雄雌！木蘭替父從軍十二載，立奇功歸裡，換回女兒裝對鏡梳妝，軍中夥伴方駭然大悟。撲朔迷離，真假虛實交織難分。", "quote": "雄兔腳撲朔，雌兔眼迷離。雙兔傍地走，安能辨我是雄雌！", "desc": "形容事情錯綜複雜，真相撲朔難明，使人不易看清底細辨明真相。", "yin": "pū shuò mí lí"}, {"rank": 24, "idiom": "怨天尤人", "pinyin": "yuàn tiān yóu rén", "origin": "《論語·憲問》", "story": "子曰：『莫我知也夫！』子貢曰：『何為其莫知子也？』子曰：『不怨天，不尤人。下學而上達。知我者其天乎！』孔子身處困厄顛沛之際，從不埋怨上天命運不公，亦不責怪推諉他人不是，終生篤志下學上達求真求道。", "quote": "不怨天，不尤人。下學而上達，知我者其天乎！", "desc": "指遇到挫折挫敗時，一味抱怨天命不公、責備埋怨別人，不知自省。", "yin": "yuàn tiān yóu rén"}, {"rank": 23, "idiom": "隨遇而安", "pinyin": "suí yù ér ān", "origin": "宋·蘇軾《答李端叔書》", "story": "蘇軾一生屢遭貶謫黃州、惠州、儋州天涯海角，處逆境而怡然自適：『得生還海南，已萬幸矣。隨遇而安，無所往而不得其樂！』無論身處何等艱險險峻境地，皆能安然隨順順應境遇，保持心靈平靜超脫。", "quote": "居逆境而樂天知命，隨遇而安，浩氣長存。", "desc": "指能適應任何環境境遇，在各種艱苦或順遂處境下都能安心知足生活。", "yin": "suí yù ér ān"}, {"rank": 22, "idiom": "談虎色變", "pinyin": "tán hǔ sè biàn", "origin": "宋·程顥《二程全書》", "story": "程顥與門人談人性習氣曰：『真知與常知不同。如人曾被虎傷，他日行林莽，偶聞人言有虎，即面帶驚恐駭然失色。未嘗遭虎者聞之，神色自若。談虎而色變者，真知虎之暴烈也！』親歷大難者一觸舊事自然驚心動魄。", "quote": "嘗遭猛虎所噬者，他日聞談虎，輒面色大變。", "desc": "比喻曾經親身經歷過可怕禍患，只要一提及那件事就嚇得神情變色害怕。", "yin": "tán hǔ sè biàn"}, {"rank": 21, "idiom": "勢不兩立", "pinyin": "shì bù liǎng lì", "origin": "《史記·淮陰侯列傳》", "story": "蒯通說韓信自立天下曰：『楚漢相持，天下利害在將軍。項王死則漢王之害在將軍，此勢不兩立者也！』漢王與楚霸王互為生死強敵，敵對雙方形勢尖銳對立，水火不容絕無共同共存之可能。", "quote": "楚漢治兵，相爭天下，勢不兩立，勝者為王。", "desc": "形容敵對雙方矛盾極其尖銳激烈，水火不相容，絕不能並立共存。", "yin": "shì bù liǎng lì"}, {"rank": 20, "idiom": "唯利是圖", "pinyin": "wéi lì shì tú", "origin": "《左傳·成公十三年》", "story": "晉厲公使呂相絕秦檄書痛斥秦國背盟棄義：『秦非不信也，然其貪冒無厭，唯利是視，利之所在，雖兄弟親邦無不背棄也！』純粹以私利作為行事取捨之唯一標準，毫無半分道義規矩。", "quote": "秦人貪冒無信，唯利是視，蔑棄道義。", "desc": "形容極端自私貪婪，一心只圖謀個人私利，只要有利可圖便不擇手段。", "yin": "wéi lì shì tú"}, {"rank": 19, "idiom": "兩敗俱傷", "pinyin": "liǎng bài jù shāng", "origin": "《史記·張儀列傳》", "story": "張儀說楚懷王引二虎相爭寓言：莊蹻見二虎爭食一牛，將拔劍刺之，管莊子止之曰：『虎者肉食之暴獸，今爭一牛，其鬥必苦；鬥苦則小者死，大者傷。子待其傷而刺之，是一舉而得兩虎也！』若兩強相爭不肯退讓，必致雙方皆罹殘傷之慘禍。", "quote": "兩虎相鬥，必有一死一傷，是兩敗俱傷也。", "desc": "指雙方爭鬥相持不下，最後雙方都蒙受巨大損失，兩相俱受重創。", "yin": "liǎng bài jù shāng"}, {"rank": 18, "idiom": "貌合神離", "pinyin": "mào hé shén lí", "origin": "《素書·原始》", "story": "黃石公《素書》論用人之道曰：『夫同德同心，其利斷金；若貌合而神離者，雖共事必生猜阻，終致傾覆之禍！』表面上看來和睦融洽聚集在一起，然而各自內心思想抱負卻截然不同甚至互相排斥防範。", "quote": "貌合而神離，同床而異夢，大患之源也。", "desc": "形容表面上看起來十分親合融洽，實際上各懷心機，內在思想完全疏離背離。", "yin": "mào hé shén lí"}, {"rank": 17, "idiom": "破涕為笑", "pinyin": "pò tì wèi xiào", "origin": "宋·陸遊《歲夜書懷》", "story": "歲末除夕，放翁自詠老懷：『客裡逢新節，愁中心事饒。兒童傳賀語，破涕忽為笑！』剛才還在傷感流淚抽泣，聽到喜訊欣慰之事，淚痕未乾便情不自禁露出歡快笑容。", "quote": "聞得捷報傳來，闔家驚喜，破涕為笑。", "desc": "形容一下子停止哭泣，轉悲為喜，露出由衷笑容。", "yin": "pò tì wèi xiào"}, {"rank": 16, "idiom": "防患未然", "pinyin": "fáng huàn wèi rán", "origin": "《周易·既濟》/《樂府詩集·君子行》", "story": "君子思患而預防之。《樂府詩集》雲：『善圖事者，當於禍亂未形之先消之於無形，防患於未然，治病於未疾！』在災害禍患尚未萌芽發生之前，預先採取周密措施予以消除化解。", "quote": "明智之士，居安思危，防患於未然。", "desc": "指在事故禍患尚未發生萌芽之前，就採取預防阻絕措施。", "yin": "fáng huàn wèi rán"}, {"rank": 15, "idiom": "飲水思源", "pinyin": "yǐn shuǐ sī yuán", "origin": "北周·庾信《徵調曲》", "story": "落其實者思其樹，飲其流者懷其源。庾信客留北周思念故國江南山河，借詩抒懷：人在甘美泉流前暢飲清泉解渴之時，切切不可忘記泉水奔湧流淌的源頭所在，報恩崇本，終生不忘所自來。", "quote": "落其實者思其樹，飲其流者懷其源。", "desc": "比喻喝水的時候想起水流的源頭，比喻不忘本源，時刻感恩回報給予恩惠者。", "yin": "yǐn shuǐ sī yuán"}, {"rank": 14, "idiom": "投桃報李", "pinyin": "tóu táo bào lǐ", "origin": "《詩經·大雅·抑》", "story": "投我以桃，報之以李。彼童而角，實罔有覯。詩人告誡世人人際交接互禮之德，他人餽贈給我香甜之鮮桃，我必當以甘美之脆李回報之，禮尚往來，互重互敬，情真意切。", "quote": "投我以桃，報之以李。禮尚往來，萬民相親。", "desc": "比喻禮尚往來，友好相處，彼此互相餽贈恩德回報相酬。", "yin": "tóu táo bào lǐ"}, {"rank": 13, "idiom": "滴水穿石", "pinyin": "dī shuǐ chuān shí", "origin": "《漢書·枚乘傳》/宋·羅大經《鶴林玉露》", "story": "枚乘諫吳王曰：『泰山之溜穿石，單極之綆斷幹。水非石之鑽，索非木之鋸，漸靡使之然也。』水滴力量極其微小柔韌，然而終年累月持續不斷滴落於同一頑石之上，頑石終被滴穿鑿空。", "quote": "水滴石穿，繩鋸木斷，功夫深湛，無堅不摧。", "desc": "比喻只要意志頑強、堅持不懈地努力奮鬥，細微弱小之力也能克服千難萬險。", "yin": "dī shuǐ chuān shí"}, {"rank": 12, "idiom": "聚沙成塔", "pinyin": "jù shā chéng tǎ", "origin": "《妙法蓮華經·方便品》", "story": "佛經偈頌廣說善功功德之積累：乃至童子戲，聚沙為佛塔，如是諸人等，皆已成佛道！孩童在海灘水濱堆聚一粒粒細沙，日復一日堆積，亦能築成莊嚴巍峨之七寶佛塔。", "quote": "乃至童子戲，聚沙成塔，日積月累，終成大德。", "desc": "比喻積少成多，只要細心一點一滴長期積累，微小微薄之物也能匯聚成大成果。", "yin": "jù shā chéng tǎ"}, {"rank": 11, "idiom": "集腋成裘", "pinyin": "jí yè chéng qiú", "origin": "《燕丹子·卷下》", "story": "燕太子丹論蓄養天下勇士之厚德曰：『夫白狐之裘，非一狐之白也，乃集千百狐狸腋下寸白之皮毛匯聚而成，價值千金！』集合微薄細小的貢獻力量，終能織就人間最華麗尊貴之皮裘。", "quote": "集千狐之腋以成珍裘，合萬夫之力以立奇功。", "desc": "狐狸腋下的白毛雖少，聚集起來就能縫製成一件珍貴皮裘。比喻積少成多。", "yin": "jí yè chéng qiú"}, {"rank": 10, "idiom": "眾擎易舉", "pinyin": "zhòng qíng yì jǔ", "origin": "明·張岱《夜航船·禮樂部》", "story": "獨手難擎千斤鼎，萬夫合力如拔山。明張岱論民心向背與團結協同：重達萬斤之巨石巨鼎，一人二人斷難移動分毫；若有千萬眾人一同伸手擎舉，輕而易舉便可穩穩舉起。", "quote": "孤力難持，眾擎易舉，合天下之志以定乾坤。", "desc": "許多人合力擎舉一件重物就很容易舉起來，比喻大家齊心協力事情就容易辦成。", "yin": "zhòng qíng yì jǔ"}, {"rank": 9, "idiom": "孤掌難鳴", "pinyin": "gū zhǎng nán míng", "origin": "《韓非子·功名》", "story": "韓非子論君臣協同相輔之道曰：『人主之操柄也，如一手之拍掌。夫一隻手雖揮動神速，孤掌何能發聲鳴響？必得兩掌相合相拍，始能發出清脆震天之聲。君明臣賢相須為用，國家乃安。』", "quote": "一手獨拍，雖疾無聲。孤掌難鳴，非合力不能有濟。", "desc": "一隻巴掌拍不響，比喻單靠一個人的力量難以辦成大事，亦比喻矛盾由雙方引起。", "yin": "gū zhǎng nán míng"}, {"rank": 8, "idiom": "獨木難支", "pinyin": "dú mù nán zhī", "origin": "《水經注·沔水》/《南史》", "story": "萬仞傾頹之大廈，非一根木樁一根樑木所能單獨支撐保全。國家天下處於風雨飄搖將覆之危局，必須凝聚天下四方千萬志士仁人團結抗難，單憑孤臣一人之力實難力挽狂瀾。", "quote": "大廈之傾，非一木所能支，必聚萬木以為柱石。", "desc": "比喻重大危急的局勢，單靠個人微弱薄弱的力量難以單獨支撐挽救。", "yin": "dú mù nán zhī"}, {"rank": 7, "idiom": "唇齒相依", "pinyin": "chún chǐ xiāng yī", "origin": "《左傳·僖公五年》", "story": "宮之奇諫虞公曰：『虞虢之交，輔車相依，唇亡則齒寒，相依為命如同唇齒相保。』嘴唇覆蓋在牙齒之外保護牙齒不受寒風侵襲，二者利害生死緊密相連，互為天然屏障。", "quote": "輔車相依，唇亡齒寒，唇齒相依，生死同盟。", "desc": "形容雙方關係極其親密，利害關係緊密休慼相關，互為依靠互保。", "yin": "chún chǐ xiāng yī"}, {"rank": 6, "idiom": "休慼與共", "pinyin": "xiū qī yǔ gòng", "origin": "《左傳·昭公四年》", "story": "晉大夫叔向謂子產曰：『晉楚交兵，四方震動。昔先王協和萬邦，休慼與共，喜悅幸福共同享受，憂患危難共同承擔，天下始享昇平安康！』休者，歡慶吉慶也；戚者，憂傷患難也。", "quote": "休慼與共，同甘共苦，四海一家，萬民協和。", "desc": "形容憂喜吉凶榮辱禍福彼此共同承受承擔，關係極為親密一體。", "yin": "xiū qī yǔ gòng"}, {"rank": 5, "idiom": "患難與共", "pinyin": "huàn nán yǔ gòng", "origin": "《史記·越王句踐世家》", "story": "越滅吳，句踐大會諸侯。范蠡毅然辭相泛舟五湖，留書大夫種曰：『越王為人，長頸鳥喙，忍辱含垢，可與共患難，不可與共樂！』在生死危亡危難關頭共同抗擊風浪拼搏求存。", "quote": "結生死之交，同甘苦，共患難，萬劫不移。", "desc": "共同承擔患難災厄與艱難危險，形容友誼情深意厚堅不可摧。", "yin": "huàn nán yǔ gòng"}, {"rank": 4, "idiom": "戮力同心", "pinyin": "lù lì tóng xīn", "origin": "《左傳·成公十三年》", "story": "晉厲公會諸侯，討伐秦軍。大夫呂相宣告盟誓曰：『昔我先君莊公、憲公，與秦穆公協德同力，戮力同心，平討暴亂，申明天地之公義！』戮力者，拼盡合聚全身力量也，團結一心同赴大義。", "quote": "協德同力，戮力同心，以濟世變。", "desc": "指齊心協力，全力以赴，大家共同合聚所有力量去完成共同事業。", "yin": "lù lì tóng xīn"}, {"rank": 3, "idiom": "齊心協力", "pinyin": "qí xīn xié lì", "origin": "《墨子·尚同中》", "story": "墨子論治理邦國協調萬民之法：『天下之萬民，齊一其心思，協和其氣力，同心同德以赴公利，則雖萬仞之高山亦可移，天下無攻不克之難關也！』眾人思想目標高度一致，力量合而為一。", "quote": "齊心協力，同舟共濟，天下大定。", "desc": "指眾人想法心志一致，共同竭盡力量共同完成某項事業任務。", "yin": "qí xīn xié lì"}, {"rank": 2, "idiom": "和衷共濟", "pinyin": "hé zhōng gòng jì", "origin": "《尚書·皋陶謨》", "story": "皋陶謨曰：『同寅協恭，和衷哉！天命有德，五服五章哉！』衷者，內心深處至誠之善念天性也。四海臣民各抱精誠至和之善心，同心協同渡過驚濤駭浪的大江大海。", "quote": "同寅協恭，和衷共濟，同德同心，克撫萬邦。", "desc": "指大家懷著至誠和睦的心願，齊心協力共同克服艱難險阻渡過危局。", "yin": "hé zhōng gòng jì"}, {"rank": 1, "idiom": "海納百川", "pinyin": "hǎi nà bǎi chuān", "origin": "《管子·形勢解》/清·林則徐題堂聯", "story": "《管子》曰：『海不辭水，故能成其大；山不辭土石，故能成其高。』清林則徐更總結平生胸襟抱負題千古名聯曰：『海納百川，有容乃大；壁立千仞，無欲則剛！』茫茫滄海容納包容天下千百條江河巨流，終成浩瀚無垠之宏偉氣象。", "quote": "海納百川，有容乃大；壁立千仞，無欲則剛。", "desc": "比喻心胸博大無比，能廣泛包容包納一切不同的意見、人才與博大智慧。", "yin": "hǎi nà bǎi chuān"}];
